Table_Dialog_Left_44 = {
  [130001] = "{id=130001,Text='冒险者，干的漂亮！现在你可以离开这里了！',Speaker=1019,}",
  [131001] = "{id=131001,Text='愚蠢的人类，看看你都干了些什么！竟敢放肆屠戮我的子民们，准备接受我的怒火吧！',Speaker=2278,}",
  [131002] = "{id=131002,Text='冒险者！你要为你的行为付出惨痛的代价！',Speaker=2278,Option='安抚蛇妖',}",
  [131007] = "{id=131007,Text='冒险者，这里可不是随便可以进出的，如果没有重要的事情，请你离开这里！',Speaker=1022,}",
  [131008] = "{id=131008,Text='尊敬的内务官，我是奉海陆曼将军的命令来到这里。',}",
  [131009] = "{id=131009,Text='梦罗克已经被巴风特麾下魔物攻陷，现在城里已经乱成一团，海陆曼团长让我请求支援。',}",
  [131010] = "{id=131010,Text='什么？梦罗克被攻陷了？！我这就组织援军。冒险者，你去找[c][ffff00]希盖伊兹[-][/c]，请他们出手！',Speaker=1022,Option='好的',}",
  [131011] = "{id=131011,Text='冒险者，你来这里有什么事吗？',Speaker=1024,}",
  [131012] = "{id=131012,Text='梦罗克已经被巴风特麾下魔物攻陷，内务官请我来找你，希望你能够前往梦罗克城帮忙！',}",
  [131013] = "{id=131013,Text='我明白了！我这就组织大家前去帮忙，请你先返回梦罗克，告诉[c][ffff00]海陆曼团长[-][/c]，我们一会就到！',Speaker=1024,Option='好的',}",
  [131016] = "{id=131016,Text='很不好。冒险者，请你先行入城，我组织好军队立刻就会前去援助你。',Speaker=1221,Option='好的',}",
  [131017] = "{id=131017,Text='冒险者，我要提醒你，之后的挑战你可能会有生命危险，为了不让你白白送死，我决定要考验一下你。',Speaker=1140,Option='尽管来！',}",
  [131018] = "{id=131018,Text='在沉船中有一个[c][ffff00]剧毒魔菇[-][/c]，干掉他，向我证明你的实力！',Speaker=1140,}",
  [131019] = "{id=131019,Text='很好，冒险者，你的实力很不错。我可以放心的把任务交给你。',Speaker=1140,}",
  [131034] = "{id=131034,Text='一股温润的力量洗涤着我的身躯，伤口在这力量汹涌中痊愈……',}",
  [131035] = "{id=131035,Text='谢谢你，[c][ffff00][PlayerName][-][/c]，我们好多了！不过我们还不能走。',Speaker=1368,}",
  [131036] = "{id=131036,Text='研究现在到了关键时刻，你能帮我去毒魔菇身上取一些[c][ffff00]魔粉[-][/c]吗？这对我们的研究非常重要。',Speaker=1368,Option='乐意效劳。',}",
  [131037] = "{id=131037,Text='谢谢你，[c][ffff00][PlayerName][-][/c]，解毒剂来的很及时。',Speaker=1142,}",
  [131038] = "{id=131038,Text='离开这里？不行，只要再取得骷髅的[c][ffff00]遗骨[-][/c]，我们的研究就会很快取得突破！',Speaker=1142,Option='交给我吧',}",
  [131039] = "{id=131039,Text='谢谢你，有了这个我们的研究很快就会有突破！',Speaker=1367,}",
  [131040] = "{id=131040,Text='这么快，冒险者，你很厉害啊，好了，把东西交给我，很快就会有结果了。',Speaker=1368,}",
  [131041] = "{id=131041,Text='东西呢？给我给我，这下研究材料都弄齐了……',Speaker=1142,}",
  [131042] = "{id=131042,Text='快把这个消息告诉洛克吧！',Speaker=1142,}",
  [131043] = "{id=131043,Text='你回来了？研究员们都安全吗？',Speaker=1132,Option='都很安全',}",
  [131044] = "{id=131044,Text='冒险者？第三层很危险，你来做什么？',Speaker=1135,}",
  [131045] = "{id=131045,Text='突然大叫吓着我了……骷髅就是你自己啊！',}",
  [131046] = "{id=131046,Text='我不信！一定是…没错，一定是罗达蛙恶心的[c][ffff00]毒液[-][/c]才让我产生了幻觉，帮我击败他们！',Speaker=1136,}",
  [131047] = "{id=131047,Text='不可能，我怎么会变成骷髅！不可能…',Speaker=1136,}",
  [131048] = "{id=131048,Text='这就是事实啊…接受现实吧…',}",
  [131049] = "{id=131049,Text='线索的话…你可以尝试前往左侧房间进行调查。',Speaker=1141,}",
  [131050] = "{id=131050,Text='右侧房间也许有你需要的线索，不过，冒险者，一切小心。',Speaker=1141,}",
  [131051] = "{id=131051,Text='找到了线索就赶紧告诉哈维吧。',Speaker=1141,}",
  [131055] = "{id=131055,Text='尊敬的贵客，你听到了么？那种\"沙沙——\"的声音……',Speaker=1353,Option='听到了。',}",
  [131056] = "{id=131056,Text='妙勒尼山脉中的蜈蚣是有着自己的首领的，你消灭了这么多蜈蚣，我猜[c][ffff00]艾吉欧蜈蚣首领[-][/c]要找上你了。',Speaker=1353,}",
  [131057] = "{id=131057,Text='尊敬的贵客，请原谅我的胆小，你必须消灭它，这样我才能安心提炼元素。',Speaker=1353,Option='好的',}",
  [131063] = "{id=131063,Text='你干的很不错！现在你可以去找找线索了。旁边的两位骑士可能会有些线索要告诉你。',Speaker=1135,}",
  [131064] = "{id=131064,Text='总算干掉了这些烦人的幽灵了……我来看看我找到了什么……唔，得赶快把线索带回去。',}",
  [131066] = "{id=131066,Text='这里是普勒花园，看着风景，真是令人迷醉啊！',}",
  [131067] = "{id=131067,Text='说起来西门还隐藏着一个骑士的“劲敌”呢！',}",
  [363000] = "{id=363000,Text='美之宫3默认dialog占坑',}",
  [363007] = "{id=363007,Text='小心！',Speaker=821714,}",
  [363008] = "{id=363008,Text='好险……果然这里也有机关。',Speaker=821714,}",
  [363009] = "{id=363009,Text='幸好带你躲过了。',Speaker=821714,}",
  [363010] = "{id=363010,Text='来，快走吧！目标是找到贡露！',Speaker=821714,}",
  [363012] = "{id=363012,Text='这里的排列和5点钟房间的好像有点像…',Speaker=821714,}",
  [363013] = "{id=363013,Text='...要不我们去看看？',Speaker=821714,}",
  [363601] = "{id=363601,Text='朕要找個隱蔽的角落休養生息，不要打擾朕……',Speaker=501810,}",
  [363602] = "{id=363602,Text='大功告成，你怎麼那麼優秀！',Speaker=501810,}",
  [363603] = "{id=363603,Text='等等，不是我的錯，我可以解釋！',Speaker=501810,}",
  [363604] = "{id=363604,Text='賞妳啦，不用謝朕。',Speaker=501810,}",
  [363605] = "{id=363605,Text='拜託，都那麼熟了，第一次知道我厲害啊？',Speaker=501810,}",
  [363606] = "{id=363606,Text='可惜你我人鬼殊途……',Speaker=501810,}",
  [363607] = "{id=363607,Text='不要因為我在閒著，就當我吃素的哦。',Speaker=501810,}",
  [363608] = "{id=363608,Text='貢品不錯，朕很滿意！',Speaker=501810,}",
  [363701] = "{id=363701,Text='呼——暂时休息！',Speaker=501850,}",
  [363702] = "{id=363702,Text='呼呼……太好了，是不错的结果。',Speaker=501850,}",
  [363703] = "{id=363703,Text='没事的，我们改天再试试……',Speaker=501850,}",
  [363704] = "{id=363704,Text='一点心意……希望主人喜欢。',Speaker=501850,}",
  [363705] = "{id=363705,Text='呼呼——看我把他们都踏平！',Speaker=501850,}",
  [363706] = "{id=363706,Text='主人……你醒醒！！',Speaker=501850,}",
  [363707] = "{id=363707,Text='呼……呼呼……有点……瞌睡……',Speaker=501850,}",
  [363708] = "{id=363708,Text='我很喜欢，谢谢主人……！',Speaker=501850,}",
  [392151] = "{id=392151,Text='Skill/Eff_Ninja_DevilDart_atk     播放完毕',}",
  [393892] = "{id=393892,Voice='Npc/vox_emoghost_fear_1',Text='唉哟！大事不好了！',Speaker=826001,}",
  [393893] = "{id=393893,Text='灯灯灯灯灯灯不见了呀！',Speaker=826001,}",
  [393894] = "{id=393894,Text='剧院里，最重要！最美丽！充满魔法的华丽的水晶吊灯不见了呀！',Speaker=826001,}",
  [393895] = "{id=393895,Voice='Npc/vox_emoghost_disgust_1',Text='那个烦人的闹闹！为了干扰我们排练，真是什么事都做得出来啊！',Speaker=826002,}",
  [393896] = "{id=393896,Voice='Npc/vox_emoghost_angry_2',Text='我说要把它的屁股揍上一顿，你们非得拦着我！现在好了，灯都没了！',Speaker=826003,}",
  [393897] = "{id=393897,Text='谁让你们要排演无聊的节目啊！谁认识那个叫特什么坦的！要排就排《风流王子俏女仆》啊！',Speaker=826004,}",
  [393898] = "{id=393898,Voice='Npc/vox_emoghost_angry_2',Text='我忍受不了了……还是揍它一顿吧！',Speaker=826003,}",
  [393899] = "{id=393899,Text='总之！我已经把灯拆开藏在皇宫的各个角落！不承认错误的话，就别想找到！',Speaker=826004,}",
  [393900] = "{id=393900,Text='这下怎么办？没有灯……舞台就没有魔法了……这下没戏了。',Speaker=826001,}",
  [393901] = "{id=393901,Text='被人类盯着看，真是讨厌……',Speaker=826002,}",
  [393902] = "{id=393902,Voice='Npc/vox_emoghost_fear_1',Text='你怎么能看到我们！？',Speaker=826001,}",
  [393903] = "{id=393903,Text='别慌！我去把他打晕！',Speaker=826003,}",
  [393904] = "{id=393904,Text='等一下！……',Speaker=826005,}",
  [393905] = "{id=393905,Text='只有清澈无邪的眼睛，才能看到我们……',Speaker=826005,}",
  [393906] = "{id=393906,Text='拥有一双慧眼的冒险者，请帮帮我们！',Speaker=826005,}",
  [393909] = "{id=393909,Text='这可是伟大的特里斯坦一世的故事啊！',Speaker=826005,Option='哦？',}",
  [393911] = "{id=393911,Text='果然……在年轻人中已经鲜为人知了。小闹闹也跟你一样，不知道特里斯坦的传说……',Speaker=826005,}",
  [393928] = "{id=393928,Text='很久以前…… 我最讨厌以[很久以前……]开场的故事了！',Speaker=826004,}",
  [393929] = "{id=393929,Text='嘘！继续念，别出戏呀！',Speaker=826005,}",
  [393930] = "{id=393930,Text='很久以前……英雄们从魔王手中拯救了米德加尔特。',Speaker=826004,}",
  [393931] = "{id=393931,Text='初代国王亚当，建立了伊甸王国，人类第一次拥有了自己的国度。',Speaker=826004,}",
  [393932] = "{id=393932,Text='人类在米德加尔德的生活自由且幸福，直到……',Speaker=826004,}",
  [393933] = "{id=393933,Text='亚当国王故去，他的儿子该隐，为了争夺权力，不择手段——',Speaker=826004,}",
  [393934] = "{id=393934,Text='他的野心肆意膨胀，不允许任何违抗他意志的人出现。',Speaker=826004,}",
  [393935] = "{id=393935,Text='自由已死，黑暗和恐惧弥漫在整个人类世界。',Speaker=826004,}",
  [393936] = "{id=393936,Text='正在这至暗时刻，一位英雄悄然诞生……',Speaker=826004,}",
  [393948] = "{id=393948,Text='仲夏夜的晚上，一位神父被敲门声惊醒。',Speaker=826003,}",
  [393949] = "{id=393949,Text='发现一只装着婴儿的篮子被遗弃在修道院的门前。',Speaker=826003,}",
  [393950] = "{id=393950,Text='婴儿在篮子里熟睡。旁边还有一封信，和一把带鞘的剑。',Speaker=826003,}",
  [393951] = "{id=393951,Text='信上只有两行字：孩子名为特里斯坦。如果他顺利长大，请把剑交给他。',Speaker=826003,}",
  [393952] = "{id=393952,Text='一晃多年，特里斯坦在神的庇荫下顺利长大，还在修道院结交了毕生的好友。',Speaker=826003,}",
  [393953] = "{id=393953,Text='从小乐于助人的特里斯坦，渐渐发现修道院外的世界是如此黑暗不公。',Speaker=826003,}",
  [393954] = "{id=393954,Text='他与好友格里高利瞒着神父，经常偷偷溜出修道院。',Speaker=826003,}",
  [393955] = "{id=393955,Text='他们劫掠恶人的财宝，施舍贫苦的百姓。人们赞扬他们的善举，却也为他们担心。',Speaker=826003,}",
  [393956] = "{id=393956,Text='“谁都不愿意做的事，就由我特里斯坦来做吧。”他如是说。',Speaker=826003,}",
  [393957] = "{id=393957,Text='他知道会被邪恶报复。他不害怕，是因为他还不知道，报复会找到他在乎的人。',Speaker=826003,}",
  [393966] = "{id=393966,Text='特里斯坦的传闻传到皇帝该隐的耳中。这是对他制定的规则，赤裸裸的挑衅和破坏。',Speaker=826004,}",
  [393983] = "{id=393983,Text='出色的人们总是相互吸引，彼此欣赏。',Speaker=826004,}",
  [393984] = "{id=393984,Text='商人马可波罗自从那晚救出特里斯坦，终其一生都追随左右。',Speaker=826004,}",
  [393985] = "{id=393985,Text='慕名而来，志同道合的伙伴越来越多，盗贼邦妮、吟游诗人丘比特，以及……',Speaker=826004,}",
  [393986] = "{id=393986,Text='特里斯坦一生中的挚爱——法师玛姬。',Speaker=826004,}",
  [393987] = "{id=393987,Text='他们都被乱世压迫，心怀同样的仇恨，发誓要了结这一切。',Speaker=826004,}",
  [393988] = "{id=393988,Text='因为这些好伙伴的帮助，特里斯坦褪去了青涩和鲁莽，成长为一名真正的领袖。',Speaker=826004,}",
  [393989] = "{id=393989,Text='他们没有因为极尽的赞美和成功的喜悦而停下脚步。',Speaker=826004,}",
  [393990] = "{id=393990,Text='因为他们知道，不解决最终的问题，这一切都是暂时的。',Speaker=826004,}",
  [393994] = "{id=393994,Text='决战时刻终于来临。',Speaker=826004,}",
  [393995] = "{id=393995,Text='敌人如潮水般涌向英雄们，但英雄们无所畏惧，历经重重磨难的历练，',Speaker=826004,}",
  [393996] = "{id=393996,Text='他们已今非昔比，往日强大的对手已经不堪一击。',Speaker=826004,}",
  [393997] = "{id=393997,Text='他们自信满满，势在必得，',Speaker=826004,}",
  [393998] = "{id=393998,Text='却没有想到该隐已经彻底投入黑暗的麾下。',Speaker=826004,}",
  [393999] = "{id=393999,Text='看到伙伴们一个一个地倒下，特里斯坦的宝剑发出光芒，敌人在刺眼的光芒中湮没。',Speaker=826004,}",
  [394000] = "{id=394000,Text='黑云散去，光明重新笼罩了米德加尔德。战争结束了，但那些迷惘的人们，又该何去何从？',Speaker=826004,}",
  [394001] = "{id=394001,Text='伊甸消失了，现在，哪里是属于他们的国度呢？',Speaker=826004,}",
  [394005] = "{id=394005,Text='人们簇拥着特里斯坦，拥护他当伊甸的皇帝，他却拒绝了。',Speaker=826004,}",
  [394006] = "{id=394006,Text='“全人类的意志不应当服从于一个人——',Speaker=826004,}",
  [394007] = "{id=394007,Text='“但是，如果你们相信我的选择，那我们可以像朋友一样，为我们共同的信仰而努力。”',Speaker=826004,}",
  [394008] = "{id=394008,Text='人们聚集在特里斯坦身边，建立卢恩王国，修建了普隆德拉城。他们坚韧、传统，爱好和平，珍视友谊，敬畏神灵。',Speaker=826004,}",
  [394009] = "{id=394009,Text='拥有不同理想和信念的人，也都在其他的国度，找到了他们的归宿。',Speaker=826004,}",
  [394010] = "{id=394010,Text='普隆德拉也受到万物的庇佑，在米德加尔德中心伫立千年。',Speaker=826004,}",
  [394011] = "{id=394011,Text='特里斯坦虽然早已故去，但他的精神成为卢恩王国的根基。',Speaker=826004,}",
  [394012] = "{id=394012,Text='冒险者特里斯坦和卢恩国王特里斯坦究竟有什么不同呢？',Speaker=826004,}",
  [394013] = "{id=394013,Text='区别之在于，他当了国王之后，就能帮助更多的人。',Speaker=826004,}",
  [394035] = "{id=394035,Text='第一幕',}",
  [394036] = "{id=394036,Text='第二幕',}",
  [394037] = "{id=394037,Text='第三幕',}",
  [394038] = "{id=394038,Text='第四幕',}",
  [394039] = "{id=394039,Text='第五幕',}",
  [394040] = "{id=394040,Text='第六幕',}",
  [394041] = "{id=394041,Text='但是在那天，他们都没能打败对方。',Speaker=826004,}",
  [396213] = "{id=396213,Text='你知道最近整个虚空领域有大事要发生了吗？',Speaker=294224,}",
  [396214] = "{id=396214,Text='月光派对要再次举办了！月光派对你不会没听说过吧？',Speaker=294224,}",
  [396215] = "{id=396215,Text='那我就勉为其难地带你去参与一次吧！',Speaker=294224,}",
  [396216] = "{id=396216,Text='在月光笼罩的虚空之下翩翩起舞，多么美妙~',Speaker=294224,}",
  [396217] = "{id=396217,Text='我精心挑选了舞伴，看，这墓碑很结实吧！',Speaker=294224,}",
  [396218] = "{id=396218,Text='迫不及待让那群家伙看看我派对之王的舞姿！',Speaker=294224,}",
  [396219] = "{id=396219,Text='离我远点！',Speaker=294224,}",
  [396220] = "{id=396220,Text='别碰我舞伴！',Speaker=294224,}",
  [396221] = "{id=396221,Text='走开！',Speaker=294224,}",
  [396222] = "{id=396222,Text='派对之王 播放表情 左看右看',Speaker=294224,}",
  [396223] = "{id=396223,Text='错误的地点！',Speaker=294224,}",
  [396224] = "{id=396224,Text='哦！太好了！我们赶上了月光派对！',Speaker=294224,}",
  [396225] = "{id=396225,Text='差一点！差一点！我们就要错过月光派对了！',Speaker=294224,}",
  [396226] = "{id=396226,Text='救命！救命！',Speaker=294224,}",
  [396227] = "{id=396227,Text='谁能帮我烧断这荆棘！',Speaker=294224,}",
  [396228] = "{id=396228,Text='太感谢了！',Speaker=294224,}",
  [396229] = "{id=396229,Text='都怪那个稻草人！',Speaker=294224,}",
  [396230] = "{id=396230,Text='害的我们没饭吃！',Speaker=294224,}",
  [396231] = "{id=396231,Text='谁能帮我们拆掉它！',Speaker=294224,}",
  [396232] = "{id=396232,Text='谢谢！',Speaker=294224,}",
  [396233] = "{id=396233,Text='谢谢！',Speaker=294224,}",
  [396234] = "{id=396234,Text='谢谢！',Speaker=294224,}",
  [396235] = "{id=396235,Text='可恶的人类！',Speaker=294224,}",
  [396236] = "{id=396236,Text='等我修行完成！',Speaker=294224,}",
  [396237] = "{id=396237,Text='人类就受死吧！',Speaker=294224,}",
  [396238] = "{id=396238,Text='嘤，不敢了！',Speaker=294224,}",
  [396239] = "{id=396239,Text='再也不敢了！',Speaker=294224,}",
  [396240] = "{id=396240,Text='呜呜……妈妈……',Speaker=294224,}",
  [396241] = "{id=396241,Text='谁来帮帮我……',Speaker=294224,}",
  [396242] = "{id=396242,Text='呜……好可怕……',Speaker=294224,}",
  [396243] = "{id=396243,Text='谢谢你！大英雄！',Speaker=294224,}",
  [396244] = "{id=396244,Text='你们……走开！',Speaker=294224,}",
  [396245] = "{id=396245,Text='我……我很厉害的！',Speaker=294224,}",
  [396246] = "{id=396246,Text='退——退——退！',Speaker=294224,}",
  [396247] = "{id=396247,Text='冒险真是太可怕了！',Speaker=294224,}",
  [396248] = "{id=396248,Text='可恶的小偷鸟！',Speaker=294224,}",
  [396249] = "{id=396249,Text='我的包袱……我的ZENY……',Speaker=294224,}",
  [396250] = "{id=396250,Text='我可太丢盗贼的脸了！',Speaker=294224,}",
  [396251] = "{id=396251,Text='嘘——替我保密哦！',Speaker=294224,}",
  [396252] = "{id=396252,Text='咯咯哒！强盗！',Speaker=294224,}",
  [396253] = "{id=396253,Text='叽叽…黑蛇来了！',Speaker=294224,}",
  [396254] = "{id=396254,Text='咯咯哒！抢劫了！',Speaker=294224,}",
  [396255] = "{id=396255,Text='叽叽…黑蛇坏坏！',Speaker=294224,}",
  [396256] = "{id=396256,Text='咯咯哒！咯咯哒！',Speaker=294224,}",
  [396257] = "{id=396257,Text='叽叽！叽叽！',Speaker=294224,}",
  [396258] = "{id=396258,Text='咯咯哒！谢谢！',Speaker=294224,}",
  [396313] = "{id=396313,Text='化为尘土，不代表一切的结束。',Speaker=502020,}",
  [396314] = "{id=396314,Text='鲸落万物生。',Speaker=502020,}",
  [396315] = "{id=396315,Text='岩石都能感受到的喜悦。',Speaker=502020,}",
  [396316] = "{id=396316,Text='无妨，只是时间长河中的小意外。',Speaker=502020,}",
  [396317] = "{id=396317,Text='磐石之心，等待召唤。',Speaker=502020,}",
  [396318] = "{id=396318,Text='岁月沉积的馈赠而已。',Speaker=502020,}",
  [396319] = "{id=396319,Text='时间与空间的产物是如此美味。',Speaker=502020,}",
  [396320] = "{id=396320,Text='新练的招式，怎么样？打一场？',Speaker=502020,}",
  [396321] = "{id=396321,Text='可恶，任务失败。',Speaker=502020,}",
  [396322] = "{id=396322,Text='任务完成。',Speaker=502020,}",
  [396323] = "{id=396323,Text='必然的结果。',Speaker=502020,}",
  [396324] = "{id=396324,Text='只是一次偶然。',Speaker=502020,}",
  [396325] = "{id=396325,Text='我不离太远。',Speaker=502020,}",
  [396326] = "{id=396326,Text='旅途中要及时补充物资。',Speaker=502020,}",
  [396327] = "{id=396327,Text='就当是佣金了。',Speaker=502020,}",
  [396328] = "{id=396328,Text='乌龟岛之外，竟是这样的……',Speaker=502020,}",
  [396329] = "{id=396329,Text='唔……再一次……没能守护……',Speaker=502020,}",
  [396330] = "{id=396330,Text='侵入者，杀。',Speaker=502020,}",
  [396331] = "{id=396331,Text='这样，就能更好的守护了吧。',Speaker=502020,}",
  [396332] = "{id=396332,Text='我也曾经失败，但奎勒告诉我失败并不可怕。',Speaker=502020,}",
  [396333] = "{id=396333,Text='那么，下次再见。',Speaker=502020,}",
  [396334] = "{id=396334,Text='奎勒说过，礼物代表着心意。',Speaker=502020,}",
  [396335] = "{id=396335,Text='谢谢……好久没有收到礼物了……',Speaker=502020,}",
  [396352] = "{id=396352,Text='冒险者，千万要小心，来自远古的恐怖气息让镜子外的我都忍不住颤抖啊。',Speaker=821522,}",
  [396353] = "{id=396353,Text='这……这就是恢复了全部力量的幻龙吗？好可怕。',Speaker=821522,}",
  [396354] = "{id=396354,Text='看来传说是真的，这面带有魔女之力的镜子会复活真正的远古魔物。',Speaker=821522,}",
  [396355] = "{id=396355,Text='这是远古勇士战团的守护！难、难道他们也复活了吗？',Speaker=821522,}",
  [396356] = "{id=396356,Text='这些水晶似乎是镜中世界的镜核，必须要尽快打破，否则幻龙会获得更多魔女的力量！',Speaker=821522,}",
  [396357] = "{id=396357,Text='糟糕，幻龙准备和你们同归于尽了……怎么办，不会出事吧……',Speaker=821522,}",
  [396358] = "{id=396358,Text='吼！丑陋又弱小的生物，竟敢将吾等尸骨任人参观！该死！！！',Speaker=276100,}",
  [396359] = "{id=396359,Text='感受到痛苦了吗？哀嚎吧，尽情哀嚎，用你们的惨叫来取悦吾。',Speaker=276100,}",
  [396360] = "{id=396360,Text='吾的人类博物馆刚好缺一些标本，你们是自寻死路！',Speaker=276100,}",
  [396361] = "{id=396361,Text='不！！！吾不会死，吾……不会……',Speaker=276100,}",
  [396362] = "{id=396362,Text='最、最大的——水晶——我、我来！',Speaker=276120,}",
  [396363] = "{id=396363,Text='打、打碎了——你、你们先——撑住！',Speaker=276120,}",
  [396364] = "{id=396364,Text='一群虚张声势的家伙，长了翅膀的可怜虫们！群星陨落！！！',Speaker=276130,}",
  [396365] = "{id=396365,Text='衣着古怪的外来者们，剩下的你们应该可以解决吧？',Speaker=276130,}",
  [396366] = "{id=396366,Text='这个家伙开始垂死挣扎了吗？又到了祖尔小队出场的时候！',Speaker=276140,}",
  [396389] = "{id=396389,Text='动力炉要损坏了！请快速修复它！',Speaker=9455,}",
  [396390] = "{id=396390,Text='有哥布灵正要攻击动力炉，注意保护！',Speaker=9455,}",
  [396391] = "{id=396391,Text='注意后方！史汀正要偷窃物资！',Speaker=9455,}",
  [396393] = "{id=396393,Text='在飞空艇运送物资的过程中，一定会有很多魔物前来阻挠，冒险者你们要做的就是尽快清除那些魔物。',Speaker=9455,}",
  [396394] = "{id=396394,Text='飞空艇上魔物的数量越多，飞空艇航行的速度就会越慢，那我们面临的危险也就越高。',Speaker=9455,}",
  [396395] = "{id=396395,Text='还需要格外留意的就是飞空艇上的几个装置。首先是中央甲板的动力炉，一旦遭到魔物破坏，飞空艇的速度上限就会降低。此时需要有人靠近动力炉来进行修复，但是要注意每次修复有冷却时间限制。',Speaker=9455,}",
  [396396] = "{id=396396,Text='其次要注意保护后方甲板的物资，如果被魔物窃取会扣除结算分数。',Speaker=9455,}",
  [396397] = "{id=396397,Text='最后飞空艇上还有一些装置可以协助你们战斗。动力炉旁边的激光装置触发之后可以对全场魔物造成晕眩的效果，注意有使用冷却时间限制；前方甲板两侧的大炮触发后可以击败飞空艇旁边飞行的魔物。',Speaker=9455,}",
  [396398] = "{id=396398,Text='冒险者请尽快清除魔物，不然飞空艇的速度会越来越慢的！',Speaker=9455,}",
  [396399] = "{id=396399,Text='冒险者准备好了吗，白星飞空艇要启动了！',Speaker=9455,Option='{启动飞空艇,2},{聆听航行说明,3}',}",
  [396406] = "{id=396406,Text='狂暴的地龙已经入侵营地！请前往救援！',Speaker=840022,}",
  [396462] = "{id=396462,Text='听说你能完美的完成每一次骑士团的任务，我很欣赏你！！因此请接受我的挑战吧！',Speaker=840048,}",
  [396463] = "{id=396463,Text='我对你的能力十分感兴趣！来吧，为了忠诚而战！',Speaker=840048,}",
  [396464] = "{id=396464,Text='腐化！腐化！快使用王国之剑驱散……',Speaker=840022,}",
  [396466] = "{id=396466,Text='你如传闻中一样厉害。',Speaker=840048,}",
  [396482] = "{id=396482,Text='守卫者也需要被守卫。',Speaker=840056,}",
  [396502] = "{id=396502,Text='真是太吓人了……呼……',Speaker=840067,}",
  [396505] = "{id=396505,Text='你会知道谁才是真正的神。',Speaker=840067,}",
  [396506] = "{id=396506,Text='让一切都毁灭吧！',Speaker=840067,}",
  [396507] = "{id=396507,Text='愿世间仍存在美好。',Speaker=840071,}",
  [396513] = "{id=396513,Text='妈妈说，有了呢喃花，爸爸就会回来了……',Speaker=840072,}",
  [396515] = "{id=396515,Text='去吧！战斗吧！',Speaker=840077,}",
  [396524] = "{id=396524,Text='呃啊……',Speaker=840078,}",
  [396526] = "{id=396526,Text='永远追随立典拉德！',Speaker=840078,}",
  [396531] = "{id=396531,Text='明天和黑暗谁会先来。',Speaker=840403,}",
  [396535] = "{id=396535,Text='这群该死的狂暴卫兵！',Speaker=840402,}",
  [396539] = "{id=396539,Text='立典拉德默认对话',Speaker=840406,}",
  [396540] = "{id=396540,Text='很高兴认识你！你的英勇事迹早已在这个王国传颂，我在你身上看到了一种少有的贵族气息。',Speaker=840406,}",
  [396541] = "{id=396541,Text='如果你愿意与我一战，将是我的荣幸。',Speaker=840406,}",
  [396542] = "{id=396542,Text='你和我想象中一样强大。',Speaker=840406,}",
  [396543] = "{id=396543,Text='下一次再见，我希望能与你并肩作战！',Speaker=840406,}",
  [396545] = "{id=396545,Text='太菜了，骑士团原来都是垃圾',}",
  [396562] = "{id=396562,Text='人类的贪婪，会毁了整个大陆！',Speaker=20054,}",
  [396563] = "{id=396563,Text='毁掉吧，毁灭一切！！！',Speaker=30069,}",
  [396564] = "{id=396564,Text='黑夜，将吞噬理智和良知……',Speaker=30070,}",
  [396566] = "{id=396566,Text='圣诞节人人平等，或许我也该为自己挑选一些礼物啦。',Speaker=2050220,}",
  [396575] = "{id=396575,Text='老大，不行我们跑路吧……',Speaker=2050220,}",
  [396576] = "{id=396576,Text='是啊老大，感觉不妙啊！',Speaker=2050220,}",
  [396577] = "{id=396577,Text='咦？老大呢？？',Speaker=2050220,}",
  [396578] = "{id=396578,Text='冒险者们，剩下的就让我来帮你们消灭吧！',Speaker=842310,}",
  [396579] = "{id=396579,Text='可恶！你们等着！！！',Speaker=2050220,}",
  [396580] = "{id=396580,Text='我们要出发咯！',Speaker=842310,}",
  [396581] = "{id=396581,Text='早去早回！',Speaker=850031,}",
  [396582] = "{id=396582,Text='好期待呀。',Speaker=850031,}",
  [396583] = "{id=396583,Text='圣门永存！',Speaker=850031,}",
  [396584] = "{id=396584,Text='呜呼……',Speaker=850031,}",
  [396585] = "{id=396585,Text='冒险者们，快把礼物搬上马车吧~',Speaker=842310,}",
  [396586] = "{id=396586,Text='正在等你呢！',Speaker=850031,}",
  [396587] = "{id=396587,Text='搬走礼物吧。',Speaker=850031,}",
  [396588] = "{id=396588,Text='加油，加油……',Speaker=850031,}",
  [396589] = "{id=396589,Text='辛苦辛苦！',Speaker=850031,}",
  [396590] = "{id=396590,Text='嘿咻嘿咻……',Speaker=850031,}",
  [396591] = "{id=396591,Text='礼物真不少！',Speaker=850031,}",
  [396592] = "{id=396592,Text='搞什么鬼。',Speaker=850031,}",
  [396593] = "{id=396593,Text='魔物拦路。',Speaker=850031,}",
  [396594] = "{id=396594,Text='讨厌也……',Speaker=850031,}",
  [396595] = "{id=396595,Text='赶走它们！',Speaker=850031,}",
  [396596] = "{id=396596,Text='可恶！',Speaker=850031,}",
  [396597] = "{id=396597,Text='太酷了！',Speaker=850031,}",
  [396598] = "{id=396598,Text='好棒。',Speaker=850031,}",
  [396599] = "{id=396599,Text='可以回家了。',Speaker=850031,}",
  [396600] = "{id=396600,Text='谢谢啦',Speaker=850031,}",
  [396601] = "{id=396601,Text='瑞斯拜！',Speaker=850031,}",
  [396602] = "{id=396602,Text='冒险者们，快把礼物搬上马车吧~',Speaker=842310,}",
  [396603] = "{id=396603,Text='搬走吧。',Speaker=850031,}",
  [396604] = "{id=396604,Text='这是准备很久的礼物。',Speaker=850031,}",
  [396605] = "{id=396605,Text='小心一点。',Speaker=850031,}",
  [396606] = "{id=396606,Text='拜托了。',Speaker=850031,}",
  [396607] = "{id=396607,Text='雪会带来好运。',Speaker=850031,}",
  [396608] = "{id=396608,Text='孩子们会开心的。',Speaker=850031,}",
  [396609] = "{id=396609,Text='叮叮当……',Speaker=850031,}",
  [396610] = "{id=396610,Text='哎呀呀，是礼物呀',Speaker=850031,}",
  [396611] = "{id=396611,Text='礼物礼物！',Speaker=850031,}",
  [396612] = "{id=396612,Text='谢谢冒险者。',Speaker=850031,}",
  [396613] = "{id=396613,Text='好棒，礼物来咯！',Speaker=850031,}",
  [396614] = "{id=396614,Text='嘟噜噜……礼物！',Speaker=850031,}",
  [396615] = "{id=396615,Text='他们来啦！',Speaker=850031,}",
  [396616] = "{id=396616,Text='耶！过圣诞节啦！',Speaker=850031,}",
  [396617] = "{id=396617,Text='哥哥等等我！',Speaker=850031,}",
  [396618] = "{id=396618,Text='孩子们，慢点跑',Speaker=850031,}",
  [396619] = "{id=396619,Text='注意安全孩子们',Speaker=850031,}",
  [396620] = "{id=396620,Text='我们先等圣诞马车过去~',Speaker=850031,}",
  [396621] = "{id=396621,Text='战线搬家注意事项：\n1.公会搬家需要消耗公会中%s\n2.搬家耗时约2小时，有一定延迟\n3.公会战前2小时至城池结算期结束期间不可申请战线搬家\n4.搬家后将失去原城池，会影响公会战连续占领奖励与公会战巅峰决战参赛资格',Speaker=842088,}",
  [396622] = "{id=396622,Text='请找回…我的记忆…',Speaker=20055,}",
  [602143] = "{id=602143,Text='属下前来复命！',Speaker=807998,}",
  [602144] = "{id=602144,Text='胆敢闯入洛阳，你们想明白自己会付出的代价了吗？！',Speaker=807995,}",
  [602145] = "{id=602145,Text='命运之门已然开启，快走！',Speaker=807994,}",
  [602146] = "{id=602146,Text='时空错位，巨龙苏醒了，我们快点离开……',Speaker=807994,}",
  [602147] = "{id=602147,Voice='Npc/luoyangopening_vocal_mix',Text='我到底应该怎么做……',Speaker=807997,}",
  [602148] = "{id=602148,Text='你…为何而来？',Speaker=807996,}",
  [602149] = "{id=602149,Text='是你吗，预言里的救世者……',Speaker=807995,}",
  [602150] = "{id=602150,Text='转向测试，请选择测试类型',Speaker=802162,Option='{野外场景,2},{副本,3}',}",
  [603153] = "{id=603153,Text='你刚刚为什么哭了？',Speaker=808063,}",
  [603154] = "{id=603154,Text='没什么……',Speaker=808135,}",
  [603155] = "{id=603155,Text='发生了什么事情？',Speaker=808063,}",
  [604286] = "{id=604286,Text='呕……这是什么味道……',Speaker=808398,}",
  [604287] = "{id=604287,Text='我要被熏死了……你说，如果把怪物引过来，是不是也能把它们给熏死啊？',Speaker=808398,}",
  [604288] = "{id=604288,Text='哇！不、不要碰！',Speaker=808398,}",
  [604289] = "{id=604289,Text='感觉碰到的话，会发生很不好的事。',Speaker=808398,}",
  [604290] = "{id=604290,Text='……………',Speaker=808398,}",
  [604291] = "{id=604291,Text='……这、这里好暗啊……就没一点光吗？（哭腔）',Speaker=808398,}",
  [604292] = "{id=604292,Text='啊！有光了！',Speaker=808398,}",
  [604293] = "{id=604293,Text='再亮点、再亮点~',Speaker=808398,}",
  [604294] = "{id=604294,Text='诶，那是？',Speaker=808398,}",
  [604295] = "{id=604295,Text='啊，我知道这个。',Speaker=300105,Emoji=7,}",
  [604296] = "{id=604296,Text='戴上它可以变得力气特别大！',Speaker=300105,Option='{是吗？,2},{你要吗？,3}',}",
  [604297] = "{id=604297,Text='什么意思嘛！我说的是真的！',Speaker=300105,Emoji=12,}",
  [604298] = "{id=604298,Text='不信的话，我们找个特别沉重的东西试试看！',Speaker=300105,}",
  [604299] = "{id=604299,Text='我才不要呢，淑女不需要这种怪力。',Speaker=300105,Option='{原来,4},{你是女孩子吗？,4}',}",
  [604300] = "{id=604300,Text='不然呢！原本的我可~厉害了！要不是被夺走力量，谁会变成这样圆滚滚的一团！',Speaker=300105,Emoji=12,}",
  [604301] = "{id=604301,Text='感觉到奇特的力量涌入了身体……',}",
  [604302] = "{id=604302,Text='好啦，我们来试验一下吧~',Speaker=300105,}",
  [604303] = "{id=604303,Text='……唔！',Speaker=808414,}",
  [604304] = "{id=604304,Text='这个我推不动，你来试试看？',Speaker=808414,}",
  [604305] = "{id=604305,Text='夏基就在前面……哇，让我躲你身后！',Speaker=300105,}",
  [604306] = "{id=604306,Text='这么怕吗？',}",
  [604307] = "{id=604307,Text='因为真的很可怕啊！',Speaker=808414,Emoji=42,}",
  [604308] = "{id=604308,Text='你看他那个大块头！一拳头下去，真的会死掉啦！',Speaker=808414,}",
  [604309] = "{id=604309,Text='如果他不是这么厉害，也不能当美之宫的守护者。',Speaker=808414,Option='{守护者只有他？,2},{那朵花是什么,3}',}",
  [604310] = "{id=604310,Text='有、有他一个就够可怕啦！',Speaker=808414,}",
  [604311] = "{id=604311,Text='不过嘛，我也不知道有没有其他守护者，反正我只知道夏基……',Speaker=808414,Emoji=19,}",
  [604312] = "{id=604312,Text='不知道！夏基把它当做宝贝一样护着！',Speaker=808414,}",
  [604313] = "{id=604313,Text='反正，我不喜欢那朵花。',Speaker=808414,Emoji=40,}",
  [604314] = "{id=604314,Text='（看来有调查一下的价值）',}",
  [604315] = "{id=604315,Text='（感觉就只是一座雕像而已……）',}",
  [604316] = "{id=604316,Text='（波姬是真的很害怕他啊）',}",
  [604317] = "{id=604317,Text='（似乎只是一朵普通的花。）',}",
  [604318] = "{id=604318,Text='（如果不是枯萎了，花开之时应该会非常美丽吧。）',}",
  [604319] = "{id=604319,Text='（一堆奇怪的字母……看来得找一个能看懂这些字母的“人”？）',}",
  [604320] = "{id=604320,Text='你自己去看吧……我不想接近夏基。',Speaker=808414,Emoji=37,}",
  [604321] = "{id=604321,Text='噫……你、你调查好了？',Speaker=808414,Option='{关于夏基,4},{关于那朵花,5},{关于启示之碑,6}',}",
  [604322] = "{id=604322,Text='嗯？你问为什么夏基现在只是一座雕像？',Speaker=808414,}",
  [604323] = "{id=604323,Text='这个我也不知道……但是，夏基确实是清醒过一段时间的。',Speaker=808414,}",
  [604324] = "{id=604324,Text='在他清醒的时候，我根本不敢走近这里。',Speaker=808414,Emoji=24,}",
  [604325] = "{id=604325,Text='也不知道从什么时候开始，夏基就一点声音都没有了。',Speaker=808414,}",
  [604326] = "{id=604326,Text='夏基很喜欢那朵花。',Speaker=808414,}",
  [604327] = "{id=604327,Text='他清醒的时候，都会把那朵花护在胸前，走到哪儿都带着它。',Speaker=808414,}",
  [604328] = "{id=604328,Text='……虽然不知道原因，但我总感觉，那朵花很恐怖，好像……比夏基还要让人不想接近。',Speaker=808414,}",
  [604329] = "{id=604329,Text='不过，现在它只是一盆枯萎的死花，感觉上就一点都不可怕啦哈哈哈哈哈~',Speaker=808414,Emoji=9,}",
  [604330] = "{id=604330,Text='看不懂的石碑？',Speaker=808414,}",
  [604331] = "{id=604331,Text='我去看看我去看看！',Speaker=808414,}",
  [604332] = "{id=604332,Text='唔，这上面的是卢恩古文呢。',Speaker=808414,Option='你看得懂？',}",
  [604333] = "{id=604333,Text='嗯……大致翻译一下的话就是——',Speaker=808414,}",
  [604334] = "{id=604334,Text='“这里无日无夜，仅有他之真心”',Speaker=808414,}",
  [604335] = "{id=604335,Text='“陌生的来者啊，集土集水，辅以光明”',Speaker=808414,}",
  [604336] = "{id=604336,Text='“布里希加曼的美丽，将为你显现”',Speaker=808414,}",
  [604337] = "{id=604337,Text='……布里希加曼？没听过哎。',Speaker=808414,Option='{我觉得,7},{可能是花的名字,7}',Emoji=8,}",
  [604338] = "{id=604338,Text='一朵花还取这种浮夸的名字……',Speaker=808414,}",
  [604339] = "{id=604339,Text='所以，有了水和土壤，再加上阳光，那朵花就能重新开放……大概就是这个意思。',Speaker=808414,Option='{不仅如此,8},{恐怕夏基也,8}',}",
  [604340] = "{id=604340,Text='这还真可能！',Speaker=808414,Emoji=1,}",
  [604341] = "{id=604341,Text='什么？你打算让那朵死花重新活过来？！',Speaker=808414,Option='是布里希加曼',}",
  [604342] = "{id=604342,Text='为什么啊！那样做的话夏基也会醒过来哦！',Speaker=808414,}",
  [604343] = "{id=604343,Text='你也被那朵花迷惑了吗！',Speaker=808414,Option='{我不是这个意思,9},{你在吃醋吗,10}',Emoji=37,}",
  [604344] = "{id=604344,Text='哼。那你是什么意思，好好解释清楚！',Speaker=808414,}",
  [604345] = "{id=604345,Text='谁、谁、谁——',Speaker=808414,}",
  [604346] = "{id=604346,Text='谁吃你的醋啊你这个大笨瓜！',Speaker=808414,Emoji=12,}",
  [604347] = "{id=604347,Text='我、我怎么会和一盆死掉的花认真！',Speaker=808414,}",
  [604348] = "{id=604348,Text='你别转移话题！让花盛开是什么意思，解释清楚！',Speaker=808414,}",
  [604349] = "{id=604349,Text='不然的话我才不帮你！',Speaker=808414,Option='为了唤醒夏基',}",
  [604350] = "{id=604350,Text='唤醒——夏基——',Speaker=808414,}",
  [604351] = "{id=604351,Text='（一听就吓得跑了……波姬，行不行啊？）',}",
  [604352] = "{id=604352,Text='（或许我该安抚一下她的情绪。）',}",
  [604353] = "{id=604353,Text='你、你不要老是用这一招！',Speaker=808414,}",
  [604354] = "{id=604354,Text='我才不……',Speaker=808414,}",
  [604355] = "{id=604355,Text='……不会被你骗了。',Speaker=808414,Emoji=38,}",
  [604356] = "{id=604356,Text='唤醒夏基……然后打败他，离开美之宫对吧……',Speaker=808414,}",
  [604357] = "{id=604357,Text='虽然我知道这是唯一的办法，但……真的很害怕！夏基真的很厉害，我们肯定打不过他的！',Speaker=808414,Option='{我也很厉害哦,12},{你也很厉害哦,12}',}",
  [604358] = "{id=604358,Text='……………………',Speaker=808414,Option='{相信我吧,13},{我相信你,13}',}",
  [604359] = "{id=604359,Text='…………………………………………',Speaker=808414,}",
  [604360] = "{id=604360,Text='那、那就……',Speaker=808414,Emoji=14,}",
  [604361] = "{id=604361,Text='信你……一次。',Speaker=808414,}",
  [604362] = "{id=604362,Text='那么，为了唤醒夏基，我们需要按照那块石碑上写的，收集水和土壤，还需要阳光——',Speaker=808414,}",
  [604363] = "{id=604363,Text='嗯？阳光？对啊，原本这里有一束阳光的，怎么不见了呢？',Speaker=808414,Option='那是我',Emoji=8,}",
  [604364] = "{id=604364,Text='那还得想办法移回来才行啊。',Speaker=808414,Emoji=10,}",
  [604365] = "{id=604365,Text='总之，目标很明确了吧。我们要找到水和土壤，还要想办法把阳光转回这朵花上。',Speaker=808414,}",
  [604366] = "{id=604366,Text='那就事不宜迟，开始行动吧！',Speaker=808414,Emoji=23,}",
  [604367] = "{id=604367,Text='啊，阳光照到这里来了呀！',Speaker=300105,}",
  [604368] = "{id=604368,Text='你看，这里的镜子底下都有轨道，肯定可以推动！',Speaker=300105,}",
  [604369] = "{id=604369,Text='你现在有足够力气了吧！试试看！',Speaker=300105,}",
  [604370] = "{id=604370,Text='嘿嘿嘿，干得好！',Speaker=300105,}",
  [604371] = "{id=604371,Text='喂喂喂？魂呢？不在啦？',Speaker=300105,}",
  [604372] = "{id=604372,Text='还在磨蹭什么呀！',Speaker=300105,}",
  [604373] = "{id=604373,Text='这里不是去过了吗？你记忆力是不是不好啊？',Speaker=300105,}",
  [604374] = "{id=604374,Text='这里是不是少了什么东西？',}",
  [604375] = "{id=604375,Text='这些挡路的好讨厌啊！',Speaker=300105,}",
  [604376] = "{id=604376,Text='推开推开都推开~',Speaker=300105,}",
  [604377] = "{id=604377,Text='（似乎需要钥匙才可以）',}",
  [604378] = "{id=604378,Text='啊，之前开不了的那扇门，现在应该可以了吧！',Speaker=808398,}",
  [604379] = "{id=604379,Text='呕！又是这个味道！不过...我们可以试试之前的想法了！',Speaker=808398,}",
  [604380] = "{id=604380,Text='我要窒息了……',Speaker=808398,}",
  [604381] = "{id=604381,Text='果然对这些家伙也有效！我早就说过！',Speaker=808398,}",
  [604382] = "{id=604382,Text='（左侧似乎传来隐约的呼救声）',}",
  [604383] = "{id=604383,Text='你听到了吗？好像有人在呼救的样子。',Speaker=808398,}",
  [604384] = "{id=604384,Text='又是黑漆漆的，好讨厌啊。',Speaker=808398,}",
  [604385] = "{id=604385,Text='嗯，是我的错觉吗？感觉怪物们好像对光很敏感。',Speaker=808398,}",
  [604386] = "{id=604386,Text='救命！！放我出去！',Speaker=808390,}",
  [604387] = "{id=604387,Text='竟然还真的有人！',Speaker=300105,}",
  [604388] = "{id=604388,Text='可恶，又挡住路了……！',Speaker=300105,}",
  [604389] = "{id=604389,Text='天哪，获救了！感谢芙蕾雅大人！感谢你们！',Speaker=808390,Option='你怎么在这里？',}",
  [604390] = "{id=604390,Text='我只是对花开之地很好奇，想来看看，就误入了这个美之宫……',Speaker=808390,}",
  [604391] = "{id=604391,Text='如果知道这里这么危险，打死我也不来了！',Speaker=808390,Emoji=42,}",
  [604392] = "{id=604392,Text='我记下了。',Speaker=808414,}",
  [604393] = "{id=604393,Text='下次再看到你，就打死你。（语气欢快）',Speaker=808414,Emoji=28,}",
  [604394] = "{id=604394,Text='总、总之谢谢你们救了我！',Speaker=808390,}",
  [604395] = "{id=604395,Text='实在也没什么可以答谢你们的，困在这里这么久，带的食物也吃完了……',Speaker=808390,}",
  [604396] = "{id=604396,Text='多少总得表达一下我的谢意嘛！',Speaker=808390,Emoji=20,}",
  [604397] = "{id=604397,Text='我把这个美之宫里我到过的地方都画成了地图，应该会对你们有所帮助。',Speaker=808390,Option='{谢谢,2},{太有帮助了,2}',}",
  [604398] = "{id=604398,Text='嘿嘿，那就好！',Speaker=808390,}",
  [604399] = "{id=604399,Text='是夏基的手下！快搞定它吧！',Speaker=808398,}",
  [604400] = "{id=604400,Text='快搞定它吧！',Speaker=808398,}",
  [604401] = "{id=604401,Text='宝箱！宝箱！！',Speaker=808414,Emoji=13,}",
  [604402] = "{id=604402,Text='（波姬开心得直接冲过去了……她对宝箱真是毫无抵抗力啊）',}",
  [604403] = "{id=604403,Text='咦？（嗅嗅）',Speaker=808414,}",
  [604404] = "{id=604404,Text='啊，你快来！！',Speaker=808414,}",
  [604405] = "{id=604405,Text='我闻到有水的味道！那个箱子里肯定有水。',Speaker=808414,}",
  [604406] = "{id=604406,Text='你快把宝箱打开！',Speaker=808414,Option='求人要礼貌点',}",
  [604407] = "{id=604407,Text='别假模假样！快干正事！',Speaker=808414,}",
  [604408] = "{id=604408,Text='诶，这里好像藏着什么好东西？（嗅嗅）',Speaker=808398,}",
  [604409] = "{id=604409,Text='啊，是这个，是这个~',Speaker=808398,}",
  [604410] = "{id=604410,Text='想想看，好像可以用来做大事呢！',Speaker=808398,}",
  [604411] = "{id=604411,Text='咦？这是什么？',Speaker=808398,}",
  [604412] = "{id=604412,Text='那块碑上写着什么？去看看吧。',Speaker=808398,}",
  [604413] = "{id=604413,Text='“这里无日无夜，仅有自我智慧”',Speaker=808440,}",
  [604414] = "{id=604414,Text='“陌生的来者啊，闭目沉思，探索内心”',Speaker=808440,}",
  [604415] = "{id=604415,Text='“传送的道路，将为你显现”',Speaker=808440,}",
  [604416] = "{id=604416,Text='你有一颗虔诚的心灵……',Speaker=808440,}",
  [604417] = "{id=604417,Text='狂妄之辈，跑死在这个美之宫吧！',Speaker=808440,}",
  [604418] = "{id=604418,Text='……这个女人又发病了。',Speaker=300105,}",
  [604419] = "{id=604419,Text='刚才我好像飞起来了……',Speaker=300105,}",
  [604420] = "{id=604420,Text='诶？为什么我会有飞起来的感觉？',Speaker=300105,Option='是传送的错觉',}",
  [604421] = "{id=604421,Text='是这样吗……好像不太一样……',Speaker=300105,}",
  [604422] = "{id=604422,Text='不错不错，就是这样~',Speaker=300105,Emoji=2,}",
  [604423] = "{id=604423,Text='继续出发啦。',Speaker=300105,}",
  [604424] = "{id=604424,Text='这个房间……好莫名其妙。',Speaker=808398,}",
  [604425] = "{id=604425,Text='是错觉吗？总觉得这房间好像来过一样……',Speaker=808398,}",
  [604426] = "{id=604426,Text='之前是不是有个房间和这里差不多？',Speaker=808398,}",
  [604427] = "{id=604427,Text='哎呀！原来还有人会来到美之宫！',Speaker=808394,Option='你是谁？',}",
  [604428] = "{id=604428,Text='真没礼貌！我可是艾卡拉奇最有名的机关研究员！',Speaker=808394,Emoji=20,}",
  [604429] = "{id=604429,Text='美之宫里各种奇特的机关，真是太有研究价值了！',Speaker=808394,Option='那么这个房间的机关',}",
  [604430] = "{id=604430,Text='啊？………………………………呃，这个。',Speaker=808394,}",
  [604431] = "{id=604431,Text='我嘛，嗯，还在研究……',Speaker=808394,Option='{原来,8}',}",
  [604432] = "{id=604432,Text='是吹牛皮的大叔呢。（大声地自言自语）',Speaker=808414,}",
  [604433] = "{id=604433,Text='不要妄下定论！至少我可以判定，这个房间的机关，包含的信息并不完整！',Speaker=808394,Option='{并不完整？,9},{为什么这么说？,9}',}",
  [604434] = "{id=604434,Text='如果信息完整的话，我怎么可能解不开！（非常大声）',Speaker=808394,}",
  [604435] = "{id=604435,Text='啊，感觉吐槽他我就输了……',Speaker=808414,}",
  [604436] = "{id=604436,Text='啊对了！你们可以去解开这个谜题啊~',Speaker=808394,Option='{那你为什么？,10},{自己不去找,10}',Emoji=11,}",
  [604437] = "{id=604437,Text='我知道。大叔一定是打不过外面的怪物嘛。',Speaker=808414,Emoji=17,}",
  [604438] = "{id=604438,Text='（真是童言无忌……）',}",
  [604439] = "{id=604439,Text='如何？如果你们解开了这个谜题的话，我就把我珍藏的宝物送给你们！',Speaker=808394,Option='{好吧,12},{没那么多功夫,13}',}",
  [604440] = "{id=604440,Text='好，那快去快去，我等着你们的消息。',Speaker=808394,}",
  [604441] = "{id=604441,Text='毫无研究精神的俗人！离我远点！',Speaker=808394,Emoji=12,}",
  [604442] = "{id=604442,Text='嗯？想再看一遍那个火坛的顺序吗？看好啦~',Speaker=808394,}",
  [604443] = "{id=604443,Text='哦！你们已经解开机关了吗！',Speaker=808394,Option='告知情况',}",
  [604444] = "{id=604444,Text='嗯……嗯嗯……',Speaker=808394,}",
  [604445] = "{id=604445,Text='啊！竟然是映射的机关吗！这可真是……',Speaker=808394,}",
  [604446] = "{id=604446,Text='太美妙了！太精巧了！我真想亲眼看到解密的那一瞬！',Speaker=808394,Emoji=27,}",
  [604447] = "{id=604447,Text='……啊。我承诺过要送你们宝物的是吧。',Speaker=808394,}",
  [604448] = "{id=604448,Text='宝物就在我身后，你们自己去拿吧。',Speaker=808394,}",
  [604449] = "{id=604449,Text='我要赶紧去看看那个精妙的机关！',Speaker=808394,}",
  [604450] = "{id=604450,Text='好奇怪的房间！',Speaker=808398,}",
  [604451] = "{id=604451,Text='什、什么声音？！',Speaker=808398,}",
  [604452] = "{id=604452,Text='又是这么多宝箱。到底有多少宝箱……',Speaker=808398,}",
  [604453] = "{id=604453,Text='你过来看看，这里又有一个机关。',Speaker=808398,}",
  [604454] = "{id=604454,Text='不知道这个机关开启的是什么……',Speaker=808398,}",
  [604455] = "{id=604455,Text='（这个机关很像之前[c][ffff00]开启阳光的那个[-][/c]。莫非……）',}",
  [604456] = "{id=604456,Text='……没听到什么声音，要走回去看看吗？',Speaker=808398,}",
  [604457] = "{id=604457,Text='小心飞轮！！',Speaker=808398,}",
  [604458] = "{id=604458,Text='我可是提醒过你了！',Speaker=808398,}",
  [604459] = "{id=604459,Text='……黑暗……呜呜呜……',Speaker=808398,}",
  [604460] = "{id=604460,Text='我不要……',Speaker=808398,}",
  [604461] = "{id=604461,Text='（嗯？波姬好像没在抱怨了。不会吓晕了吧？）',}",
  [604462] = "{id=604462,Text='（波姬呢？）',Emoji=8,}",
  [604463] = "{id=604463,Text='一个奇怪的扳手和神奇的石碑，先去调查看看吧',}",
  [604464] = "{id=604464,Text='………………（发抖）',Speaker=808414,}",
  [604465] = "{id=604465,Text='……啊……',Speaker=808414,Option='{波姬！,2},{你没事吧？,2}',}",
  [604466] = "{id=604466,Text='………………大…………',Speaker=808414,}",
  [604467] = "{id=604467,Text='大笨蛋……怎么现在才来找我……',Speaker=808414,Emoji=24,}",
  [604468] = "{id=604468,Text='（都吓得哽咽了。是真的害怕得不得了了吧）',Emoji=10,}",
  [604469] = "{id=604469,Text='我和你说过了我怕黑……',Speaker=808414,Option='{是我不小心,2},{（摸摸）,3}',}",
  [604470] = "{id=604470,Text='呜……下次、下次不允许这样了……',Speaker=808414,}",
  [604471] = "{id=604471,Text='你、你这是做什么呀！',Speaker=808414,Option='{不怕了哦,4},{不怕了吧？,4}',}",
  [604472] = "{id=604472,Text='你这个人……',Speaker=808414,}",
  [604473] = "{id=604473,Text='好啦好啦，下次不允许发生这种事了！',Speaker=808414,}",
  [604474] = "{id=604474,Text='要好好地把我看住哦！',Speaker=808414,Emoji=2,}",
  [604475] = "{id=604475,Text='又是夏基的手下。怎么对付应该很有经验了吧！',Speaker=808398,}",
  [604476] = "{id=604476,Text='快去享受胜利的果实~',Speaker=808398,}",
  [604477] = "{id=604477,Text='竟然有土壤！',Speaker=808398,}",
  [604478] = "{id=604478,Text='这下那朵花可没理由再装死咯~',Speaker=808398,}",
  [604479] = "{id=604479,Text='这个房间的石头是不是少了点？总觉得哪里怪怪的。',Speaker=808398,}",
  [604480] = "{id=604480,Text='阳光又照进来了。',Speaker=808398,}",
  [604481] = "{id=604481,Text='……不过方向还是不太对。',Speaker=808398,}",
  [604482] = "{id=604482,Text='阳光，水，土。现在这三样东西都已经齐备了。',Speaker=808398,}",
  [604483] = "{id=604483,Text='当花朵得到这三样东西，夏基应该就会苏醒了。',Speaker=808398,}",
  [604484] = "{id=604484,Text='你啊，做好准备了吗？',Speaker=808398,Option='{是的,2},{显然没有,2}',}",
  [604485] = "{id=604485,Text='你不要觉得我会夸你直率坦诚噢！',Speaker=808398,Emoji=15,}",
  [604486] = "{id=604486,Text='既然你不急那我也可以偷懒，等你做好准备再来找我。',Speaker=808398,}",
  [604487] = "{id=604487,Text='你啊，做好准备了吗？',Speaker=808398,}",
  [604488] = "{id=604488,Text='嘿嘿嘿，我喜欢这样有自信的你。',Speaker=808398,Emoji=2,}",
  [604489] = "{id=604489,Text='虽然夏基确实很可怕……',Speaker=808398,}",
  [604490] = "{id=604490,Text='不过一起上的话，勇气也会多那么一点点！',Speaker=808398,}",
  [604491] = "{id=604491,Text='来吧，把我们辛苦找到的阳光、水和土壤，变成冲出这美之宫的道路吧！',Speaker=808398,Emoji=23,}",
  [604492] = "{id=604492,Text='……喂，我们要发呆到什么时候？',Speaker=300105,Option='{不知为何,2},{有些伤感,2}',}",
  [604493] = "{id=604493,Text='事到如今再说这话已经没意义了吧。为了离开美之宫，我们总是要击败夏基的。',Speaker=300105,}",
  [604494] = "{id=604494,Text='……再说，我觉得他们也挺幸福的不是吗。',Speaker=300105,Option='{你说得对,3},{……,3}',}",
  [604495] = "{id=604495,Text='啊，对了。',Speaker=300105,Emoji=7,}",
  [604496] = "{id=604496,Text='夏基被打败后，那面那个传送阵就激活了呢。',Speaker=300105,}",
  [604497] = "{id=604497,Text='那会是通向外面的吗？',Speaker=808414,Option='去试试',}",
  [604498] = "{id=604498,Text='这里……似乎……',Speaker=808414,}",
  [604499] = "{id=604499,Text='还是美之宫吧？',Speaker=808414,Option='显然',}",
  [604500] = "{id=604500,Text='……啧，真麻烦。',Speaker=808414,Option='早该想到',Emoji=25,}",
  [604501] = "{id=604501,Text='那边也有一个传送之碑，又是通向哪儿的？',Speaker=808414,}",
  [604502] = "{id=604502,Text='（总觉得波姬说话口气有点不太一样了）',}",
  [604503] = "{id=604503,Text='（是我的错觉吗……？）',}",
  [604504] = "{id=604504,Text='唔、唔……（嘟嘟哝哝）',Speaker=808414,Option='{发现什么了？,7},{你好像变了呢,8}',}",
  [604505] = "{id=604505,Text='光是看能发现什么啊。',Speaker=808414,}",
  [604506] = "{id=604506,Text='你要不要来看看？',Speaker=808414,}",
  [604507] = "{id=604507,Text='哈？说什么胡话？',Speaker=808414,Emoji=8,}",
  [604508] = "{id=604508,Text='我就是我啊。',Speaker=808414,Option='{可是,9},{似乎语气,9}',}",
  [604509] = "{id=604509,Text='语气……怎么了吗？',Speaker=808414,Option='{变稳重了,10},{变聪明了,10}',}",
  [604510] = "{id=604510,Text='哼，我本来就很稳重很聪明！',Speaker=808414,Emoji=5,}",
  [604511] = "{id=604511,Text='“这里无日无夜，仅有坚定勇气”',Speaker=808391,}",
  [604512] = "{id=604512,Text='“陌生的来者啊，不可后退，谨慎小心”',Speaker=808391,}",
  [604513] = "{id=604513,Text='“卡瓦希尔的道路，将为你显现”',Speaker=808391,}",
  [604514] = "{id=604514,Text='卡瓦希尔……卡瓦希尔……',Speaker=808398,}",
  [604515] = "{id=604515,Text='这个名字听起来有点耳熟……？',Speaker=808398,}",
  [604516] = "{id=604516,Text='奇怪，头……有点痛……',Speaker=808398,Option='{波姬？,12},{你还好吗？,12}',}",
  [604517] = "{id=604517,Text='嘿嘿嘿嘿……',Speaker=808446,}",
  [604518] = "{id=604518,Text='夏基就这样被你们击败了啊。',Speaker=808446,}",
  [604519] = "{id=604519,Text='也对，那个肌肉比脑子发达的家伙就这么点实力，整天抱着朵破花畏畏缩缩的。',Speaker=808446,}",
  [604520] = "{id=604520,Text='他还不知道那朵花本来就是派来弄死他的呢哈哈哈哈！！！！',Speaker=808446,}",
  [604521] = "{id=604521,Text='太荒谬了！太无趣了！——我，卡瓦希尔，居然与这种蠢货同为守护者！',Speaker=808446,}",
  [604522] = "{id=604522,Text='这简直是……',Speaker=808400,}",
  [604523] = "{id=604523,Text='……这简直是……',Speaker=808400,}",
  [604524] = "{id=604524,Text='——耻辱！！！！',Speaker=808400,}",
  [604525] = "{id=604525,Text='你、莫非……？',Speaker=808400,}",
  [604526] = "{id=604526,Text='哼，原来夏基不过是你的封印之一……',Speaker=808400,}",
  [604527] = "{id=604527,Text='波姬！！！',}",
  [604528] = "{id=604528,Text='我留在这里。你离开。',Speaker=808398,}",
  [604529] = "{id=604529,Text='不必为我担心。这个卡瓦希尔只是幻影。要对付他，现在的我完全没问题。',Speaker=808398,}",
  [604530] = "{id=604530,Text='……下次我们再见面时，不要吃惊哦？',Speaker=808398,}",
  [604531] = "{id=604531,Text='（零散的文字。是夏基留下的吗？）',}",
  [604532] = "{id=604532,Text='我为什么在这里。那个恶心的女人，把我禁锢在这里想要做什么？',Speaker=808402,}",
  [604533] = "{id=604533,Text='头好痛。好痛。好痛。好痛。好痛。……痛得只想杀掉些什么。',Speaker=808402,}",
  [604534] = "{id=604534,Text='我似乎又痛昏过去了。已经不记得时间了。奇怪。我的身边有个什么白白的东西……',Speaker=808402,}",
  [604535] = "{id=604535,Text='……是一朵花。它从哪儿来的？',Speaker=808402,}",
  [604536] = "{id=604536,Text='我可能是疯了。我在和花说话。不，那是女孩子，那是布里希加曼。',Speaker=808402,}",
  [604537] = "{id=604537,Text='花。女孩子。布里希加曼。……布里希加曼？那是谁？不……',Speaker=808402,}",
  [604538] = "{id=604538,Text='……是的，我知道。你就是你。',Speaker=808402,}",
  [604539] = "{id=604539,Text='你的声音。你的手。你的眼神。你的呼吸。你需要什么？告诉我，告诉我你需要的一切，我会满足。所以——',Speaker=808402,}",
  [604540] = "{id=604540,Text='请不要，消失。',Speaker=808402,}",
  [604541] = "{id=604541,Text='我得到了永恒。我再也不会失去。这感受，和死亡一样。无所谓了，我已经快看不见了。',Speaker=808402,}",
  [604542] = "{id=604542,Text='你在那里吗，我的布里希加曼？',Speaker=808402,}",
  [604543] = "{id=604543,Text='我~们找到一个门~',Speaker=808396,}",
  [604544] = "{id=604544,Text='一个门！一个门！',Speaker=808397,}",
  [604545] = "{id=604545,Text='还~~要找到一个钥匙~',Speaker=808396,}",
  [604546] = "{id=604546,Text='一个钥匙！一个钥匙！',Speaker=808397,}",
  [604547] = "{id=604547,Text='不会用量词你们就别乱唱好嘛……',Speaker=808395,}",
  [604548] = "{id=604548,Text='（这就是夏基吗...）',}",
  [604549] = "{id=604549,Text='喂、喂！你要去哪里啊？',Speaker=300105,}",
  [604550] = "{id=604550,Text='（还不到离开的时候，先调查这里的线索吧。）',}",
  [604551] = "{id=604551,Text='还是暂时先不要乱动的好…',}",
  [604552] = "{id=604552,Text='你看你看，这里的镜子底下都有轨道，这些肯定可以推动！',Speaker=300105,}",
  [604553] = "{id=604553,Text='…………',Speaker=808408,}",
  [604554] = "{id=604554,Text='啊，扳手断了，看起来已经损坏，不能再次使用了',Speaker=808409,}",
  [604555] = "{id=604555,Text='不要！！！',Speaker=310603,}",
  [604557] = "{id=604557,Text='刚刚那个奇怪的团子是谁？这又是什么地方？不管怎么样，先追上去看看吧',}",
  [604558] = "{id=604558,Text='什、什么人！那个宝箱是你打开的吗？',Speaker=808423,}",
  [604559] = "{id=604559,Text='把宝物交出来！',Speaker=808424,}",
  [604560] = "{id=604560,Text='年轻人，好东西要吗（低声）',Speaker=808393,}",
  [604561] = "{id=604561,Text='这个危机四伏的破地方，谁不需要一点自保的能力呢。',Speaker=808393,}",
  [604562] = "{id=604562,Text='只要给我足够的材料，我就能让你变得更强，怎么样？',Speaker=808393,Option='{成交,3},{不用不用,4}',}",
  [604563] = "{id=604563,Text='你怎么不识好歹呢！',Speaker=808393,Emoji=14,}",
  [604564] = "{id=604564,Text='爽快！那么，一手交钱一手交货！',Speaker=808393,Emoji=20,}",
  [604565] = "{id=604565,Text='那么……你想要加强哪方面的能力？',Speaker=808393,Option='{物理攻击,5},{魔法攻击,7},{生命,9}',}",
  [604566] = "{id=604566,Text='这些可是用来保命的，别那么小气！把材料准备够了再来！',Speaker=808393,}",
  [604567] = "{id=604567,Text='哇，原来点灯谜题产生的异动是这里啊！',Speaker=300105,}",
  [604568] = "{id=604568,Text='一本奇怪的手记，是否打开看看。',Option='{打开,2}',}",
  [604569] = "{id=604569,Text='看起来像是一段独白，即使透过文字也能很明显的感受到他的痛楚。',}",
  [604570] = "{id=604570,Text='先拿着吧，说不定会在哪能够用上。',}",
  [604571] = "{id=604571,Text='又是一本，是否打开看看。',Option='{打开,2}',}",
  [604572] = "{id=604572,Text='他们在互相依偎，互相取暖。',}",
  [604573] = "{id=604573,Text='（一堆奇怪的字母……波姬会懂吗？）',}",
  [604574] = "{id=604574,Text='符文闪烁着异样的光芒，通过它会前往何处呢？',}",
  [604575] = "{id=604575,Text='[c][ffff00]这个传送阵的尽头到底通向哪，要不要看看还有没有房间没去过呢。[-][/c]',Option='{准备好了,5},{再检查看看,6}',}",
  [604576] = "{id=604576,Text='好软呀~',}",
  [604577] = "{id=604577,Text='哇！！！',}",
  [604578] = "{id=604578,Text='老大！！',}",
  [604579] = "{id=604579,Text='你没事吧！！！',}",
  [604580] = "{id=604580,Text='！！！！',}",
  [604581] = "{id=604581,Text='老~~~~~~~~',}",
  [604582] = "{id=604582,Text='大~~~~~~~~',}",
  [604583] = "{id=604583,Text='老大？',}",
  [604584] = "{id=604584,Text='太荒谬了！',}",
  [604585] = "{id=604585,Text='太无趣了！',}",
  [604586] = "{id=604586,Text='——我，卡瓦希尔，居然与这种蠢货同为守护者！',}",
  [604587] = "{id=604587,Text='这简直是……',}",
  [604588] = "{id=604588,Text='!!!',}",
  [604589] = "{id=604589,Text='简直是……',}",
  [604590] = "{id=604590,Text='——耻辱！！！！',}",
  [604591] = "{id=604591,Text='留下你们的遗言吧！',}",
  [604592] = "{id=604592,Text='你！你莫非...!?',}",
  [604593] = "{id=604593,Text='不可能！',}",
  [604594] = "{id=604594,Text='我来拖住他！你快离开这里！',}",
  [604595] = "{id=604595,Text='不！我们要一起出去！',}",
  [604596] = "{id=604596,Text='不必为我担心，我长大了！',}",
  [604597] = "{id=604597,Text='如果还有机会再见面...',}",
  [604598] = "{id=604598,Text='一定要认得我喲！',}",
  [604599] = "{id=604599,Text='那就说好了！冒险者！',}",
  [604600] = "{id=604600,Text='[c][ffff00]还是先四处调查一下再说吧[-][/c]。',}",
  [604601] = "{id=604601,Text='[c][ffff00]或许应该去问问她。[-][/c]',}",
  [604602] = "{id=604602,Text='千万要保重啊~~~~~',Speaker=808390,Emoji=35,}",
  [604603] = "{id=604603,Text='你记住了吗？反正我可记不住！',Speaker=300105,}",
  [604604] = "{id=604604,Text='传送阵！传送阵！快走进去试试！',Speaker=300105,}",
  [604605] = "{id=604605,Text='不远处传来轰隆隆的声音，看起来像是某扇门状态变化了。',}",
  [604606] = "{id=604606,Text='什么声音？',Speaker=300105,}",
  [604607] = "{id=604607,Text='从右边隔壁房间传来了轰隆隆的声音，有两个障碍物凭空出现了。',}",
  [604608] = "{id=604608,Text='好像现在还过不去呢，不过地上出现了一个神奇的传送阵。',Speaker=300105,}",
  [604609] = "{id=604609,Text='要不要踩上去看看通向哪里…',}",
  [604610] = "{id=604610,Text='哎，还有什么事情吗？',Speaker=808394,Option='{想再看一遍,6},{我解开了,7}',}",
  [604611] = "{id=604611,Text='你可别开玩笑了！我是认真的…',Speaker=808394,}",
  [604612] = "{id=604612,Text='你要是不想帮忙的话，就别来给我添乱！',Speaker=808394,}",
  [604613] = "{id=604613,Text='好像错了呢，再想想再想想……',Speaker=300105,}",
  [604614] = "{id=604614,Text='一把铜制钥匙，试试面前这扇有锁孔的门吧。',}",
  [604615] = "{id=604615,Text='又一把铜制钥匙，那么之前路过的那扇门也许就…',}",
  [604616] = "{id=604616,Text='啊，前方肯定有用到它的地方。',}",
  [604617] = "{id=604617,Text='这会是最后一把吗？',}",
  [604618] = "{id=604618,Text='竟然有土壤！',Speaker=300105,}",
  [604619] = "{id=604619,Text='这下那朵花可没理由再装死咯~',Speaker=300105,}",
  [604620] = "{id=604620,Text='又一本夏基的手记！',Speaker=300105,}",
  [604621] = "{id=604621,Text='我已经将你的物理伤害提升了15%，但是我要提醒你前面的路可不好走，如果你执意前行的话…',Speaker=808393,}",
  [604622] = "{id=604622,Text='不管怎么样，祝你好运！',Speaker=808393,}",
  [604623] = "{id=604623,Text='这里看起来像是少了一面镜子，或许找到镜子我们就可以打开所有的门了。',Speaker=300105,}",
  [604624] = "{id=604624,Text='那我们现在该去哪？',}",
  [604625] = "{id=604625,Text='要不先去南面的门碰碰运气？',Speaker=300105,}",
  [604626] = "{id=604626,Text='我已经将你的魔法伤害提升了15%，但是我要提醒你前面的路可不好走，如果你执意前行的话…',Speaker=808393,}",
  [604627] = "{id=604627,Text='我已经将你的生命上限提升了20%，但是我要提醒你前面的路可不好走，如果你执意前行的话…',Speaker=808393,}",
  [604628] = "{id=604628,Text='你说取回记忆和力量，是怎么回事？',}",
  [604629] = "{id=604629,Text='字面意思啊。我忘记了很多事，力量也变弱了。所以才需要你陪我找回来。',Speaker=300105,}",
  [604630] = "{id=604630,Text='虽然不知道确切位置，但它们一定就在这美之宫里。',Speaker=300105,}",
  [604631] = "{id=604631,Text='没错，就是这个！有了它我就能——',Speaker=300105,Option='重获力量？',}",
  [604632] = "{id=604632,Text='不，只能算是恢复一小部分而已……',Speaker=300105,Emoji=15,}",
  [604633] = "{id=604633,Text='又一个,虽然一开始的力量很有限……',Speaker=300105,}",
  [604634] = "{id=604634,Text='但是，慢慢的慢慢的，我肯定可以重获力量的。',Speaker=300105,}",
  [604635] = "{id=604635,Text='一团淡绿色的火焰...',Option='这是？',}",
  [604636] = "{id=604636,Text='啊，我知道这个，这是树人之祖的能量核心。',Speaker=300105,Option='那是什么东西',}",
  [604637] = "{id=604637,Text='传说中拥有它的人会获得百毒不侵的能力。',Speaker=300105,}",
  [604638] = "{id=604638,Text='那之前遇见的毒池岂不是……',}",
  [604639] = "{id=604639,Text='当然这些只是传闻，要亲身试验一下才知道！',Speaker=300105,}",
  [604643] = "{id=604643,Text='我想想，你得先给我150个晨曦的露水，15个流星的凝光~',Speaker=808393,Option='没问题',}",
  [604649] = "{id=604649,Text='请问您要金斧子，银斧子，还是我这把木斧子',Speaker=817510,Option='{金斧子,2},{银斧子,3},{木斧子,4},{我全都要,5},{我要起飞了,6},{想要开房,7}',}",
  [604650] = "{id=604650,Text='宁怎么不去死呢',Speaker=817510,}",
  [604651] = "{id=604651,Text='真是个好孩子呢！',Speaker=817510,}",
  [604652] = "{id=604652,Text='看来暂时还无法解决这里的谜题，应该有没去过的房间~',Speaker=300105,}",
  [604653] = "{id=604653,Text='去别的地方碰碰运气吧！',Speaker=300105,}",
  [604654] = "{id=604654,Text='这个地方我之前有见过一个一模一样的房间',Speaker=300105,}",
  [604655] = "{id=604655,Text='但是我想不起来在哪了，或许找到那个房间谜底就解开了',Speaker=300105,}",
  [604656] = "{id=604656,Text='有颜色区分和排列顺序的石块~',Speaker=300105,}",
  [604657] = "{id=604657,Text='emmm…让我想想！',Speaker=300105,}",
  [604658] = "{id=604658,Text='波利和有颜色的石块，或许有着某种联系~',Speaker=300105,}",
  [604659] = "{id=604659,Text='房已经开好了，您飞一下就好了',Speaker=817510,}",
  [604660] = "{id=604660,Text='牛啊，起飞！',Speaker=817510,}",
  [604661] = "{id=604661,Text='不好！他不见了，得快点找到他在哪！不然我怕会死的很惨！',Speaker=300106,}",
  [604662] = "{id=604662,Text='地面上出现了防护罩，暂时去那里躲躲吧！',Speaker=300106,}",
  [604663] = "{id=604663,Text='绝美晚霞之下，克魔岛传统的花车巡游，将要出发啦！',Speaker=808466,}",
  [604664] = "{id=604664,Text='5！',Speaker=808466,}",
  [604665] = "{id=604665,Text='4！',Speaker=808466,}",
  [604666] = "{id=604666,Text='3！',Speaker=808466,}",
  [604667] = "{id=604667,Text='2！',Speaker=808466,}",
  [604668] = "{id=604668,Text='1！',Speaker=808466,}",
  [604669] = "{id=604669,Text='我们出发啦！',Speaker=808466,}",
  [604670] = "{id=604670,Text='满载着独特的风土人情，克魔岛花车将沿着海岸，带给你们最美妙的夜晚！',Speaker=808466,}",
  [604671] = "{id=604671,Text='现在，准备好接受克魔岛魅舞剧团的热辣演出了吗！',Speaker=808466,}",
  [604672] = "{id=604672,Text='看！克魔岛的朋友们正向大家招手呢！别犹豫，快来加入这场绚烂的游行吧~',Speaker=808466,}",
  [604673] = "{id=604673,Text='请让我们听见大家的欢呼！',Speaker=808466,}",
  [604674] = "{id=604674,Text='花车一路行过，洒下不计其数的欢乐与飞吻~',Speaker=808466,}",
  [604675] = "{id=604675,Text='放松身心，大胆来互动吧！',Speaker=808466,}",
  [604676] = "{id=604676,Text='天边绽放的烟火，点亮了克魔岛的夜晚。与音乐和舞蹈相伴，一起享受这属于奇迹的时刻！',Speaker=808466,}",
  [604677] = "{id=604677,Text='动感的音乐，火辣的热舞！来吧， 伸出你的手！',Speaker=808466,}",
  [604678] = "{id=604678,Text='自由！节拍！扭动身体，释放灵魂！',Speaker=808466,}",
  [604679] = "{id=604679,Text='魅舞剧团的伙伴，即将再次展现震撼身心的舞姿！',Speaker=808466,}",
  [604680] = "{id=604680,Text='听见海边的歌声了吗？来随着节奏跳起舞步吧，尽情狂欢歌唱吧，燃起音乐的热情之火！',Speaker=808466,}",
  [604681] = "{id=604681,Text='就在此刻，与身边的陌生人微笑致意，迈出友谊的第一步~',Speaker=808466,}",
  [604682] = "{id=604682,Text='热情的狂欢队伍，再次启程咯！',Speaker=808466,}",
  [604683] = "{id=604683,Text='不必心急，我们一个小时后再见！',Speaker=808466,}",
  [604684] = "{id=604684,Text='嗨~热情狂放的花车巡游，又回来了！',Speaker=808466,}",
  [604685] = "{id=604685,Text='充满魅力的巡游，是不是让大家感到些许疲累？',Speaker=808466,}",
  [604686] = "{id=604686,Text='巡游即将暂告段落，但欢乐会永远持续下去哦！',Speaker=808466,}",
  [604687] = "{id=604687,Text='现在，我将代表王权的权杖授予你。',Speaker=808471,}",
  [604688] = "{id=604688,Text='呵~',Speaker=812728,}",
  [604689] = "{id=604689,Text='嗯？这是……',Speaker=812726,}",
  [604690] = "{id=604690,Text='请铭记今天的宣誓与许诺。',Speaker=808471,}",
  [604691] = "{id=604691,Text='……权杖！',Speaker=812726,}",
  [604692] = "{id=604692,Text='梦里的人手持的是权杖！',Speaker=812726,}",
  [604693] = "{id=604693,Text='不要碰它！',Speaker=812726,}",
  [604694] = "{id=604694,Text='不要！不要拿起它！',Speaker=812726,}",
  [604695] = "{id=604695,Text='啊……',Speaker=812726,}",
  [604696] = "{id=604696,Text='额……啊……我……',Speaker=812728,}",
  [604697] = "{id=604697,Text='不……',Speaker=812728,}",
  [604698] = "{id=604698,Text='救救我们……',Speaker=812730,}",
  [604699] = "{id=604699,Text='我在和马丁诉说之后，他愿意帮助我拿取权杖，于是我就在下班离开王宫将钥匙交给了他后，回家了。',Speaker=812732,}",
  [604700] = "{id=604700,Text='拿到钥匙之后。夜晚王宫人少后，就前往密室取出权杖。',Speaker=812733,}",
  [604701] = "{id=604701,Text='我根据爱丽丝的嘱托，将权杖带去正厅，放进主教的银盒内，并关上了盒子。',Speaker=812733,}",
  [604702] = "{id=604702,Text='珀把毒药涂在自己的手套上。',}",
  [604703] = "{id=604703,Text='利用地砖倒影观察爱丽丝接近。',}",
  [604704] = "{id=604704,Text='将毒药放入爱丽丝围裙里。',}",
  [604705] = "{id=604705,Text='奈特继位时，珀挤到前方与王子握手。',}",
  [604706] = "{id=604706,Text='确保只有奈特一个人中毒。',}",
  [604707] = "{id=604707,Text='现在，我将代表王权的权杖授予你。',}",
  [604708] = "{id=604708,Text='呵~',}",
  [604709] = "{id=604709,Text='嗯？这是……',}",
  [604710] = "{id=604710,Text='请铭记今天的宣誓与许诺。',}",
  [604711] = "{id=604711,Text='……权杖！',}",
  [604712] = "{id=604712,Text='梦里的人手持的是权杖！',}",
  [604713] = "{id=604713,Text='不要碰它！',}",
  [604714] = "{id=604714,Text='不要！不要拿起它！',}",
  [604715] = "{id=604715,Text='啊……',}",
  [604716] = "{id=604716,Text='额……啊……',}",
  [604717] = "{id=604717,Text='我……',}",
  [604718] = "{id=604718,Text='不……',}",
  [604733] = "{id=604733,Voice='Npc_Quest/604733',Text='是我邀请马丁……跟我一起去密室……',Speaker=812971,}",
  [604734] = "{id=604734,Text='庭审如期举办，冒险者一行三人在众人面前用证据揭露出真相，原来，爱丽丝十分胆小，皇宫中又谣传着闹鬼的事情，她不敢自己去密室拿取权杖，于是拜托了王宫侍卫长马丁在深夜无人之时，帮她从密室中拿出权杖，并放进了主教的银盒之中。整个过程爱丽丝都没有接触过权杖，也就没有时间能够下毒。\n虽然庭审中证实了爱丽丝的清白，但是仍然留下了很多疑点。由于毒药是在爱丽丝身上被发现的，尼希尔便向她询问案发当天是否有人靠近过她的身边。爱丽丝回忆起来，在案发的当天她曾经被珀·力哈尔特撞倒过。这让调查有了新的方向，冒险者一行人围绕着珀展开了一系列的调查，确认了案件是珀所为。',}",
  [604776] = "{id=604776,Text='默认对话1',Speaker=1000,}",
  [604777] = "{id=604777,Text='默认对话2',Speaker=1000,}",
  [604778] = "{id=604778,Text='默认对话3',Speaker=1000,}",
  [604779] = "{id=604779,Text='默认对话4',Speaker=1000,}",
  [604780] = "{id=604780,Text='默认对话5',Speaker=1000,}",
  [604781] = "{id=604781,Text='默认对话6',Speaker=1000,}",
  [604782] = "{id=604782,Text='默认对话7',Speaker=1000,}",
  [604783] = "{id=604783,Text='默认对话8',Speaker=1000,}",
  [604784] = "{id=604784,Text='默认对话9',Speaker=1000,}",
  [604785] = "{id=604785,Text='默认对话10',Speaker=1000,}",
  [604786] = "{id=604786,Text='默认对话11',Speaker=1000,}",
  [604787] = "{id=604787,Text='默认对话12',Speaker=1000,}",
  [604788] = "{id=604788,Text='默认对话13',Speaker=1000,}",
  [604789] = "{id=604789,Text='默认对话14',Speaker=1000,}",
  [604790] = "{id=604790,Text='默认对话15',Speaker=1000,}",
  [604791] = "{id=604791,Text='默认对话16',Speaker=1000,}",
  [604792] = "{id=604792,Text='默认对话17',Speaker=1000,}",
  [604793] = "{id=604793,Text='默认对话18',Speaker=1000,}",
  [604794] = "{id=604794,Text='默认对话19',Speaker=1000,}",
  [604795] = "{id=604795,Text='默认对话20',Speaker=1000,}",
  [604796] = "{id=604796,Text='选项对话1',Speaker=1000,Option='{是,3},{否,4}',}",
  [604797] = "{id=604797,Text='选项对话1',Speaker=1000,Option='{是,5},{否,6}',}",
  [604798] = "{id=604798,Text='深渊之湖的潮汐开始紊乱，敏锐的时空龙奥斯卡察觉到了异常——时空乱流回收站中有人脱逃。作为回收这个世界“错误存在”的空间，时空乱流回收站对维持世界的平衡至关重要，因此守护它的重任一直由龙族承担。\n时空龙奥斯卡迅速召唤冒险者，一同前往深渊之湖的湖心秘境。这里不仅是时空乱流回收站的所在地，也是龙族的栖息之地，此前未有人类踏足。然而，当他们抵达时，眼前的一幕令人心惊：一场惨烈的龙族内战刚刚结束，血迹斑斑的地面中赫然出现了可疑的人类脚印。顺着脚印，他们来到了天地树下，发现它正遭受破坏，而罪魁祸首似乎正是天地树下的神秘人类。\n事情进展顺利的令人意外，时空龙奥斯卡在这名神秘人的身上发现了与时空乱流回收站出逃者相匹配的信息，决定将其带回回收站进行调查。幸运的是，在冒险者的解释下，误会得以澄清——神秘人是刺客公会的会长无名者，他感应到深渊之湖发生了破坏平衡的事件，特地前来调查。尽管如此，时空龙奥斯卡对误判无名者为出逃者一事仍持保留态度，认为事情远未结束。\n在扑灭天地树燃起的熊熊烈火过程中，三人逐渐了解到，这场大火只是深渊之湖混乱的冰山一角。大火褪去后，更多的问题浮出水面：赤炎龙与黑炎龙因是否带领龙族子民离开深渊之湖而产生了激烈的纷争，另外真正破坏天地树的并非大火，而是被出逃者感染根部的那股力量。\n为了寻找线索，三人深入感染的根部，而无名者却受到了来自出逃者的力量影响，陷入了混乱的记忆之中，也因此时空龙奥斯卡判断，出逃者与无名者之间或许存在着某种联系。时空龙奥斯卡和冒险者进入无名者的记忆，却看到一个人影将记忆带入神殿之中，只是那里充满迷雾，无法看出记忆中的人影到底是谁。但神殿的出现，却让时空龙奥斯卡则忆起那神殿曾经驻守过神族，也许在那里可以找到治愈天地树的办法。\n无名者与冒险者抵达神殿后，却发现这里早已荒为遗迹，神影不再降临。然而，经过二人的努力，神影终于显现，并揭示了治愈天地树的方法——需要前往龙息祭台打开龙息之锁，获取存放在时空裂隙中的原初之力，唯有原初之力才能治愈天地树。\n然而，当他们成功打开龙息之锁后，却发现所谓的原初之力并不存在。原来，从神影的出现开始，一切都是出逃者的诡计。他真正目的是夺走时空龙奥斯卡的真身，利用其强大的力量驱动时空矩阵，彻底打开时空乱流回收站，释放所有时空垃圾，从而引发更大的灾难。\n就在关键时刻，时空龙奥斯卡赶到，带来了重要的信息——治愈天地树的办法需要收集四颗龙族之星，它们分别来自时空龙奥斯卡、赤炎龙蕾蒂西亚、黑炎龙参宿四以及尼德霍格。而第一颗龙族之星，就藏在时空龙奥斯卡的真身之中，眼前的奥斯卡不过是分身而已。\n因此，三人必须前往时空矩阵，找到时空龙奥斯卡的真身，关闭时空矩阵，获得第一颗龙族之星。\n当解除出逃者对时空龙奥斯卡的操控后，奥斯卡真身苏醒，郑重地将第一颗龙族之星交给了二人。随着龙族之星的力量注入天地树根，微弱的光芒开始闪烁，众人感受到了一丝希望。这一刻，天地树得到第一次治愈，而未来的战斗才刚刚拉开帷幕。',}",
  [632169] = "{id=632169,Text='（在风中抖了抖花瓣）……',Speaker=821381,}",
  [632170] = "{id=632170,Text='（这朵花有种微妙的熟悉感……难不成是布兰迪斯新学会的伪装？）',Option='{拔起来,0},{戳一戳,0}',Emoji=8,}",
  [632171] = "{id=632171,Text='（被触碰到的一瞬间，眼前的花瞬间瑟缩起来，枝叶蜷成一团。）',}",
  [632172] = "{id=632172,Text='（尖叫）大、大大大胆！异世界的冒险者，你要杀人吗！',Speaker=821381,Option='{你不是小布？,0},{…你是谁？,0}',Emoji=18,}",
  [632173] = "{id=632173,Text='打听这干嘛？我只是来问你几句话。',Speaker=821381,}",
  [632174] = "{id=632174,Text='（花朵的声音很模糊，像是刻意改变了音色。）',}",
  [632175] = "{id=632175,Text='……[c][ffff00]布兰迪斯失踪了[-][/c]。你知道这件事么？',Speaker=821381,Option='失踪？！',}",
  [632176] = "{id=632176,Text='哦，看来不知道。这就怪了，你们不是关系不错么，他没来找你？',Speaker=821381,Option='{（沉默）,0},{与你无关吧,0}',}",
  [632177] = "{id=632177,Text='嘴可真严。',Speaker=821381,}",
  [632178] = "{id=632178,Text='（顿了顿）那我换个问法。布兰迪斯最近到底经历了什么？你告诉我，也许从中能得知他的去向。',Speaker=821381,}",
  [632179] = "{id=632179,Text='（这朵花语气古怪，背后的身份也不明……它怎么急切地打听这些，到底打的什么主意？）',}",
  [632180] = "{id=632180,Text='……还犹豫干嘛？你就不想找到他吗？！我可是来帮你的！',Speaker=821381,Emoji=12,}",
  [632181] = "{id=632181,Text='（是否要告诉这它，布兰迪斯和自己之前的遭遇？）',Option='{告诉,2},{不告诉,3}',}",
  [632182] = "{id=632182,Text='（抖了抖花瓣）……呵，倒是比我想象的爽快。',Speaker=821381,}",
  [632183] = "{id=632183,Text='事情和我猜的差不多。谢谢你告诉我这些~不过呢，一切也就到此为止了。',Speaker=821381,Option='什么意思',}",
  [632184] = "{id=632184,Text='（抖了抖花瓣）一个字都不肯说啊……你还真是布兰迪斯的好朋友。',Speaker=821381,}",
  [632185] = "{id=632185,Text='不过呢，即使你保持沉默，我也有其他手段找得到他。所以……',Speaker=821381,Option='所以什么',}",
  [632186] = "{id=632186,Text='哈。还没明白？',Speaker=821381,Emoji=5,}",
  [632187] = "{id=632187,Text='——你已经没有利用价值了。',Speaker=821381,}",
  [632188] = "{id=632188,Text='（话音刚落，眼前的花挥动枝叶，在空中飞快闪过了一道白光！）',}",
  [632189] = "{id=632189,Text='好久不见了，[c][ffff00][PlayerName][-][/c]。',Speaker=821382,Option='什么人？！',}",
  [632190] = "{id=632190,Text='（可恶……被暗算了！这家伙……到底是什么来头……）',Emoji=15,}",
  [632191] = "{id=632191,Text='（嘲弄地）看你这表情，不会是还想跟我打一架吧？就你？',Speaker=821382,}",
  [632192] = "{id=632192,Text='哈哈哈哈！你现在真是弱的令我发笑！',Speaker=821382,}",
  [632193] = "{id=632193,Text='[c][ffff00][PlayerName][-][/c]，既然中了毒，就老老实实在这里等死吧。',Speaker=821382,}",
  [632194] = "{id=632194,Text='（自言自语）可算是让我报了之前在[c][ffff00]天津町[-][/c]的仇！真是痛快！',Speaker=821382,}",
  [632195] = "{id=632195,Text='（天津町、天津町……不行，越想越晕了……）',}",
  [632196] = "{id=632196,Text='别挣扎了，[c][ffff00][PlayerName][-][/c]~',Speaker=821382,}",
  [632197] = "{id=632197,Text='（尽管努力想要集中精神，可视线还是越来越模糊……）',}",
  [632198] = "{id=632198,Text='……你不该动他。',Speaker=821395,}",
  [632199] = "{id=632199,Text='（等等，这个声音难道是——）',Emoji=7,}",
  [632200] = "{id=632200,Text='哈哈哈哈！！布兰迪斯，太好了，没想到你自己竟然送上门来！',Speaker=821382,}",
  [632201] = "{id=632201,Text='现在告诉我浮空精灵的[c][ffff00]秘宝[-][/c]在哪，我就饶了这家伙一命！！',Speaker=821382,Option='{（他的目标…）,0},{（是秘宝！）,0}',}",
  [632202] = "{id=632202,Text='说什么鬼话呢？有我在，他不会有事的。',Speaker=821383,Option='（布兰迪斯…）',}",
  [632203] = "{id=632203,Text='（冷冷地看着眼黑影）都说了——你、不该、动他。',Speaker=821383,}",
  [632204] = "{id=632204,Text='咳、咳咳……布兰迪斯……你等着……',Speaker=821382,}",
  [632205] = "{id=632205,Text='废话真多。要么滚，要么死，你选一个？',Speaker=821383,}",
  [632206] = "{id=632206,Text='（这人像是被布兰迪斯的气势唬住了，似乎有所忌惮。最终，他只是狠狠啐了一声。）',}",
  [632207] = "{id=632207,Text='……别得意，[c][ffff00]那位大人不会放过你们的[-][/c]！这笔账，来日再算！',Speaker=821382,Emoji=12,}",
  [632208] = "{id=632208,Text='哼，溜的倒快。',Speaker=821383,}",
  [632209] = "{id=632209,Text='（布兰迪斯利落地帮自己解了毒，可全程板着个脸，像棵被霜打的星降花。）',Option='{布兰迪斯？,0},{布布？,0}',}",
  [632210] = "{id=632210,Text='……很快那群守卫就要来了，先离开这。',Speaker=821383,}",
  [632213] = "{id=632213,Text='（银发少年盯着自己看了看，片刻后像是败下阵来一般叹了口气。）',}",
  [632216] = "{id=632216,Text='（闷声闷气）那个混蛋……如果不是我及时赶到，你现在早就没命了。',Speaker=821383,Option='他是谁',}",
  [632217] = "{id=632217,Text='你不知道？听他的意思，你们应该认识。',Speaker=821383,Option='{感觉熟悉,0},{不能确定,0}',Emoji=8,}",
  [632219] = "{id=632219,Text='本来想假装不知道的。让他放松警惕，自以为伪装的滴水不漏。',Speaker=821383,}",
  [632221] = "{id=632221,Text='（布兰迪斯闻言，忽然有些不自在地别过了脸。）',}",
  [632226] = "{id=632226,Text='（认真地摇头）抗议无效。拒绝救命恩人的请求，这不道德。',Speaker=821383,}",
  [632227] = "{id=632227,Text='对了，一定要找[c][ffff00]发着蓝光[-][/c]的月光三角兽啊。它们有点暴躁，注意安全。',Speaker=821383,Option='……哦！',}",
  [632229] = "{id=632229,Text='（嗯？那不是小妖精的萨满……维维塔·坎波吗！）',}",
  [632230] = "{id=632230,Text='（难道布兰迪斯是要和他说[c][ffff00]悄悄话[-][/c]，因此故意把自己支开？）',Option='{有点不爽,0},{有点兴奋,0}',}",
  [632231] = "{id=632231,Text='布布，这、这太冒险了！我不同意！现在我们的敌人，可是那个芙蕾雅女神啊……！',Speaker=821415,Emoji=18,}",
  [632232] = "{id=632232,Text='（淡淡地）慌什么慌。',Speaker=821414,}",
  [632233] = "{id=632233,Text='谁说我要一个人去了？我还有[c][ffff00][PlayerName][-][/c]呢。',Speaker=821414,}",
  [632234] = "{id=632234,Text='……喂喂，你跟[c][ffff00][PlayerName][-][/c]才认识多久啊！就真的这么放心？',Speaker=821415,}",
  [632235] = "{id=632235,Text='（毫不犹豫地）当然了。他是我亲自认证的共犯。',Speaker=821414,}",
  [632236] = "{id=632236,Text='好嘛。既然你都这么说了，那我再怎么劝也是没用的。',Speaker=821415,}",
  [632237] = "{id=632237,Text='（布兰迪斯望着满脸委屈的小妖精，忽然伸手戳了戳他的脑袋。）',}",
  [632238] = "{id=632238,Text='噫！好吓人，你干嘛！！',Speaker=821415,Emoji=15,}",
  [632239] = "{id=632239,Text='表示安慰。',Speaker=821414,Emoji=30,}",
  [632240] = "{id=632240,Text='……维维塔。现在[c][ffff00]昏睡病[-][/c]也[c][ffff00]蔓延[-][/c]到了小妖精一族，你身为萨满，是绝不可能置之不理的。',Speaker=821414,}",
  [632241] = "{id=632241,Text='好吧……你是对的。',Speaker=821415,}",
  [632242] = "{id=632242,Text='更何况，[c][ffff00]密米尔[-][/c]老师还在[c][ffff00]昏睡[-][/c]，可[c][ffff00]彩虹桥[-][/c]就快[c][ffff00]修复完成[-][/c]了……',Speaker=821414,}",
  [632243] = "{id=632243,Text='（叹气）我明白你的意思。布布，放心[c][ffff00]去找秘宝[-][/c]吧，剩下的事我会处理好。',Speaker=821415,Emoji=14,}",
  [632244] = "{id=632244,Text='找到真相以后，记得活着回来啊。',Speaker=821415,}",
  [632245] = "{id=632245,Text='……出来吧，还想躲多久？',Speaker=821414,Option='（被发现了！）',}",
  [632246] = "{id=632246,Text='都听到了？',Speaker=821383,Option='{点头,0},{摇头,0}',}",
  [632247] = "{id=632247,Text='……以后不用躲着，站在旁边听就可以。',Speaker=821383,}",
  [632248] = "{id=632248,Text='（少年蔚蓝的双瞳间，掠过一丝淡淡的笑意。但只是片刻后，他便垂下了眼眸。）',}",
  [632249] = "{id=632249,Text='现在的情况很不好。彩虹桥正逐渐被修复……而昏睡病蔓延到了小妖精，密米尔老师也再次沉睡不醒。',Speaker=821383,Option='怎么会这样',}",
  [632250] = "{id=632250,Text='（淡淡地）还没到终局，谁输谁赢不一定呢。',Speaker=821383,}",
  [632251] = "{id=632251,Text='刚才和维维塔都商量好了。他留下照看小妖精一族，继续寻机会破坏彩虹桥——而我们两个，去找秘宝。',Speaker=821383,Option='秘宝！',}",
  [632252] = "{id=632252,Text='没错。找到秘宝，我们就有了与芙蕾雅抗衡的力量。',Speaker=821383,}",
  [632253] = "{id=632253,Text='[c][ffff00]“无垢的晨曦与夜空之星，将于风中寻回失落的秘宝，重构彩虹的辉光。”[-][/c]',Speaker=821383,}",
  [632254] = "{id=632254,Text='芙蕾雅想必清楚这条预言的含义。为了追查秘宝的下落，她一直在让人监视我。',Speaker=821383,}",
  [632255] = "{id=632255,Text='……恐怕她也想不到，派出的人会被我揍一顿再赶回去吧。',Speaker=821383,Option='等等……',}",
  [632256] = "{id=632256,Text='（女神如果得知监视失败，肯定会采取更极端的手段对付我们啊！所以为什么要放人回去——）',Option='表示忧虑',}",
  [632257] = "{id=632257,Text='（瞥了你一眼）就会瞎操心。',Speaker=821383,}",
  [632258] = "{id=632258,Text='那个女人害了我的亲人和恩师，本来就没必要对她客气。',Speaker=821383,}",
  [632259] = "{id=632259,Text='虽然，我原本是打算保守点，再忍一阵那乱七八糟的监视的。',Speaker=821383,Option='那为什么改主意',}",
  [632260] = "{id=632260,Text='……谁让刚才，[c][ffff00]你差点就被她的手下害死了！[-][/c]',Speaker=821383,Emoji=12,}",
  [632261] = "{id=632261,Text='（银发少年抿了抿唇，望着艾卡拉奇的方向。此刻，他的眼神锐利如寒夜的星霜。）',}",
  [632262] = "{id=632262,Text='（轻声）竟敢连续伤害我重要的人……这一笔笔血债，我忍不下，也不想忍。',Speaker=821383,Option='布兰迪斯……',}",
  [632263] = "{id=632263,Text='芙蕾雅做的事越是见不得光，我就越要坦坦荡荡。所以，我决定放走监视者。',Speaker=821383,}",
  [632264] = "{id=632264,Text='通过那个蠢货，便可以明明白白地告诉那个女人——布兰迪斯，不惧怕任何人。',Speaker=821383,}",
  [632265] = "{id=632265,Text='[c][ffff00]这世界上，没有任何人能阻止我的决定。[-][/c]哪怕是神，也不例外！',Speaker=821383,}",
  [632266] = "{id=632266,Text='（没、没想到自己中了一回毒，竟然能让布兰迪斯做出如此的觉悟，几乎是正面和女神宣战……）',Option='{真是罪过！,0},{心情复杂…,0}',}",
  [632267] = "{id=632267,Text='呃，我刚才都说了什么啊……',Speaker=821383,}",
  [632268] = "{id=632268,Text='…………！！',Speaker=821383,Option='你在念叨什么？',Emoji=1,}",
  [632269] = "{id=632269,Text='（银发少年闻声回过头，像是被吓了一跳。但他随后便调整了情绪，神色恢复如常。）',}",
  [632270] = "{id=632270,Text='[c][ffff00][PlayerName][-][/c]，经过慎重考虑，我觉得有必要郑重声明一件事。',Speaker=821383,}",
  [632271] = "{id=632271,Text='（一本正经）请不要误会刚才的发言。我可不是因为你受伤，才决定挑衅芙蕾雅的。就是突然想这么做而已。',Speaker=821383,Option='{可你之前？,0},{不是这么说的？,0}',}",
  [632272] = "{id=632272,Text='（面不改色）……是你被毒傻了，所以听错了话。',Speaker=821383,Option='……',}",
  [632273] = "{id=632273,Text='（布兰迪斯依旧云淡风轻地说着胡话。但是这家伙恐怕没想到，泛红的耳根出卖了他的谎言。）',Option='{幸灾乐祸,0},{假装没看到,0}',}",
  [632274] = "{id=632274,Text='……先不提这些了！你之前不是去找三角兽的毛了吗，快拿出来。',Speaker=821383,}",
  [632275] = "{id=632275,Text='站好了，不要动。',Speaker=821383,}",
  [632276] = "{id=632276,Text='（布兰迪斯伸出手——飞快拔下了自己的一根[c][ffff00]头发[-][/c]！！）',Option='{嘶……！,0},{还我头发！,0}',}",
  [632277] = "{id=632277,Text='……大惊小怪。',Speaker=821383,}",
  [632278] = "{id=632278,Text='接下来，我会留下一道魔力的印痕。你跟着印痕施法看看。',Speaker=821383,Option='你要干什么',}",
  [632279] = "{id=632279,Text='这个，收好了。',Speaker=821383,}",
  [632282] = "{id=632282,Text='（少年的睫羽颤了颤。此刻他的眼中，泛着一片柔软的银河。）',Speaker=821383,}",
  [632289] = "{id=632289,Text='（笃定地）秘宝就在这里。',Speaker=821383,Option='怎么知道的？',}",
  [632290] = "{id=632290,Text='[c][ffff00]“无垢的晨曦与夜空之星，将于风中寻回失落的秘宝，重构彩虹的辉光。”[-][/c]',Speaker=821383,}",
  [632291] = "{id=632291,Text='……塞西莉亚姐姐离去后，这条预言应验了。我能感觉到，在这片花开之地的某处，有股特殊的魔力在召唤我。',Speaker=821383,Option='特殊魔力！',}",
  [632292] = "{id=632292,Text='嗯。它缥缈但纯粹，而且极其灵动，仿佛拥有生命一般……这些年来，我从未见过这样的魔力。',Speaker=821383,}",
  [632293] = "{id=632293,Text='——这只可能是秘宝的力量。',Speaker=821383,Option='有道理',}",
  [632294] = "{id=632294,Text='芙蕾雅估计察觉到了什么。你看[c][ffff00]西侧的小路[-][/c]，有许多[c][ffff00]极光之翼[-][/c]把守。',}",
  [632295] = "{id=632295,Text='我们如果往西侧走，倒是条近路……但为了安全，需要特殊的伪装。',Speaker=821383,}",
  [632296] = "{id=632296,Text='而[c][ffff00]东侧的路[-][/c]上弥漫着[c][ffff00]毒雾[-][/c]。走那里可能会慢一些，但是能避开守卫们。',Speaker=821383,Emoji=14,}",
  [632297] = "{id=632297,Text='[c][ffff00][PlayerName][-][/c]，你想走哪条路？',Speaker=821383,Option='{有守卫的西侧,0},{有毒雾的东侧,0}',}",
  [632298] = "{id=632298,Text='听你的，走吧。',Speaker=821383,}",
  [632299] = "{id=632299,Text='（皱眉）……这些雾气，长期吸入会中毒。',Speaker=821383,Emoji=14,}",
  [632300] = "{id=632300,Text='不管你选哪条路，我都会负责让你安全通过的。',Speaker=821383,}",
  [632301] = "{id=632301,Text='看来必须要快速通过这里才行。',Speaker=821383,Option='快走吧',}",
  [632302] = "{id=632302,Text='糟糕。停留太久，好像中毒了，我来解毒……小心前进！',Emoji=18,}",
  [632303] = "{id=632303,Text='……笨、笨蛋，被发现了！',Speaker=821383,}",
  [632304] = "{id=632304,Text='还好我飞得快，及时带你跑回来了。',Speaker=821383,}",
  [632305] = "{id=632305,Text='……再试一次吧。不着急，仔细点。',Speaker=821383,Emoji=14,}",
  [632306] = "{id=632306,Text='我们到了。',Speaker=821383,}",
  [632307] = "{id=632307,Text='要是决定好了，就走吧。',Speaker=821383,}",
  [632308] = "{id=632308,Text='……情况不妙啊。',Speaker=821383,Option='想想办法？',}",
  [632309] = "{id=632309,Text='办法有是有，不过你得努努力。',Speaker=821383,}",
  [632310] = "{id=632310,Text='你瞧。这么多守卫，直接开打的话，动静会闹得很大。这恐怕会直接暴露我们的位置。',Speaker=821383,Option='所以？',}",
  [632311] = "{id=632311,Text='所以——既然无法正面决战，那就用点小技巧。',Speaker=821383,}",
  [632312] = "{id=632312,Text='嗯。完美的变装！他们一眼绝对分不出来真假。',Speaker=821383,Emoji=9,}",
  [632313] = "{id=632313,Text='（抽了抽嘴角）……就是稍微丑了点。',Speaker=821383,Option='那你呢？？',}",
  [632314] = "{id=632314,Text='你问我吗？',Speaker=821383,}",
  [632315] = "{id=632315,Text='（话音刚落，布兰迪斯便消失了。片刻后，一朵星降花晃晃悠悠地落在了口袋里……）',Option='盯着星降花',}",
  [632316] = "{id=632316,Text='——我会很安静地躺着，默默给你加油鼓劲。',Speaker=821385,}",
  [632317] = "{id=632317,Text='我们就快到了。',Speaker=821385,}",
  [632321] = "{id=632321,Text='（布兰迪斯的身上，正散发着不可思议的蓝色光芒——）',}",
  [632322] = "{id=632322,Text='（这、这个地方原来有这么多[c][ffff00]发光的花[-][/c]吗？！）',Option='询问布兰迪斯',}",
  [632323] = "{id=632323,Text='……笨蛋，以前才没有这些。',Speaker=821383,Emoji=15,}",
  [632324] = "{id=632324,Text='而且你发现了吗？我们不知不觉间，进入了一个结界。那些魔物和守卫都不见了。',Speaker=821383,Option='确实',}",
  [632325] = "{id=632325,Text='恐怕是因为我们的到来……这个地方才出现了变化。',Speaker=821383,}",
  [632326] = "{id=632326,Text='（看着花朵，若有所思）恐怕只有解开它们的秘密，才能找到秘宝的所在。',Speaker=821383,}",
  [632327] = "{id=632327,Text='（伴随着光芒闪过，一枚银色指环正静静悬立于蔚云与花海之间。）',}",
  [632328] = "{id=632328,Text='（怔怔地）这就是……浮空精灵失落的秘宝之一。',Speaker=821383,}",
  [632329] = "{id=632329,Text='（少年望着面前寂静的指环，双手紧握，几乎要攥出血痕。他的眼中掠过万千思绪，席卷成即将肆虐的风暴。）',}",
  [632330] = "{id=632330,Text='哥哥……密米尔老师……塞西莉亚姐姐……',Speaker=821383,}",
  [632331] = "{id=632331,Text='——他们不惜牺牲一切也要守住的秘密，就是这一枚小小的指环吗？！',Speaker=821383,}",
  [632333] = "{id=632333,Text='（布兰迪斯凝视着旋转的秘宝，眼里的风暴渐渐化作了一声叹息。他松开了原先紧攥的手，像是自嘲一般摇了摇头。）',}",
  [632334] = "{id=632334,Text='……难以想象，看起来如此脆弱易碎的东西，竟然成了我们最后的希望。',Speaker=821383,}",
  [632336] = "{id=632336,Text='一起看看这戒指里，到底藏着怎样的秘密。',Speaker=821383,}",
  [632337] = "{id=632337,Text='（随着两人的触碰，指环上渐渐浮现出了几行银色的小字……）',}",
  [632338] = "{id=632338,Text='“ 逆位的星辰  击碎了他燃烧的行迹  在此间寻觅风的踪影”',Speaker=821386,}",
  [632339] = "{id=632339,Text='“ 异乡之风 眷恋彗光的静谧 他携来寂寂银河 将吹至云端去”',Speaker=821386,}",
  [632340] = "{id=632340,Text='“我在此长眠 堆皱了逝去的幻影  见它们吟诵着谎言的余音“ ',Speaker=821386,}",
  [632341] = "{id=632341,Text='“那些蝴蝶的羽翼 于我梦中 拂过遗忘的誓言 交叠消弭的命运  ”',Speaker=821386,}",
  [632342] = "{id=632342,Text='（似乎被指环带到了一座辉煌的宫殿之中……）',}",
  [632343] = "{id=632343,Text='怎么可能……这是辰星殿堂！',Speaker=821383,Option='辰星殿堂？',Emoji=1,}",
  [632344] = "{id=632344,Text='嗯。这是历代大祭司的住处，平时几乎没有人可以进入。我哥哥……就曾经住在这里。',Speaker=821383,}",
  [632345] = "{id=632345,Text='……怎么还不来呢。',Speaker=821387,}",
  [632346] = "{id=632346,Text='这个声音是……塞、塞塞西莉亚姐姐？！',Speaker=821383,}",
  [632347] = "{id=632347,Text='姐姐，是我啊，布兰迪斯！',Speaker=821383,}",
  [632348] = "{id=632348,Text='……她为什么不理我？',Speaker=821383,}",
  [632349] = "{id=632349,Text='（低垂着眼眸，像是在思考什么）……',Speaker=821387,Option='{塞西莉亚？,0},{魔女姐姐？,0}',}",
  [632350] = "{id=632350,Text='（彗光的魔女依然沉默着，就像是完全没有注意到屋里还有其他人。）',Option='（完全没反应…）',}",
  [632351] = "{id=632351,Text='……我知道了，[c][ffff00][PlayerName][-][/c]。',Speaker=821383,}",
  [632352] = "{id=632352,Text='现在这个情况，我们恐怕被指环带进了某段[c][ffff00]过去的记忆[-][/c]里。',Speaker=821383,Option='没错',}",
  [632353] = "{id=632353,Text='看起来，这个空间是无法被未来的力量干涉的……我们只能在旁边观察事情的发展。',Speaker=821383,Emoji=15,}",
  [632354] = "{id=632354,Text='（低声）好不甘心啊。',Speaker=821383,}",
  [632355] = "{id=632355,Text='（好像有人来了！）',}",
  [632356] = "{id=632356,Text='（在柔软的金光中，渐渐出现了一名浮空精灵的身影。那双泉水似的眼眸与云雾般的长发——正是前任大祭司，卡德。）',}",
  [632357] = "{id=632357,Text='哥哥……',Speaker=821383,}",
  [632358] = "{id=632358,Text='（抬起双眸）你回来了。这一切到底是怎么回事？',Speaker=821387,}",
  [632359] = "{id=632359,Text='辉煌领域即将迎来最严峻的挑战。那位象征美丽的[c][ffff00]女神[-][/c]，完全不像她的外表一样无害。',Speaker=821388,Option='（是芙蕾雅…）',}",
  [632360] = "{id=632360,Text='她[c][ffff00]觊觎[-][/c]着精灵族的[c][ffff00]秘宝[-][/c]，因此，我将秘宝[c][ffff00]分为两半[-][/c]藏了起来。',Speaker=821388,}",
  [632361] = "{id=632361,Text='一半秘宝，我交给了[c][ffff00]克莱尔老师[-][/c]保管。而另一半，放在了只有我们两个人知道的地方。',Speaker=821388,}",
  [632362] = "{id=632362,Text='[c][ffff00]“无垢的晨曦与夜空之星，将于风中寻回失落的秘宝，重构彩虹的辉光。”[-][/c]这是密米尔为此做出的预言。',Speaker=821388,}",
  [632363] = "{id=632363,Text='晨曦与星吗……',Speaker=821387,}",
  [632364] = "{id=632364,Text='莉亚……等时机到来，若是预言中预示的两人出现——请你和克莱尔老师，为他们指明方向。',Speaker=821388,}",
  [632365] = "{id=632365,Text='（塞西莉亚望着爱人的微笑，眼眸中的冰雪渐渐消融。）',}",
  [632366] = "{id=632366,Text='（轻声）……好。',Speaker=821387,}",
  [632367] = "{id=632367,Text='我以日月和星光起誓，绝不会违背与你的约定。',Speaker=821387,}",
  [632368] = "{id=632368,Text='（这是之前的那条水晶石项链……卡德要做什么？）',}",
  [632369] = "{id=632369,Text='……不会是我想的那样吧！？',Speaker=821383,}",
  [632370] = "{id=632370,Text='卡德，这是——',Speaker=821387,}",
  [632371] = "{id=632371,Text='我将[c][ffff00]守护的咒文[-][/c]注入了这条项链里……它可以抵御这个世上绝大多数的伤害。',Speaker=821388,Option='（守护的咒文…）',Emoji=14,}",
  [632372] = "{id=632372,Text='（年轻的大祭司注视着他的未婚妻，眼中满是愧疚与怜惜。）',}",
  [632373] = "{id=632373,Text='……抱歉，莉亚。我可能此生没办法给你一个婚礼了。',Speaker=821388,}",
  [632374] = "{id=632374,Text='希望我不在的时候，它可以护你平安。',Speaker=821388,}",
  [632375] = "{id=632375,Text='东西我收下。不过，现在我得去和克莱尔会合了。',Speaker=821387,Emoji=14,}",
  [632376] = "{id=632376,Text='（塞西莉亚将项链收入怀中。那张清丽冷然的面容上，第一次露出了微笑。）',}",
  [632377] = "{id=632377,Text='（她望向卡德，就像在注视着夜色下那最后一朵星降花。）',}",
  [632378] = "{id=632378,Text='……至于婚礼，就先欠着吧。',Speaker=821387,}",
  [632379] = "{id=632379,Text='再见了，卡德。',Speaker=821387,}",
  [632380] = "{id=632380,Text='……再见，莉亚。',Speaker=821388,}",
  [632381] = "{id=632381,Text='（怎么回事？！为什么感觉整个宫殿都要塌了……！）',}",
  [632382] = "{id=632382,Text='[c][ffff00][PlayerName][-][/c]，怪事！这些碎石是真的能砸到人！快躲一躲——',Speaker=821383,}",
  [632383] = "{id=632383,Text='卡德、卡德！成功了！[c][ffff00]彩虹桥[-][/c]已经被我[c][ffff00]摧毁[-][/c]了！',Speaker=821389,}",
  [632384] = "{id=632384,Text='记住，[c][ffff00]决不能让芙蕾雅回到神域[-][/c]——',Speaker=821389,}",
  [632385] = "{id=632385,Text='我会信守诺言，密米尔。',Speaker=821388,}",
  [632386] = "{id=632386,Text='希望你们都平安无事……',Speaker=821388,}",
  [632387] = "{id=632387,Text='（原来，卡德和密米尔合作摧毁彩虹桥，是为了阻止芙蕾雅重返神域！）',}",
  [632388] = "{id=632388,Text='（那这就是说……芙蕾雅一定是在神域筹谋了什么[c][ffff00]危险的计划[-][/c]……）',Emoji=11,}",
  [632389] = "{id=632389,Text='（轻声）……这是有什么人，要来了。',Speaker=821383,}",
  [632390] = "{id=632390,Text='（这个女人……是现任的大祭司，女神的神使贞奴比亚！！）',}",
  [632391] = "{id=632391,Text='贵安，卡德阁下。不知道您是否察觉了刚才的震动？',Speaker=821390,}",
  [632392] = "{id=632392,Text='嗯，有感觉到。',Speaker=821388,}",
  [632393] = "{id=632393,Text='（贞奴比亚纤长的双眸微微眯起，像是要把卡德看透一般。）',}",
  [632394] = "{id=632394,Text='……卡德阁下好像并不惊讶啊。刚才的震动，可是彩虹桥断裂引起的。',Speaker=821390,}",
  [632395] = "{id=632395,Text='哦，是吗。',Speaker=821388,}",
  [632396] = "{id=632396,Text='您如此淡定，真不愧是辉煌领域的大祭司。',Speaker=821390,Emoji=14,}",
  [632397] = "{id=632397,Text='女神大人特意让我来邀请阁下，希望您可以带领浮空精灵们协助修复彩虹桥。',Speaker=821390,}",
  [632398] = "{id=632398,Text='（挑了挑眉）……同时，审判摧毁彩虹桥的罪魁祸首——智慧巨人密米尔。',Speaker=821390,}",
  [632399] = "{id=632399,Text='别理她，哥哥！！',Speaker=821383,}",
  [632400] = "{id=632400,Text='抱歉，我不能答应。',Speaker=821388,}",
  [632401] = "{id=632401,Text='我是绝不会让女神冕下重返神域——去实现那个“[c][ffff00]世界清理计划[-][/c]”的。',Speaker=821388,Option='{世界清理计划？！,0},{那是什么？！,0}',}",
  [632402] = "{id=632402,Text='（贞奴比亚闻言，露出讶异的笑容。她勾了勾手指，瞬间，一道道紫色的光芒于她的掌心凝聚。）',}",
  [632403] = "{id=632403,Text='……你知道的不少。那么只好再见了，大祭司阁下。',Speaker=821390,}",
  [632404] = "{id=632404,Text='（糟糕！那是芙蕾雅女神的紫蝴蝶————）',Emoji=1,}",
  [632405] = "{id=632405,Text='……不，快离开那里！哥哥！！',Speaker=821383,}",
  [632406] = "{id=632406,Text='（布兰迪斯尝试将那些紫蝴蝶赶走。可不管他怎么努力，那些蝴蝶依旧织成了细密的网，将卡德紧紧包围——）',}",
  [632407] = "{id=632407,Text='哥哥……不……',Speaker=817667,}",
  [632408] = "{id=632408,Text='到此为止了，卡德阁下。',Speaker=821390,}",
  [632409] = "{id=632409,Text='……看来……确实就到此为止了……',Speaker=808450,}",
  [632410] = "{id=632410,Text='（卡德似乎想起来什么值得怀念的事物。他轻轻闭上眼，像是释然般地笑了。）',}",
  [632411] = "{id=632411,Text='我这一生，没有什么可遗憾的。',Speaker=808450,}",
  [632412] = "{id=632412,Text='哥哥………不要…………',Speaker=817667,}",
  [632413] = "{id=632413,Text='（轻声）……如果说唯一后悔的事，恐怕就是……没有和他好好道别吧……',Speaker=808450,Option='卡德！！',}",
  [632414] = "{id=632414,Text='……小布…抱歉……',Speaker=808450,}",
  [632415] = "{id=632415,Text='哥哥——！！！！',Speaker=817667,}",
  [632416] = "{id=632416,Text='（卡德身上的金色光芒，渐渐化作了浮光与尘埃，散落在了空气中……）',}",
  [632417] = "{id=632417,Text='终于结束了。',Speaker=821390,}",
  [632418] = "{id=632418,Text='啊呀……看来这一切，都很顺利。',Speaker=821391,}",
  [632419] = "{id=632419,Text='做得好，亲爱的贞奴比亚。',Speaker=821391,}",
  [632420] = "{id=632420,Text='（是芙蕾雅女神——她为什么会出现在这里？！）',}",
  [632421] = "{id=632421,Text='芙蕾雅大人，感谢您的垂怜。',Speaker=821390,}",
  [632422] = "{id=632422,Text='如果不是您的紫蝶及时降临，对上这个卡德大祭司，我恐怕还需要再费些功夫。',Speaker=821390,}",
  [632423] = "{id=632423,Text='（女神抿唇笑了笑，神情一如既往地慵懒温柔。）',}",
  [632424] = "{id=632424,Text='不用客气，亲爱的贞奴比亚。卡德嘛……倒是可惜了。',Speaker=821391,}",
  [632425] = "{id=632425,Text='这么美好可爱的小虫，如果不是要拿他[c][ffff00]做别的用处[-][/c]……真想带回去做成玩偶啊。',Speaker=821391,}",
  [632426] = "{id=632426,Text='（微微睁大眼）啊呀……亲爱的贞奴比亚，你看我发现了什么？',Speaker=821391,}",
  [632427] = "{id=632427,Text='这个卡德，竟然没有带上历代大祭司的[c][ffff00]守护符文[-][/c]呀！怪不得，这么轻松就死掉了~',Speaker=821391,Option='{那个守护咒文…,0},{给了塞西莉亚……,0}',}",
  [632428] = "{id=632428,Text='（芙蕾雅女神像是发现了什么新鲜的玩具，好奇又渴望地看着卡德的遗体。）',}",
  [632429] = "{id=632429,Text='他会把符文给了谁呢？是冷冰冰的未婚妻……还是那个矮小的大贤者？',Speaker=821391,Emoji=8,}",
  [632430] = "{id=632430,Text='真有趣啊。亲爱的贞奴比亚，稍后就[c][ffff00]把那两人请回来[-][/c]，好好慰问一番吧。',Speaker=821391,}",
  [632431] = "{id=632431,Text='遵命，芙蕾雅大人。',Speaker=821390,}",
  [632432] = "{id=632432,Text='啊呀，差点忘记了正事。我已经把那个[c][ffff00]碍事的老头子[-][/c]，关在[c][ffff00]时间花园[-][/c]了。',Speaker=821391,Option='密米尔……',}",
  [632433] = "{id=632433,Text='以防万一，我还[c][ffff00]封住了他的嘴[-][/c]，让他不能提及关于我的任何事~',Speaker=821391,Option='卑鄙！',}",
  [632434] = "{id=632434,Text='（忧愁地叹息）可是闹的动静太大，被[c][ffff00]很多浮空精灵看到了[-][/c]啊，好苦恼。',Speaker=821391,}",
  [632435] = "{id=632435,Text='……您有什么想法？',Speaker=821390,}",
  [632436] = "{id=632436,Text='眼前这只小虫，他的躯壳……恰好可以让我施展一个有趣的[c][ffff00]小法术[-][/c]。',Speaker=821391,}",
  [632437] = "{id=632437,Text='（慢悠悠地）我要让所有的浮空精灵闭嘴——让他们忘却应该忘却的，记得理应记得的——',Speaker=821391,}",
  [632438] = "{id=632438,Text='来帮我一下，亲爱的贞奴比亚。我们一起完成这个法术吧。',Speaker=821391,}",
  [632439] = "{id=632439,Text='遵命，芙蕾雅大人。',Speaker=821390,}",
  [632440] = "{id=632440,Text='辛苦你了，亲爱的贞奴比亚。',Speaker=821391,Option='修改记忆……',Emoji=9,}",
  [632441] = "{id=632441,Text='现在，所有普通浮空精灵的[c][ffff00]记忆[-][/c]，都被我好好的[c][ffff00]修改[-][/c]过了哦。',Speaker=821391,}",
  [632442] = "{id=632442,Text='（眨了眨眼）亲爱的贞奴比亚，现在开始，你就是辉煌领域[c][ffff00]新的大祭司[-][/c]啦。',Speaker=821391,}",
  [632443] = "{id=632443,Text='原来的呢？',Speaker=821390,}",
  [632444] = "{id=632444,Text='原来的那个呀，不是和密米尔一起，成了砸毁彩虹桥的[c][ffff00]叛徒[-][/c]吗？',Speaker=821391,}",
  [632445] = "{id=632445,Text='芙蕾雅……原来一切都是你干的……',Speaker=821383,}",
  [632446] = "{id=632446,Text='最后他无法面对公允慈悲的女神，选择痛快的自杀了！是个敢作敢当的叛徒呢！',Speaker=821391,}",
  [632447] = "{id=632447,Text='（女神笑的十分开怀。蝴蝶的羽翼倒映在她的眸中，凝固成一片看不见底的深海。）',}",
  [632448] = "{id=632448,Text='亲爱的贞奴比亚，你看我说的怎么样？',Speaker=821391,}",
  [632449] = "{id=632449,Text='您说的每一个字，都是完美的。',Speaker=821390,}",
  [632450] = "{id=632450,Text='谢谢你，亲爱的贞奴比亚。不过，我这副身体终究还联系着天地树，现在必须回去休息了哦。',Speaker=821391,}",
  [632451] = "{id=632451,Text='浮空精灵的[c][ffff00]秘宝[-][/c]……这件事，就拜托你了~',Speaker=821391,}",
  [632452] = "{id=632452,Text='当然，芙蕾雅大人。我从不会让您失望。',Speaker=821390,}",
  [632453] = "{id=632453,Text='（看来，虚妄之戒里的回忆，就到此为止了……）',}",
  [632455] = "{id=632455,Text='（少年深吸了一口气，强忍着痛苦与愤怒，咬着牙说出了接下来的话。）',}",
  [632457] = "{id=632457,Text='所有的这一切，我都将让它们铭刻进我的灵魂，永世不忘。',Speaker=821383,}",
  [632460] = "{id=632460,Text='（是之前给自己下毒的人！想必也就是他，一直监视布兰迪斯……）',}",
  [632461] = "{id=632461,Text='你们跑得倒快，叫我好找。',Speaker=821382,Option='你到底是谁？',}",
  [632462] = "{id=632462,Text='这不重要！只要知道，我是来杀你们的就行了~',Speaker=821382,}",
  [632463] = "{id=632463,Text='听我一句劝——赶紧把拿到的[c][ffff00]秘宝[-][/c]交出来，还能死的痛快点！',Speaker=821382,}",
  [632464] = "{id=632464,Text='——哼，就凭你？别开玩笑了！',Speaker=821383,}",
  [632465] = "{id=632465,Text='呵呵……我还真是……小瞧了你们……',Speaker=821392,}",
  [632466] = "{id=632466,Text='看来……是时候……让你们感受真正的恐惧了…………',Speaker=821392,}",
  [632467] = "{id=632467,Text='……小心，有什么东西要出现了！',Speaker=821383,}",
  [632468] = "{id=632468,Text='（阿卡娜？！怎么可能，她不是早就被贞奴比亚处决了吗——）',Option='难道说…！！',}",
  [632469] = "{id=632469,Text='能以原本的姿态重新见到你，我可真是高兴啊，[c][ffff00][PlayerName][-][/c]。',Speaker=821393,Option='你没？！',Emoji=5,}",
  [632470] = "{id=632470,Text='哼，当然没有。贞奴比亚大人待我亲如姐妹，怎么可能伤害我？',Speaker=821393,}",
  [632471] = "{id=632471,Text='（果然……从见到芙蕾雅女神的那一刻起，自己眼前的一切，都是她精心编织的骗局。）',}",
  [632472] = "{id=632472,Text='[c][ffff00][PlayerName][-][/c]，还有布兰迪斯——以现在的状态，你们是打不过我的。',Speaker=821393,}",
  [632473] = "{id=632473,Text='[c][ffff00]交出秘宝[-][/c]，也许我能向女神大人给你们求求情。怎么样？',Speaker=821393,Option='不可能！',}",
  [632474] = "{id=632474,Text='……不用跟这个疯子多说。 ',Speaker=821383,}",
  [632475] = "{id=632475,Text='（银发少年望着阿卡娜，眼中的光芒冷冽而决绝。）',}",
  [632476] = "{id=632476,Text='（可恶……阿卡娜的实力和之前完全不是一个级别的……）',Emoji=18,}",
  [632477] = "{id=632477,Text='（这样下去，我和布兰迪斯会越来越吃力的！）',}",
  [632478] = "{id=632478,Text='咳、咳咳……差不多了。',Speaker=821383,}",
  [632479] = "{id=632479,Text='[c][ffff00][PlayerName][-][/c]，闭上眼睛。',Speaker=821383,}",
  [632480] = "{id=632480,Text='（这是……结界？！布兰迪斯要做什么？）',}",
  [632481] = "{id=632481,Text='（皱着脸）咳、咳咳……',Speaker=821383,Option='你受伤了！',}",
  [632482] = "{id=632482,Text='不碍事。没有时间了，我就说几句话。',Speaker=821383,}",
  [632483] = "{id=632483,Text='（布兰迪斯定定望着自己。那双原本淡漠疏离的双瞳，此刻像是蕴藏着千言万语。）',}",
  [632484] = "{id=632484,Text='其实，我——',Speaker=821383,Option='什么？',}",
  [632485] = "{id=632485,Text='（别过脸）……算了，不重要。',Speaker=821383,}",
  [632486] = "{id=632486,Text='接稳了，别弄丢。',Speaker=821383,}",
  [632487] = "{id=632487,Text='（一个冷冰冰的东西，落到了自己怀里。）',}",
  [632488] = "{id=632488,Text='（这、这是浮空精灵的秘宝，[c][ffff00]虚妄之戒[-][/c]啊——！！）',Option='询问布兰迪斯',}",
  [632489] = "{id=632489,Text='大惊小怪，给你就拿着。',Speaker=821383,}",
  [632490] = "{id=632490,Text='（叹了口气，解释道）阿卡娜是来抢秘宝的。我是夜空之星，她绝对会一直盯着我。',Speaker=821383,}",
  [632491] = "{id=632491,Text='——所以，我偏就要把这戒指交给你。',Speaker=821383,}",
  [632492] = "{id=632492,Text='等离开这以后，就要拜托你把另一半秘宝凑齐了。',Speaker=821383,Option='什么！',}",
  [632493] = "{id=632493,Text='……密米尔老师的预言绝不会错。另一半秘宝一定会让晨曦的圣女，[c][ffff00]赫蒂[-][/c]找到。',Speaker=821383,}",
  [632494] = "{id=632494,Text='（低声）你也知道，彩虹桥很快就要修复完成。',Speaker=821383,}",
  [632495] = "{id=632495,Text='只有合成完整的秘宝，才有希望阻止芙蕾雅回到神域。',Speaker=821383,Option='那你呢？',}",
  [632496] = "{id=632496,Text='（少年闻言愣了一瞬，垂下双眸，遮住了眼底的情绪。）',Emoji=9,}",
  [632497] = "{id=632497,Text='我的事，不用你瞎操心。',Speaker=821383,}",
  [632498] = "{id=632498,Text='……唔，看来时间快到了。',Speaker=821383,}",
  [632499] = "{id=632499,Text='之前我给你的那块星星护符，还收着吗？',Speaker=821383,}",
  [632500] = "{id=632500,Text='（看到这块护符，布兰迪斯的目光柔软了许多。）',}",
  [632501] = "{id=632501,Text='还记得吗？我曾经说过，这块护符是一个[c][ffff00]约定[-][/c]。',Speaker=821383,Option='约定……',}",
  [632502] = "{id=632502,Text='我曾对着护符许下愿望……让它保佑我珍视的朋友永远平安。',Speaker=821383,}",
  [632503] = "{id=632503,Text='现在到了兑现它的时候了。',Speaker=821383,}",
  [632504] = "{id=632504,Text='（护符中散发出的银色光芒，渐渐包裹住了自己……而布兰迪斯的声音越来越轻，就好像要去往遥远的天空。)',}",
  [632505] = "{id=632505,Text='别乱动。它会让你安全离开的，[c][ffff00][PlayerName][-][/c]。',Speaker=821383,}",
  [632506] = "{id=632506,Text='（不好，这个结界要崩溃了！他怎么还在往里走！）',Option='{布兰迪斯！！,0},{你要去哪！！,0}',}",
  [632507] = "{id=632507,Text='自然是要去做我想做的事了。',Speaker=821383,}",
  [632508] = "{id=632508,Text='（这家伙……不会是要离开结界，自己单独跟阿卡娜战斗吧？！）',Option='{强行阻止他！,0},{跟他讲道理！,0}',}",
  [632509] = "{id=632509,Text='……噗。你又不是第一天认识我了，我是会听劝的人吗？',Speaker=821383,Option='{你不是…,0},{你可以是,0}',Emoji=9,}",
  [632510] = "{id=632510,Text='（少年弯起眼眸，露出一个粲然的笑来。就像是夜空中第一颗划过的流星，只照亮那初见之人的心上。）',}",
  [632511] = "{id=632511,Text='[c][ffff00]这个世界上，没有任何人能阻止我的决定。[-][/c]',Speaker=821383,}",
  [632512] = "{id=632512,Text='……如果真的担心我，就照顾好自己。',Speaker=821383,}",
  [632513] = "{id=632513,Text='（茫茫之中，微风掠过少年的银发，纷飞的花瓣拂起他的衣角。）',}",
  [632514] = "{id=632514,Text='（天空倒映成他的眼眸，洒落月与辰光于那双瞳中。）',}",
  [632515] = "{id=632515,Text='（而在少年抬起手的一瞬，万千星河于他的身侧闪耀。）',Option='{布兰迪斯！,0},{别死啊！,0}',}",
  [632516] = "{id=632516,Text='放心，不会输的。',Speaker=821383,}",
  [632517] = "{id=632517,Text='我可是你的共犯。',Speaker=821383,}",
  [632518] = "{id=632518,Text='（护符带来的光芒，渐渐让自己陷入困意。）',}",
  [632519] = "{id=632519,Text='（眼中最后看到的，是银发少年冷冽而决意的背影。）',}",
  [632520] = "{id=632520,Text='（……不要有事啊，布兰迪斯。）',}",
  [632521] = "{id=632521,Text='“ 逆位的星辰  击碎了他燃烧的行迹  在此间寻觅风的踪影”',}",
  [632522] = "{id=632522,Text='“ 异乡之风 眷恋彗光的静谧 他携来寂寂银河 将吹至云端去”',}",
  [632523] = "{id=632523,Text='“我在此长眠 堆皱了逝去的幻影  见它们吟诵着谎言的余音“ ',}",
  [632524] = "{id=632524,Text='“那些蝴蝶的羽翼 于我梦中 拂过遗忘的誓言 交叠消弭的命运  ”',}",
  [632525] = "{id=632525,Text='我暂时解除了毒的影响……尽快离开！',Speaker=821383,}",
  [632526] = "{id=632526,Text='啧，比想象中还要棘手。',Speaker=821383,}",
  [632527] = "{id=632527,Text='我们来制造米米怪的幻象，吸引极光之翼的注意力，可以趁机溜过去。',Speaker=821383,}",
  [632528] = "{id=632528,Text='怎么回事……？',Speaker=821383,}",
  [632529] = "{id=632529,Text='（布兰迪斯强烈的感情波动……让这片空间开始变得不稳定了！！）',}",
  [632530] = "{id=632530,Text='……看来，需要先修复这些空间的碎片，存储于此的记忆才会继续。',Speaker=821383,}",
  [632531] = "{id=632531,Text='（现在应该可以继续观察戒指中的记忆了……）',}",
  [632532] = "{id=632532,Text='也许，我们应该找到这些[c][ffff00]闪光的花朵[-][/c]。',Speaker=821383,}",
  [632533] = "{id=632533,Text='注意在花的边上[c][ffff00]多停留一阵[-][/c]，这样才能观察到它们的特殊之处。',Speaker=821383,}",
  [632534] = "{id=632534,Text='这朵花在发光，要仔细观察一下。',Speaker=821383,}",
  [632535] = "{id=632535,Text='是闪光的花！走近些看看……',Speaker=821383,}",
  [632536] = "{id=632536,Text='就是这朵花了。留点心，看看它有什么特别的地方。',Speaker=821383,}",
  [632537] = "{id=632537,Text='做的不错。',Speaker=821383,}",
  [632538] = "{id=632538,Text='离秘宝又更进一步了。',Speaker=821383,}",
  [632539] = "{id=632539,Text='等下你就知道了。',Speaker=821383,}",
  [632540] = "{id=632540,Text='看来刚才你的注意力不够集中。再试一次吧？',Speaker=821383,Option='{再来！,3},{先等等,2}',}",
  [632541] = "{id=632541,Text='她一旦回去，就会让[c][ffff00]九界彻底陷入黑暗[-][/c]之中——',Speaker=821389,}",
  [632546] = "{id=632546,Text='无限书库，怎么会变成这样？！',}",
  [632547] = "{id=632547,Voice='Npc_Quest/632547',Text='如你所见——伊米尔之书失窃了。',Speaker=826569,}",
  [632548] = "{id=632548,Voice='Npc_Quest/632548',Text='多日之前，达纳托斯塔发生异动，沉寂多年的魔剑再次复苏，并逃出封印。',Speaker=826569,Picture='new_npc_pic_27',}",
  [632549] = "{id=632549,Voice='Npc_Quest/632549',Text='我的神识追踪它来到这里，发现它的力量已经恢复到能幻化出人形了。',Speaker=826569,Picture='new_npc_pic_26',}",
  [632550] = "{id=632550,Voice='Npc_Quest/632550',Text='尽管我重创了它，但仅仅我的神识没能阻止它夺走伊米尔之书。',Speaker=826569,Picture='new_npc_pic_25',Option='它有什么目的？',}",
  [632551] = "{id=632551,Voice='Npc_Quest/632551',Text='为了力量，伊米尔之书中蕴含着的英雄之力。',Speaker=826569,Option='{展开说说？,0},{英雄之力？,0}',}",
  [632552] = "{id=632552,Voice='Npc_Quest/632552',Text='伊米尔之书中记载了英雄们的故事，这些文字中蕴含着强大的力量。',Speaker=826569,}",
  [632553] = "{id=632553,Voice='Npc_Quest/632553',Text='这力量不止是这些英雄本身的力量，还蕴含着他们的意志与决心。',Speaker=826569,}",
  [632554] = "{id=632554,Voice='Npc_Quest/632554',Text='伊米尔之书是命运女神留给众生的宝物，这些英雄之力一直守护着这个世界。',Speaker=826569,Option='{那现在怎么办？,0},{我现在马上出发！,0}',}",
  [632555] = "{id=632555,Voice='Npc_Quest/632555',Text='所幸，即使盗走了伊米尔之书，也会因缺少“钥匙”无法激活英雄之力。',Speaker=826569,Option='钥匙？',}",
  [632556] = "{id=632556,Voice='Npc_Quest/632556',Text='是原本镶嵌在扉页上宝石。据文献记载，它名为[c][ffff00]命运宝石[-][/c]，存放在“生命起源之地”——赫瓦格密尔。',Speaker=826569,}",
  [632557] = "{id=632557,Voice='Npc_Quest/632557',Text='但这个消息并不隐秘，魔剑极有可能也知道命运宝石的下落。',Speaker=826569,}",
  [632558] = "{id=632558,Voice='Npc_Quest/632558',Text='必须赶在魔剑之前找到宝石，并将它保护起来。这样，我们才能争取更多的时间。',Speaker=826569,Option='{明白了 ,0},{交给我吧,0}',}",
  [632559] = "{id=632559,Voice='Npc_Quest/632559',Text='我的本体暂时还无法离开达纳托斯塔，我的神识将与你一同行动。',Speaker=826569,}",
  [632560] = "{id=632560,Voice='Npc_Quest/632560',Text='立刻前往赫瓦格密尔。',Speaker=826569,}",
  [632564] = "{id=632564,Voice='Npc_Quest/632564',Text='如果气息消失，可以再次使用“感知”。',Speaker=826569,}",
  [632567] = "{id=632567,Voice='Npc_Quest/632567',Text='命运宝石应该就在这片区域，使用“感知”对这里进行调查。',Speaker=826569,}",
  [632568] = "{id=632568,Voice='Npc_Quest/632568',Text='发现线索，及时汇报。',Speaker=826569,}",
  [632569] = "{id=632569,Text='地面上留着浅浅的足迹，有人来到过这地方……',Speaker=826570,}",
  [632570] = "{id=632570,Text='但诡异的是，足迹附近的植物，都凋零枯萎了下去。',Speaker=826570,}",
  [632571] = "{id=632571,Text='石碑风化严重，只能勉强辨认出些许文字：',Speaker=826571,}",
  [632572] = "{id=632572,Text='……的王，遭遇至亲的背叛……她的身影自云端陨落，于生命之泉长眠。',Speaker=826571,}",
  [632573] = "{id=632573,Text='然而，时光将抚平创伤……坟墓也能孕育新生。',Speaker=826571,}",
  [632574] = "{id=632574,Text='我等……族至高的王，终将归来！',Speaker=826571,}",
  [632575] = "{id=632575,Text='越接近湖水的地方，花草越是茂密，生机勃勃。',Speaker=826572,}",
  [632576] = "{id=632576,Text='一块蓝色宝石漂浮在水中。',Speaker=826573,}",
  [632577] = "{id=632577,Text='水底竟然沉睡着一名少女，而她的手里捧着这块蓝色宝石！',}",
  [632578] = "{id=632578,Text='这块宝石的气息……似乎就是一直在寻找的命运宝石！',}",
  [632579] = "{id=632579,Voice='Npc_Quest/632579',Text='情况如何？还需要继续调查吗？',Speaker=826569,Option='{继续调查,3},{调查完成,2}',}",
  [632580] = "{id=632580,Voice='Npc_Quest/632580',Text='嗯，注意，需细心谨慎。',Speaker=826569,}",
  [632581] = "{id=632581,Voice='Npc_Quest/632581',Text='这里，没什么还值得留意的。',Speaker=826569,}",
  [632582] = "{id=632582,Voice='Npc_Quest/632582',Text='说说你的调查结果。',Speaker=826569,Option='蓝色宝石',}",
  [632583] = "{id=632583,Voice='Npc_Quest/632583',Text='宝石……那应该就是命运宝石。',Speaker=826569,}",
  [632584] = "{id=632584,Voice='Npc_Quest/632584',Text='无论如何，先将宝石取到手。',Speaker=826569,}",
  [632585] = "{id=632585,Text='吾乃天地树之饲育者，命运宝石之守护者！',Speaker=826574,}",
  [632586] = "{id=632586,Text='无耻窃贼，别想对命运宝石下手！',Speaker=826574,}",
  [632587] = "{id=632587,Voice='Npc_Quest/632587',Text='她很强大，我会将神识的最后一缕力量交与你。',Speaker=826569,}",
  [632588] = "{id=632588,Voice='Npc_Quest/632588',Text='无论用什么手段，命运宝石必须拿到，接下去，交给你了。',Speaker=826569,}",
  [632589] = "{id=632589,Voice='Npc_Quest/632589',Text='宵小之徒，你定会后悔今日行为。',Speaker=826574,}",
  [632590] = "{id=632590,Voice='Npc_Quest/632590',Text='哼，挺厉害的嘛……那么，你能否接下这招！',Speaker=826574,}",
  [632591] = "{id=632591,Voice='Npc_Quest/632591',Text='住手、守护……疯女人，远离……朋友！',Speaker=826575,}",
  [632592] = "{id=632592,Voice='Npc_Quest/632592',Text='诶？吾、吾知道了啦！妹妹！快停手，别再损耗你的力量了！',Speaker=826574,}",
  [632593] = "{id=632593,Voice='Npc_Quest/632593',Text='疯女人、离我……远点！',Speaker=826575,}",
  [632594] = "{id=632594,Voice='Npc_Quest/632594',Text='等等，回来！妹妹！妹妹！维德！达纳托斯，达纳托斯——！',Speaker=826574,}",
  [632595] = "{id=632595,Voice='Npc_Quest/632595',Text='唉，算了。还是先解决眼前的麻烦吧！',Speaker=826574,}",
  [632596] = "{id=632596,Voice='Npc_Quest/632596',Text='好了，小毛贼，别以为吾妹袒护你，你就可以为所欲为。',Speaker=826574,}",
  [632597] = "{id=632597,Voice='Npc_Quest/632597',Text='直视吾的眼睛——是谁指使你来偷窃宝石，又打算拿它做什么！',Speaker=826574,Option='说明情况',}",
  [632598] = "{id=632598,Voice='Npc_Quest/632598',Text='什么！伊米尔之书被一个叫魔剑的东西偷走了！所以，你是为了转移宝石才来到这里？',Speaker=826574,}",
  [632599] = "{id=632599,Voice='Npc_Quest/632599',Text='什么啊……这么重要的事情，你怎么不早说？',Speaker=826574,Option='{没有解释的机会,14},{是我没有说清楚,13}',}",
  [632600] = "{id=632600,Voice='Npc_Quest/632600',Text='哼，区区凡人，竟然敢顶撞吾？看在刚才精彩战斗的份上，你之放肆，吾宽恕了~',Speaker=826574,Option='您是？',}",
  [632601] = "{id=632601,Voice='Npc_Quest/632601',Text='嗯～你这个凡人，不错。吾对你很满意～',Speaker=826574,Option='您是？',}",
  [632602] = "{id=632602,Voice='Npc_Quest/632602',Text='咳咳，吾乃天地之树饲育者，堕夜之救赎者，原初之龙尼德霍格。',Speaker=826574,}",
  [632603] = "{id=632603,Voice='Npc_Quest/632603',Text='吾是众生之长、天地之灵的龙族女王，命运宝石之守护者。',Speaker=826574,}",
  [632604] = "{id=632604,Voice='Npc_Quest/632604',Text='吾确实应当将宝石交由你，但吾现在有一件必须完成的事需要宝石的力量。',Speaker=826601,Option='是什么事情？',}",
  [632605] = "{id=632605,Voice='Npc_Quest/632605',Text='这件事说来话长，先把吾的姊妹哄回来，吾再解答你的困惑。',Speaker=826601,Option='{你的姊妹？,0},{你不会是指……,0}',}",
  [632606] = "{id=632606,Voice='Npc_Quest/632606',Text='就是达纳托斯啦，前世的他叫做维德佛尔尼尔，是吾唯一的血亲、世界上最亲密的伴侣。',Speaker=826601,Option='{…… ,0},{？？？,0}',}",
  [632607] = "{id=632607,Voice='Npc_Quest/632607',Text='他似乎认识你……你是否知道他究竟是怎么变成只能游荡在梦境中的残魂？',Speaker=826601,Option='{达纳托斯塔 ,0},{大战梦罗克,0}',}",
  [632608] = "{id=632608,Voice='Npc_Quest/632608',Text='什么！竟然是梦罗克那个混蛋！……怎么会……',Speaker=826601,}",
  [632609] = "{id=632609,Voice='Npc_Quest/632609',Text='吾知道了。走，吾和你一起去找他。',Speaker=826601,}",
  [632621] = "{id=632621,Voice='Npc_Quest/632621',Text='在诸神黄昏之战后，吾陷于沉睡中来修复力量。',Speaker=826576,}",
  [632622] = "{id=632622,Voice='Npc_Quest/632622',Text='吾妹维德佛尔尼尔也在那场大战时失去了生命。',Speaker=826576,}",
  [632623] = "{id=632623,Voice='Npc_Quest/632623',Text='吾和她之间过去发生了很多，也有着很多误解……',Speaker=826576,}",
  [632624] = "{id=632624,Voice='Npc_Quest/632624',Text='吾原以为和她永远无法相见，没想到今天……',Speaker=826576,}",
  [632625] = "{id=632625,Voice='Npc_Quest/632625',Text='有个残魂进入了吾之梦中，他的灵魂中有吾妹的气息。',Speaker=826576,}",
  [632626] = "{id=632626,Voice='Npc_Quest/632626',Text='吾知道，这就是她的转世！吾将残魂带出了梦境……',Speaker=826576,}",
  [632627] = "{id=632627,Voice='Npc_Quest/632627',Text='吾一定会修复他的灵魂，让吾妹再次回在这个世界上。',Speaker=826576,}",
  [632641] = "{id=632641,Voice='Npc_Quest/632641',Text='如今的达纳托斯，只是个濒临破碎的残魂，是吾强行将他从梦境中带出。',Speaker=826576,}",
  [632642] = "{id=632642,Voice='Npc_Quest/632642',Text='但吾的力量还没有完全恢复，只能借助命运宝石来支撑他的残魂不会消散。',Speaker=826576,Option='为何强行带出？',}",
  [632643] = "{id=632643,Voice='Npc_Quest/632643',Text='吾——没有办法，只有将他带出梦境，才有办法重塑他的灵魂。',Speaker=826576,}",
  [632644] = "{id=632644,Voice='Npc_Quest/632644',Text='所以，你想要带走宝石，就得帮助吾重塑他的灵魂。',Speaker=826576,Option='{为什么是我？ ,0},{我能做什么？,0}',}",
  [632645] = "{id=632645,Voice='Npc_Quest/632645',Text='吾……和维德佛尔尼尔有些误会，她一直厌恶着吾。',Speaker=826576,}",
  [632646] = "{id=632646,Voice='Npc_Quest/632646',Text='即使转世成为达纳托斯，他亦厌恶着吾……呜呜……吾不难过！吾不难过……',Speaker=826576,}",
  [632647] = "{id=632647,Voice='Npc_Quest/632647',Text='但他很亲近你……有你的陪伴，他或许就不会逃离吾的身边了吧……',Speaker=826576,Option='{我会陪着他的！,51},{我也很能打！,52}',}",
  [632648] = "{id=632648,Voice='Npc_Quest/632648',Text='谢谢，吾会好好保护你这个凡人的。',Speaker=826576,}",
  [632649] = "{id=632649,Voice='Npc_Quest/632649',Text='凡人，你很狂妄，不过吾并不讨厌这样。',Speaker=826576,}",
  [632650] = "{id=632650,Voice='Npc_Quest/632650',Text='接下来，吾会去寻死亡女神海拉，这个世上没有人比她更了解灵魂。',Speaker=826576,}",
  [632651] = "{id=632651,Voice='Npc_Quest/632651',Text='但达纳托斯的意识仍然有些模糊，他还需要一些时间休息。',Speaker=826576,}",
  [632652] = "{id=632652,Voice='Npc_Quest/632652',Text='等他彻底稳定下来，吾就带你等前往尼夫海姆。',Speaker=826576,}",
  [632672] = "{id=632672,Text='不过吾担心在这个小空间内，吾的气息会引发混乱。',Speaker=826576,}",
  [632675] = "{id=632675,Text='哟，这不是[c][ffff00][PlayerName][-][/c]嘛！你怎么又来到尼夫海姆了？莫非……你已经……',Speaker=826579,Option='{你诅咒我！,0},{我还活着！,0}',}",
  [632676] = "{id=632676,Text='哈哈，别生气，一个玩笑～来！久别重逢，我们为彼此调制一杯友谊之酒如何？',Speaker=826579,}",
  [632677] = "{id=632677,Text='怎么样？这可是我专门为你调制的死灵之酒，喝下去就能让你的气息变得和[c][ffff00]死灵一模一样][-][/c]！',Speaker=826579,Option='{哦？,0},{真的吗？,0}',}",
  [632678] = "{id=632678,Text='哪怕是奥丁喝下这杯酒！他也会变成亡灵奥丁！嘿嘿～都是为了你能更好的在尼夫海姆玩耍嘛！',Speaker=826579,}",
  [632679] = "{id=632679,Text='嗯～你调的酒也不错，人类的酒，好久没有品尝过了。为了友谊干杯！',Speaker=826579,Option='干杯！',}",
  [632680] = "{id=632680,Text='唉，好想进入埃琉德尼尔宫啊，想要让海拉陛下训斥我～鞭打我呢～～',Speaker=826580,}",
  [632681] = "{id=632681,Text='别想了，除非我们的贡品被陛下的两位侍从选中，否则根本没有资格[c][ffff00]上殿觐见[-][/c]啊！',Speaker=826581,}",
  [632682] = "{id=632682,Text='可恶啊！如果我能像[c][ffff00]约姆家[-][/c]一样，种出又大又圆、媲美黄金的南瓜就好了！',Speaker=826580,}",
  [632683] = "{id=632683,Text='要不，我去求求他们，分我们几个南瓜吧！',Speaker=826580,}",
  [632684] = "{id=632684,Text='别想了，老约姆去转生之后，那三个吝啬鬼兄弟之间争南瓜都争个不停！哪里会给我们！',Speaker=826581,}",
  [632685] = "{id=632685,Text='你看，他们三还在那吵吵嚷嚷的呢！',Speaker=826581,}",
  [632686] = "{id=632686,Text='呜呜呜，不说了，喝酒喝酒……',Speaker=826580,}",
  [632687] = "{id=632687,Text='咱妈说老子才是大哥！老鬼的南瓜产业应该由老子全部继承！！',Speaker=826584,}",
  [632688] = "{id=632688,Text='咱妈谁不知道？[c][ffff00]撒谎鬼！[-][/c]说的话没有一句是真的！',Speaker=826585,}",
  [632689] = "{id=632689,Text='就是就是！你可不能为了独吞海拉女神的赏赐胡说八道！',Speaker=826586,}",
  [632690] = "{id=632690,Text='老鬼的遗产咱们三个平分不好吗？大家都是差不多时间出生的[c][ffff00]三胞胎[-][/c]！',Speaker=826585,}",
  [632691] = "{id=632691,Text='唔……要是能知道到底谁是大哥就好了……',Speaker=826586,Option='有什么能帮助你的？',}",
  [632692] = "{id=632692,Text='嗯？你很面生啊！但是看着，很聪明的样子！正好帮忙分析分析！',Speaker=826586,}",
  [632693] = "{id=632693,Text='咱约姆兄弟是三胞胎，一直搞不清楚咱们自己的出生顺序。',Speaker=826586,}",
  [632694] = "{id=632694,Text='咱妈曾经透露过三句话，但是她是个[c][ffff00]撒谎鬼[-][/c]，说的每一句都是谎话！',Speaker=826586,}",
  [632695] = "{id=632695,Text='你帮忙分析分析，通过这三句谎话，能知道咱们三个人的出生顺序吗？',Speaker=826586,}",
  [632696] = "{id=632696,Text='你帮忙分析分析，通过这三句谎话，能知道咱们三个人的出生顺序吗？\n咱妈说：贝克是老大，杰克不是老三，福特是老二。那谁是老大？',Speaker=826586,Option='{杰克,2},{贝克,2},{福特,3}',}",
  [632697] = "{id=632697,Text='不对，我觉得不对劲。',Speaker=826586,}",
  [632698] = "{id=632698,Text='原来是老子啊！老子就说贝克肯定就是个臭弟弟！老子知道了！老子可以夺回产业了！',Speaker=826586,}",
  [632699] = "{id=632699,Text='对了！感谢你帮老子想清楚了困惑多年的问题！这些南瓜种子就送你吧！',Speaker=826586,}",
  [632700] = "{id=632700,Text='这种子种出来的南瓜做出来的南瓜派啊！可是海拉大人都赞不绝口！',Speaker=826586,}",
  [632701] = "{id=632701,Text='[c][ffff00]明天[-][/c]我就领着两个蠢弟弟按时给海拉大人送南瓜去了！',Speaker=826586,}",
  [632702] = "{id=632702,Text='啊～美妙的音乐～咯咯……流淌～轻抚～',Speaker=826583,Option='{真好听,0},{好悲伤,0}',}",
  [632703] = "{id=632703,Text='哦～这位大人也是懂音乐的～咯咯……来～让我们共弹一首曲子！献给我们伟大的海拉女神～',Speaker=826583,}",
  [632704] = "{id=632704,Text='咯咯……希望我们的演奏可以抚平海拉女神心中的悲伤……',Speaker=826583,Option='海拉怎么了？ ',}",
  [632705] = "{id=632705,Text='从某一天开始，咯咯……她将自己禁闭在[c][ffff00]埃琉德尼尔宫殿[-][/c]，悲伤笼罩着她……',Speaker=826583,}",
  [632706] = "{id=632706,Text='如此的悲伤……或许……是谁，永远离开了她，咯咯……',Speaker=826583,}",
  [632707] = "{id=632707,Text='两个吊死鬼常规售卖的酒，深受很多死灵的喜爱。',Speaker=826587,}",
  [632708] = "{id=632708,Text='来人！～来人……给我打包点……嗝——[c][ffff00]赫尔饼[-][/c]！',Speaker=826582,}",
  [632709] = "{id=632709,Text='不然……加尔姆大人……可要生气的……它最喜欢……最喜欢赫尔饼了……',Speaker=826582,}",
  [632710] = "{id=632710,Text='酒馆的一道下酒菜，客人们都非常爱点。',Speaker=826589,}",
  [632711] = "{id=632711,Text='不知道是谁做的料理，散发着黑暗的气息，无人问津。',Speaker=826588,}",
  [632712] = "{id=632712,Voice='Npc_Quest/632712',Text='酒……喜欢……死……不喜欢……',Speaker=826600,}",
  [632713] = "{id=632713,Voice='Npc_Quest/632713',Text='回去……希尔斯……想……伙伴……',Speaker=826600,}",
  [632715] = "{id=632715,Voice='Npc_Quest/632715',Text='吾刚刚听死灵的谈话，死亡女神一直待在埃琉德尼尔宫殿，不允许任何人进入，如何是好？',Speaker=826601,}",
  [632719] = "{id=632719,Voice='Npc_Quest/632719',Text='可是，吾等的气息如果进入宫殿一定会被发现吧？尤其是吾……',Speaker=826601,}",
  [632722] = "{id=632722,Voice='Npc_Quest/632722',Text='还有，听说死亡女神的寝宫一直由她的爱犬加尔姆看守……有什么办法可以引开它吗？',Speaker=826601,}",
  [632733] = "{id=632733,Text='生命之源，请听吾的召唤——',Speaker=826576,}",
  [632734] = "{id=632734,Text='滋养大地，赋予生命！',Speaker=826576,}",
  [632735] = "{id=632735,Text='唔……',Speaker=826576,}",
  [632736] = "{id=632736,Text='吾，天地最初之龙，献出龙鳞！助你一臂之力！',Speaker=826576,}",
  [632737] = "{id=632737,Voice='Npc_Quest/632737',Text='呼……呼……呼……',Speaker=826576,Option='{你没事吧？！,0},{你做了什么？,0}',}",
  [632738] = "{id=632738,Voice='Npc_Quest/632738',Text='血……血的气味……受伤……不……',Speaker=826575,}",
  [632739] = "{id=632739,Voice='Npc_Quest/632739',Text='无事，吾只是取了一片龙鳞，帮助这些南瓜快速成熟。',Speaker=826576,}",
  [632740] = "{id=632740,Voice='Npc_Quest/632740',Text='痛……人……难受……',Speaker=826575,}",
  [632741] = "{id=632741,Voice='Npc_Quest/632741',Text='无事，都是值得的，你曾陪吾见证过斗转星移，你，是吾无可替代的妹妹。',Speaker=826576,}",
  [632742] = "{id=632742,Voice='Npc_Quest/632742',Text='现在，只要等待南瓜成熟，吾等就可前往死亡女神的宫殿。',Speaker=826576,}",
  [632743] = "{id=632743,Voice='Npc_Quest/632743',Text='达纳托斯，吾之姊妹……这一次，吾一定会救你。',Speaker=826576,}",
  [632766] = "{id=632766,Voice='Npc_Quest/632766',Text='带着南瓜进来吧。',Speaker=826599,}",
  [632767] = "{id=632767,Voice='Npc_Quest/632767',Text='潜入埃琉德尼尔大成功！吾等很快就能见到海拉了～',Speaker=826576,Option='{需要小心谨慎 ,0},{毕竟是海拉的地盘,0}',}",
  [663471] = "{id=663471,Voice='Npc_Quest/663471',Text='是的，这就是这个世界的风格，麻烦总是不断产生的。',Speaker=829775,}",
  [663472] = "{id=663472,Voice='Npc_Quest/663472',Text='在爱丽丝被启动后，整个时空都产生了混乱，就在我辛辛苦苦修补这些问题的时候……',Speaker=829775,}",
  [663473] = "{id=663473,Voice='Npc_Quest/663473',Text='梦罗克却利用此空隙，企图盗取属于那个时空藏于吉芬尼亚的伊米尔之心碎片。',Speaker=829775,Option='吉芬尼亚？',}",
  [663474] = "{id=663474,Voice='Npc_Quest/663474',Text='过去的吉芬，还并未形成现在的格局，那时，人们还称它为吉芬尼亚。',Speaker=829775,}",
  [663475] = "{id=663475,Voice='Npc_Quest/663475',Text='我当然不能让梦罗克得逞，所以才发生了刚才的事情。可恶。',Speaker=829775,}",
  [663476] = "{id=663476,Voice='Npc_Quest/663476',Text='我猜测他又回到了吉芬尼亚施行自己的阴谋。',Speaker=829775,}",
  [663477] = "{id=663477,Voice='Npc_Quest/663477',Text='在那时的吉芬尼亚上的邪恶势力都盯着那块碎片，现在又来了一个梦罗克。真替守护伊米尔之心碎片的德古拉家族捏把汗。',Speaker=829775,Option='德古拉？',}",
  [663478] = "{id=663478,Voice='Npc_Quest/663478',Text='跟随我的魔法，我会带你认识德古拉。总之，这一次还是和以前一样，让历史停留在过去的样子。走吧！',Speaker=829775,}",
  [663479] = "{id=663479,Voice='Npc_Quest/663479',Text='我的魔法无法穿透笼罩吉芬尼亚的迷雾，这里似乎被一种很强大的魔法控制。',Speaker=829775,}",
  [663480] = "{id=663480,Voice='Npc_Quest/663480',Text='所以，只能将你送到这里了。',Speaker=829775,}",
  [663481] = "{id=663481,Voice='Npc_Quest/663481',Text='那个引发一切混乱的伊米尔之心碎片在过去的吉芬一直由德古拉家族守护。',Speaker=829775,}",
  [663482] = "{id=663482,Voice='Npc_Quest/663482',Text='不过，现在我找不到德古拉的藏身之处，也看不到他。不如你自己想象一下？',Speaker=829775,Option='开始想象',}",
  [663483] = "{id=663483,Voice='Npc_Quest/663483',Text='德古拉家族是一个拥有千年历史的古老家族。',Speaker=829775,}",
  [663484] = "{id=663484,Voice='Npc_Quest/663484',Text='这座城堡的主人就是德古拉。',Speaker=829775,}",
  [663485] = "{id=663485,Voice='Npc_Quest/663485',Text='他拥有着阴冷的心和冷酷的外表。是冷酷！',Speaker=829775,}",
  [663486] = "{id=663486,Voice='Npc_Quest/663486',Text='还有一对锋利的獠牙。',Speaker=829775,}",
  [663487] = "{id=663487,Voice='Npc_Quest/663487',Text='在吉芬尼亚的伊米尔之心碎片一直由德古拉家族守护。',Speaker=829775,}",
  [663488] = "{id=663488,Voice='Npc_Quest/663488',Text='德古拉家族为了守护伊米尔之心碎片曾经发过毒誓……',Speaker=829775,}",
  [663489] = "{id=663489,Voice='Npc_Quest/663489',Text='德古拉家族世代守护伊米尔之心碎片，永不撼动。',Speaker=829775,}",
  [663490] = "{id=663490,Voice='Npc_Quest/663490',Text='关于德古拉的信息，只有这一些。',Speaker=829775,}",
  [663491] = "{id=663491,Voice='Npc_Quest/663491',Text='希望你能在吉芬尼亚尽快找到他，并帮助德古拉家族保护好伊米尔之心碎片不被夺走。这便是历史应该有的样子，也是你这次时空旅行的使命。',Speaker=829775,Option='{我知道了！,0},{真会找麻烦。,0}',}",
  [663492] = "{id=663492,Voice='Npc_Quest/663492',Text='好了，接下去你就自己想办法进入吉芬尼亚吧！',Speaker=829775,}",
  [663493] = "{id=663493,Voice='Npc_Quest/663493',Text='合适的时候我会再次出现。再见了！',Speaker=829775,}",
  [663494] = "{id=663494,Voice='Npc_Quest/663494',Text='走走走，这里不允许进入！',Speaker=829793,}",
  [663495] = "{id=663495,Voice='Npc_Quest/663495',Text='里面就是完美的世界，为什么不让我们进去！',Speaker=829794,}",
  [663496] = "{id=663496,Voice='Npc_Quest/663496',Text='没有为什么！上头的命令就是我应该服从的使命，走开！',Speaker=829793,}",
  [663497] = "{id=663497,Voice='Npc_Quest/663497',Text='我们走了很久很久才来到这里，让我们进去吧，求求你们了……',Speaker=829795,}",
  [663498] = "{id=663498,Voice='Npc_Quest/663498',Text='走开！你们已经严重妨碍我的工作了！要不是你们……我才不会来这里！',Speaker=829793,}",
  [663499] = "{id=663499,Voice='Npc_Quest/663499',Text='很抱歉给你们添麻烦了，我们只是饱受战争之苦的流民，听说这里有一个完美，和平的地方……',Speaker=829795,}",
  [663500] = "{id=663500,Voice='Npc_Quest/663500',Text='所以我们走了很久很久才来了这里。一路上我们已经失去了很多，只为寻一处没有战争的地方。',Speaker=829795,}",
  [663501] = "{id=663501,Voice='Npc_Quest/663501',Text='别做梦了！这种地方根本就不会属于你们这些人！',Speaker=829793,}",
  [663502] = "{id=663502,Voice='Npc_Quest/663502',Text='我就知道你们拦着我们不让我们进去，是因为好地方都被王室所霸占！',Speaker=829794,}",
  [663503] = "{id=663503,Voice='Npc_Quest/663503',Text='不是你们想的那样！总之我也无法解释……',Speaker=829793,}",
  [663504] = "{id=663504,Voice='Npc_Quest/663504',Text='这个世界根本不存在什么完美的世界！快走吧！离开这里！',Speaker=829793,}",
  [663505] = "{id=663505,Voice='Npc_Quest/663505',Text='不……我一定要进去！滚开，让我进去！',Speaker=829794,}",
  [663506] = "{id=663506,Voice='Npc_Quest/663506',Text='洛克，别……',Speaker=829795,}",
  [663507] = "{id=663507,Voice='Npc_Quest/663507',Text='你终于醒了！那里的骑士太多了，仅凭你一个人根本无法斗得过他们。',Speaker=829796,Option='你是……',}",
  [663508] = "{id=663508,Voice='Npc_Quest/663508',Text='我能找到进入吉芬尼亚的核心地带的秘密入口，因此渴望进去的人们叫我苍白使者。',Speaker=829796,}",
  [663509] = "{id=663509,Voice='Npc_Quest/663509',Text='你也看到了，那群王室的走狗正在阻止流民进入！！',Speaker=829796,}",
  [663510] = "{id=663510,Voice='Npc_Quest/663510',Text='这些来自克雷斯特汉姆的流民们，在他们的故土覆灭后流离失所。',Speaker=829796,}",
  [663511] = "{id=663511,Voice='Npc_Quest/663511',Text='他们来到这里，只是想寻求一个远离战争的地方……他们并没有做错什么！',Speaker=829796,Option='为什么是这里？',}",
  [663512] = "{id=663512,Voice='Npc_Quest/663512',Text='吉芬尼亚被女神所祝福，因此这里远离战争，人们称这里为吉芬尼亚·净土。',Speaker=829796,}",
  [663513] = "{id=663513,Voice='Npc_Quest/663513',Text='但是那些骑士就是王室所派来的人，王室的人只想独享这里……',Speaker=829796,}",
  [663514] = "{id=663514,Voice='Npc_Quest/663514',Text='我看你的身手就很不错…你愿意帮助我和那些可怜的流民，进入吉芬尼亚·净土吗？',Speaker=829796,Option='当然',}",
  [663515] = "{id=663515,Voice='Npc_Quest/663515',Text='谢谢！',Speaker=829795,}",
  [663516] = "{id=663516,Voice='Npc_Quest/663516',Text='我们终于可以摆脱流浪……摆脱战争……摆脱死亡……',Speaker=829794,}",
  [663517] = "{id=663517,Voice='Npc_Quest/663517',Text='皇室为了达成自己的阴谋，安排了骑士不间断巡逻，前往吉芬尼亚的秘密入口的路也不例外。',Speaker=829796,}",
  [663518] = "{id=663518,Voice='Npc_Quest/663518',Text='你务必要听从我的指令，小心前行。',Speaker=829796,}",
  [663519] = "{id=663519,Voice='Npc_Quest/663519',Text='去了那里你们就可以看到一个全新的世界。',Speaker=829796,}",
  [663520] = "{id=663520,Voice='Npc_Quest/663520',Text='那儿没有战争，资源也十分富足，就连河水中也泛着银色的光。',Speaker=829796,}",
  [663521] = "{id=663521,Voice='Npc_Quest/663521',Text='太好了，那是梦想中的家。',Speaker=829795,}",
  [663522] = "{id=663522,Voice='Npc_Quest/663522',Text='我喜欢钓鱼！那里的河水中一定有大鱼！',Speaker=829794,}",
  [663523] = "{id=663523,Voice='Npc_Quest/663523',Text='呵呵，鱼总是会上钩的……',Speaker=829796,}",
  [663524] = "{id=663524,Voice='Npc_Quest/663524',Text='快走！增援很快就会抵达！',Speaker=829796,}",
  [663525] = "{id=663525,Voice='Npc_Quest/663525',Text='我们已经到了入口，不过还要请和我一起使用咒语破解迷障。',Speaker=829796,}",
  [663526] = "{id=663526,Voice='Npc_Quest/663526',Text='天空中的繁星，吾以女神之名召唤你，照亮纷扰弥尘之路。',Speaker=829796,}",
  [663527] = "{id=663527,Text='能感觉到，入口那头连接着一个空间。',}",
  [663528] = "{id=663528,Voice='Npc_Quest/663528',Text='你快带着所有人进去吧，我会引开那些追来的骑士！！快走吧！',Speaker=829796,}",
  [663529] = "{id=663529,Voice='Npc_Quest/663529',Text='再见。记住，别告诉任何人见过我！',Speaker=829796,}",
  [663534] = "{id=663534,Voice='Npc_Quest/663534',Text='你们是谁？',Speaker=829797,Option='我……',}",
  [663535] = "{id=663535,Voice='Npc_Quest/663535',Text='为什么来到这里！！？',Speaker=829797,Option='我……',}",
  [663536] = "{id=663536,Voice='Npc_Quest/663536',Text='你们的身上！？有吸血鬼族的味道！',Speaker=829797,Option='什么？',}",
  [663537] = "{id=663537,Voice='Npc_Quest/663537',Text='别开玩笑了，我们身上怎么可能有吸血鬼族的味道……',Speaker=829794,}",
  [663538] = "{id=663538,Voice='Npc_Quest/663538',Text='再说了，我们早就打听过了，吉芬尼亚早就没有吸血鬼了！',Speaker=829794,}",
  [663539] = "{id=663539,Voice='Npc_Quest/663539',Text='“吉芬尼亚早就没有吸血鬼了”，真是如此吗？',Speaker=829797,}",
  [663540] = "{id=663540,Voice='Npc_Quest/663540',Text='吉芬尼亚的银牙猎手从未放弃过寻找吸血鬼一族仍然存在的痕迹……',Speaker=829797,}",
  [663541] = "{id=663541,Voice='Npc_Quest/663541',Text='银牙猎手？这是一个没事找事的团体吗？',Speaker=829794,}",
  [663542] = "{id=663542,Voice='Npc_Quest/663542',Text='闭嘴！在过去，没有银牙猎手中的那些猎人们，这片土地早就化为吸血鬼族的乐土……',Speaker=829797,}",
  [663543] = "{id=663543,Voice='Npc_Quest/663543',Text='即使吸血鬼族看似远离了我们很久……但我能迅速辨别出它们的气味，而你们身上有着浓浓的吸血鬼族的气味……',Speaker=829797,}",
  [663544] = "{id=663544,Voice='Npc_Quest/663544',Text='疯子！醒醒吧！这里是吉芬尼亚……没有吸血鬼。',Speaker=829794,}",
  [663545] = "{id=663545,Voice='Npc_Quest/663545',Text='不…我的判断不会错，你们之中就有吸血鬼或者见过吸血鬼！',Speaker=829797,}",
  [663548] = "{id=663548,Voice='Npc_Quest/663548',Text='我看你才是这里最奇怪的家伙。好端端的非要说我们身上有吸血鬼族的味道…',Speaker=829794,}",
  [663549] = "{id=663549,Voice='Npc_Quest/663549',Text='嗯嗯……好了，洛克不要再说了，毕竟是我们贸然闯入。',Speaker=829795,}",
  [663550] = "{id=663550,Voice='Npc_Quest/663550',Text='你们从哪里来？',Speaker=829797,}",
  [663551] = "{id=663551,Voice='Npc_Quest/663551',Text='克雷斯特汉姆覆灭后，我们便一直在寻找栖身之地，最终找到了这里。',Speaker=829795,}",
  [663552] = "{id=663552,Voice='Npc_Quest/663552',Text='这里就是你们所有人吗？你们来之前还见过什么人？',Speaker=829797,}",
  [663553] = "{id=663553,Voice='Npc_Quest/663553',Text='没……除了冒险者，我们没有见过任何人。是吧，冒险者？',Speaker=829795,Option='额……',}",
  [663554] = "{id=663554,Voice='Npc_Quest/663554',Text='……你们不愿意告诉我真话。不过刚才的气味已经证明了银牙猎手的猜测——吸血鬼族一直都在。',Speaker=829797,}",
  [663555] = "{id=663555,Voice='Npc_Quest/663555',Text='你们很希望吸血鬼族再次出现吗？然后继续战争……无休止的战争……',Speaker=829795,}",
  [663556] = "{id=663556,Voice='Npc_Quest/663556',Text='当然不……我和你们一样在等待真正没有战争的那一天。',Speaker=829797,Option='真正……',}",
  [663557] = "{id=663557,Voice='Npc_Quest/663557',Text='充满战争的世界，却有一块没有战争的净土……这件事本来就看起来不真实……',Speaker=829797,}",
  [663558] = "{id=663558,Voice='Npc_Quest/663558',Text='这里并不是你们想象的那样，也不是你们该来的地方。',Speaker=829797,}",
  [663559] = "{id=663559,Voice='Npc_Quest/663559',Text='悲观的少年，不管你说什么，我洛克来了这里就不会走了！这里就是完美的世界！',Speaker=829794,}",
  [663560] = "{id=663560,Voice='Npc_Quest/663560',Text='既然已经来了，我可以带你们找一个栖身的地方。',Speaker=829797,Option='{太好了,0},{正有此意,0}',}",
  [663569] = "{id=663569,Voice='Npc_Quest/663569',Text='冒险者，你和他们一样感觉到那种疲惫了吗？',Speaker=829799,Option='{是的,0},{有一点,0}',}",
  [663570] = "{id=663570,Voice='Npc_Quest/663570',Text='不知道从什么时候开始，这里的人们都开始困倦，也包括我。',Speaker=829799,}",
  [663571] = "{id=663571,Voice='Npc_Quest/663571',Text='而银牙猎手的成员感受到的困顿更为强烈，但我们一直没有找到原因。',Speaker=829799,}",
  [663572] = "{id=663572,Voice='Npc_Quest/663572',Text='人们就在这样的困顿中逐渐失去了警觉性和信仰，他们认可了这样的“完美世界”。',Speaker=829799,}",
  [663573] = "{id=663573,Voice='Npc_Quest/663573',Text='这样的世界真的存在吗？',Speaker=829799,Option='{也许,0},{我不知道,0}',}",
  [663574] = "{id=663574,Voice='Npc_Quest/663574',Text='呵呵，答案并不重要，真相才是我要寻求的结果。',Speaker=829799,}",
  [663575] = "{id=663575,Voice='Npc_Quest/663575',Text='我看得出，你和他们并不一样，你为什么来这里？',Speaker=829799,Option='我来找德古拉',}",
  [663576] = "{id=663576,Voice='Npc_Quest/663576',Text='德古拉！他就是吸血鬼族的首领！',Speaker=829799,Option='你认识他？',}",
  [663577] = "{id=663577,Voice='Npc_Quest/663577',Text='有趣…我也在找他…可是大家都说这个世界早已经没有吸血鬼了……不是吗？',Speaker=829799,Option='{额,0},{是,0}',}",
  [663578] = "{id=663578,Voice='Npc_Quest/663578',Text='你为什么来找他？难道你也相信这个世界上仍然有吸血鬼。',Speaker=829799,Option='{嗯……,0},{好问题,0}',}",
  [663579] = "{id=663579,Voice='Npc_Quest/663579',Text='我们的目标一样，虽然不知道你找德古拉的目的是什么，但……',Speaker=829799,}",
  [663580] = "{id=663580,Voice='Npc_Quest/663580',Text='啊……啊……有鬼啊……',Speaker=829804,}",
  [663581] = "{id=663581,Voice='Npc_Quest/663581',Text='疯子，疯子……走开啦！',Speaker=829804,}",
  [663582] = "{id=663582,Voice='Npc_Quest/663582',Text='那边好像发生了骚乱？走，和我一起去看看！',Speaker=829799,}",
  [663585] = "{id=663585,Voice='Npc_Quest/663585',Text='他们看起来眼神空洞，面露恐惧的样子……',Speaker=829799,Option='像是做了噩梦',}",
  [663586] = "{id=663586,Voice='Npc_Quest/663586',Text='……这种情况每隔一段时间就会发生。不久前也发生过几回。只是发生的间隔越来越小了。',Speaker=829799,Option='可是什么',}",
  [663587] = "{id=663587,Voice='Npc_Quest/663587',Text='鲁尔……告诉我，你看到了什么？',Speaker=829799,}",
  [663588] = "{id=663588,Voice='Npc_Quest/663588',Text='网……吸血鬼……还有吃人……还有血……',Speaker=829805,}",
  [663589] = "{id=663589,Voice='Npc_Quest/663589',Text='还有什么？',Speaker=829799,}",
  [663590] = "{id=663590,Voice='Npc_Quest/663590',Text='网……吸血鬼……还有吃人……还有血……',Speaker=829805,Option='……',}",
  [663591] = "{id=663591,Voice='Npc_Quest/663591',Text='看来问不出更多的信息了……只有治愈了他们才能问到有用的信息……',Speaker=829799,Option='如何治疗',}",
  [663592] = "{id=663592,Voice='Npc_Quest/663592',Text='只有光才能让他们平静下来。可是我并没有资格获得光。',Speaker=829799,}",
  [663593] = "{id=663593,Voice='Npc_Quest/663593',Text='看看这个世界吧，这里一直都没有光，“和平”到来的同时，吉芬尼亚进入了极夜。',Speaker=829799,}",
  [663594] = "{id=663594,Voice='Npc_Quest/663594',Text='光成为这个世界极为罕见的宝贝，也是权力的象征。',Speaker=829799,Option='光？',}",
  [663595] = "{id=663595,Voice='Npc_Quest/663595',Text='是维吉尔大人！',Speaker=829806,}",
  [663596] = "{id=663596,Voice='Npc_Quest/663596',Text='维吉尔大人来了，他们有救了！！',Speaker=829807,}",
  [663619] = "{id=663619,Voice='Npc_Quest/663619',Text='你看极夜中的星星多美啊。',Speaker=829799,}",
  [663620] = "{id=663620,Voice='Npc_Quest/663620',Text='这是我们能看到为数不多的光，所以人们渴望流星雨，这样陨落的光才能降临在这里。',Speaker=829799,}",
  [663621] = "{id=663621,Voice='Npc_Quest/663621',Text='有了光，人们才会感到安宁。',Speaker=829799,}",
  [663622] = "{id=663622,Voice='Npc_Quest/663622',Text='像魔法团长维吉尔所说，保护民众的方法有很多，我应该和魔法团一样寻找光，让这里变得更完美。',Speaker=829799,}",
  [663623] = "{id=663623,Voice='Npc_Quest/663623',Text='但我却始终觉得正是因为完美而不真实。你一定也觉得我很奇怪吧？',Speaker=829799,Option='{有一点,0},{并不会,0}',}",
  [663624] = "{id=663624,Voice='Npc_Quest/663624',Text='可是奇怪的不止我一个，银牙猎手剩下的几位老猎人和我都坚信着战争从未远离我们。我想要证明银牙猎手的猜测！',Speaker=829799,}",
  [663625] = "{id=663625,Voice='Npc_Quest/663625',Text='你愿意帮我寻找吸血鬼存在的证据吗？当然，这不仅仅是帮助我，你也需要找到德古拉不是吗？',Speaker=829799,Option='{当然愿意,0},{只能如此,0}',}",
  [663627] = "{id=663627,Voice='Npc_Quest/663627',Text='那么跟我来吧，我有办法找到吸血鬼族。',Speaker=829799,}",
  [663637] = "{id=663637,Voice='Npc_Quest/663637',Text='我仿佛已经看到了肮脏的吸血鬼在啃噬，鲜血在滴落…鲜血在滴落……',Speaker=829799,}",
  [663638] = "{id=663638,Voice='Npc_Quest/663638',Text='冒险者，我需要在这里维持法术，麻烦你去查看一下血线尽头的情况。',Speaker=829799,Option='交给我吧',}",
  [663653] = "{id=663653,Voice='Npc_Quest/663653',Text='求求你们……放过我……我错了。我再也不敢了。我会和以前一样躲起来，不再骚扰人类……',Speaker=829819,}",
  [663654] = "{id=663654,Voice='Npc_Quest/663654',Text='和以前一样？',Speaker=829799,}",
  [663655] = "{id=663655,Voice='Npc_Quest/663655',Text='是的，在进入极夜后，大人要求所有血族不再出现在人类的世界中，违者处决。',Speaker=829819,}",
  [663656] = "{id=663656,Voice='Npc_Quest/663656',Text='我违背大人的命令……我错了……请放过我吧……',Speaker=829819,}",
  [663657] = "{id=663657,Voice='Npc_Quest/663657',Text='告诉我你们躲在哪里？德古拉在哪儿！！',Speaker=829799,}",
  [663658] = "{id=663658,Voice='Npc_Quest/663658',Text='我不知道……在极夜之后我因为太弱小而被抛弃…所以我才想要偷偷的提升自己后，重新回到族群中！',Speaker=829819,}",
  [663659] = "{id=663659,Voice='Npc_Quest/663659',Text='违背大人的命令，会遭到什么样的惩罚呢？',Speaker=829799,}",
  [663660] = "{id=663660,Voice='Npc_Quest/663660',Text='割头刑，然后灰飞烟灭……',Speaker=829819,}",
  [663661] = "{id=663661,Voice='Npc_Quest/663661',Text='再见了，肮脏的吸血鬼族，就让我代替你的大人惩罚你吧！',Speaker=829799,}",
  [663662] = "{id=663662,Voice='Npc_Quest/663662',Text='放过我吧！！求求你了！！！',Speaker=829819,}",
  [663663] = "{id=663663,Voice='Npc_Quest/663663',Text='你的生命本该化为尘土，而不是以这样的方式存活。我所做的只是让你回到原来的终点，去死吧！',Speaker=829799,}",
  [663664] = "{id=663664,Voice='Npc_Quest/663664',Text='结束了……冒险者，我们将证据带回给维吉尔团长吧。',Speaker=829799,}",
  [663665] = "{id=663665,Voice='Npc_Quest/663665',Text='冒险者，谢谢你将沃尔夫带回。沃尔夫，你不能总是生活在过去，要向前看。',Speaker=829808,}",
  [663666] = "{id=663666,Voice='Npc_Quest/663666',Text='可吸血鬼族的确从未离开过我们的身边！我们所感受到的只是一个假象！',Speaker=829799,}",
  [663667] = "{id=663667,Voice='Npc_Quest/663667',Text='沃尔夫你发现了什么？',Speaker=829808,}",
  [663668] = "{id=663668,Voice='Npc_Quest/663668',Text='看！这个十字架，它吸收到了吸血鬼族的力量，这就是吸血鬼族存在的证据！',Speaker=829799,}",
  [663669] = "{id=663669,Voice='Npc_Quest/663669',Text='……沃尔夫，这个十字架上，什么都没有。',Speaker=829808,}",
  [663670] = "{id=663670,Voice='Npc_Quest/663670',Text='怎么会这样！……刚才明明……冒险者可以作为我的证人，我们一起猎杀了一个吸血鬼！',Speaker=829799,}",
  [663671] = "{id=663671,Voice='Npc_Quest/663671',Text='沃尔夫！这出闹剧你到底要演到什么时候！',Speaker=829808,}",
  [663672] = "{id=663672,Voice='Npc_Quest/663672',Text='在吸血鬼所在的地方，死者的脖子上有两个牙印，这也可以证明吸血鬼族的存在。找到他就足以证明！',Speaker=829799,}",
  [663673] = "{id=663673,Voice='Npc_Quest/663673',Text='我再给你最后一次机会……瑟曦！',Speaker=829808,}",
  [663674] = "{id=663674,Voice='Npc_Quest/663674',Text='团长！我在！',Speaker=829822,}",
  [663675] = "{id=663675,Voice='Npc_Quest/663675',Text='瑟曦，去沃尔夫所说的地方，检查死者的情况。记住仔细检查！',Speaker=829808,}",
  [663676] = "{id=663676,Voice='Npc_Quest/663676',Text='好的！团长！',Speaker=829822,}",
  [663677] = "{id=663677,Text='众人等待瑟曦的检查结果。',}",
  [663678] = "{id=663678,Voice='Npc_Quest/663678',Text='报告团长！死者的脖子处只有动物啃噬的痕迹！',Speaker=829822,}",
  [663679] = "{id=663679,Voice='Npc_Quest/663679',Text='这怎么可能？！我和冒险者都亲眼所见！！！！',Speaker=829799,Option='我可以作证',}",
  [663680] = "{id=663680,Voice='Npc_Quest/663680',Text='可真相就是，死者被一些动物所攻击而致死……',Speaker=829822,}",
  [663681] = "{id=663681,Voice='Npc_Quest/663681',Text='不，有人在阻止我们找到证据。',Speaker=829799,}",
  [663682] = "{id=663682,Voice='Npc_Quest/663682',Text='够了，沃尔夫，这场闹剧到此结束吧！',Speaker=829808,}",
  [663683] = "{id=663683,Voice='Npc_Quest/663683',Text='不！魔法团团长！有人正在阻止我们找到证据！我们一直在被人监视着，这是一个巨大的阴谋。',Speaker=829799,}",
  [663684] = "{id=663684,Voice='Npc_Quest/663684',Text='阴谋？不能以真面目示人的你，又是带着怎样的阴谋，试图破坏现在的平衡呢？',Speaker=829808,}",
  [663685] = "{id=663685,Voice='Npc_Quest/663685',Text='寻找吸血鬼族的事情还是交给猎人吧。',Speaker=829832,}",
  [663686] = "{id=663686,Voice='Npc_Quest/663686',Text='抱歉，维吉尔，沃尔夫虽然不是银牙猎手的成员，但他的母亲是一位优秀的猎手，也许耳濡目染让他总是想着要抓什么吸血鬼。',Speaker=829832,}",
  [663687] = "{id=663687,Voice='Npc_Quest/663687',Text='咳咳咳……不过银牙猎手死的死，老的老，这个世界的银牙猎手就快像吸血鬼族一样消失了……也不知道我这把老骨头能撑到什么时候。',Speaker=829832,}",
  [663688] = "{id=663688,Voice='Npc_Quest/663688',Text='好好养护身体吧，或许使用一些光，你会变得好一些。',Speaker=829808,}",
  [663689] = "{id=663689,Voice='Npc_Quest/663689',Text='不必了，所有的猎人都将在极夜中死去，直到无人想起，走了，愿你们在极夜中前路无阻。',Speaker=829832,}",
  [663737] = "{id=663737,Voice='Npc_Quest/663737',Text='咳咳……咳……我想过猎人团全部战死在战场上，却没想到猎人的尽头在这极夜中……',Speaker=829832,Option='罗恩怎么了？',}",
  [663738] = "{id=663738,Voice='Npc_Quest/663738',Text='外祖父又昏过去了…最近他的身体越来越弱，因为迅速衰老的原因，也时常陷入昏迷。',Speaker=829799,}",
  [663739] = "{id=663739,Voice='Npc_Quest/663739',Text='去采摘一些[c][ffff00]昔时白夜草[-][/c]！，自从极夜后，祖父自感身体不适，一直在靠它勉强维持身体的状况。',Speaker=829799,}",
  [663740] = "{id=663740,Voice='Npc_Quest/663740',Text='只是昔时白夜草因为长久失去光的照耀，越发难以生长，就在营地不远处，也许还有一些。',Speaker=829799,}",
  [663742] = "{id=663742,Voice='Npc_Quest/663741',Text='咳咳……我刚才做了一个很沉的梦，梦中我看到了一张巨大的网……那里是生命的尽头。',Speaker=829832,Option='网？',}",
  [663743] = "{id=663743,Voice='Npc_Quest/663742',Text='对，网……我在那里看到了我的老伙伴们，那些猎人们正在那等着我……一张巨大的网……',Speaker=829832,}",
  [663744] = "{id=663744,Voice='Npc_Quest/663743',Text='我的死亡意味着吉芬尼亚的银牙猎手时代彻底远走，我们所走的痕迹会被时间掩埋……',Speaker=829832,}",
  [663745] = "{id=663745,Voice='Npc_Quest/663744',Text='所以沃尔夫，你要不断往前走，不断……不断，直到找到德古拉。',Speaker=829832,}",
  [663746] = "{id=663746,Voice='Npc_Quest/663745',Text='不要忘记你的仇恨，为你的母亲赫莲娜复仇……',Speaker=829832,}",
  [663747] = "{id=663747,Voice='Npc_Quest/663746',Text='复仇那日请把德古拉之血撒向空中告慰所有逝去的猎人之魂。',Speaker=829832,}",
  [663748] = "{id=663748,Voice='Npc_Quest/663747',Text='沃尔夫你以生命起誓，你将手刃德古拉！为你的母亲报仇！咳咳……',Speaker=829832,}",
  [663749] = "{id=663749,Voice='Npc_Quest/663748',Text='我以生命起誓，我将手刃德古拉，为母亲，为所有银牙猎手复仇！',Speaker=829799,}",
  [663750] = "{id=663750,Voice='Npc_Quest/663749',Text='好……好……',Speaker=829832,}",
  [663753] = "{id=663753,Voice='Npc_Quest/663753',Text='安息吧……',Speaker=829799,Option='安息，罗恩',}",
  [663754] = "{id=663754,Voice='Npc_Quest/663754',Text='你是永远的银牙猎手。',Speaker=829799,}",
  [663755] = "{id=663755,Voice='Npc_Quest/663755',Text='属于银牙猎手的辉煌不会被吸血鬼族磨灭！',Speaker=829799,}",
  [663806] = "{id=663806,Voice='Npc_Quest/663806',Text='就是他！就是他带着这群外来者，给吉芬尼亚带来了厄运！',Speaker=829846,}",
  [663807] = "{id=663807,Voice='Npc_Quest/663807',Text='鲜血…好多人都受伤了…吸血鬼…吸血鬼又出现了！',Speaker=829846,}",
  [663808] = "{id=663808,Voice='Npc_Quest/663808',Text='它们一直都在，而不是又一次出现。',Speaker=829799,}",
  [663809] = "{id=663809,Voice='Npc_Quest/663809',Text='怎么会这样…可怕的吸血鬼族…沃尔夫，告诉我们，这不是真的。',Speaker=829846,}",
  [663810] = "{id=663810,Voice='Npc_Quest/663810',Text='这群外来者一定和吸血鬼是一伙的！',Speaker=829846,}",
  [663811] = "{id=663811,Voice='Npc_Quest/663811',Text='不…他们和你们一样，相信了吉芬尼亚是没有吸血鬼族的完美世界，他们也是受害者！',Speaker=829799,}",
  [663812] = "{id=663812,Voice='Npc_Quest/663812',Text='你们听好了！我们，被吸血鬼困在了梦境中！他们正在利用一种名为捕梦网的秘术吸取我们的生命能量！',Speaker=829799,}",
  [663813] = "{id=663813,Voice='Npc_Quest/663813',Text='这是最近许多人加速死亡的真正原因！',Speaker=829799,}",
  [663815] = "{id=663815,Voice='Npc_Quest/663815',Text='接受现实吧，我们忘记战争太久了。以至于敌人再次出现只剩下指责、恐惧和互相伤害。',Speaker=829799,}",
  [663816] = "{id=663816,Voice='Npc_Quest/663816',Text='我需要你们！所有人振作起来吧！我需要你们的加入，吉芬尼亚需要猎手！',Speaker=829799,}",
  [663817] = "{id=663817,Voice='Npc_Quest/663817',Text='银牙猎手的精神永不沉没…',Speaker=829799,}",
  [663818] = "{id=663818,Voice='Npc_Quest/663818',Text='银牙猎手的精神永不沉没！！没想到本想躺平的我，却成为了猎人！银牙猎手的精神永不沉没！！',Speaker=829794,}",
  [663844] = "{id=663844,Voice='Npc_Quest/663844',Text='有动静了……',Speaker=829799,}",
  [663845] = "{id=663845,Voice='Npc_Quest/663845',Text='快看，又进来一批新的民众。',Speaker=829799,}",
  [663846] = "{id=663846,Voice='Npc_Quest/663846',Text='那个带着面具的人……',Speaker=829799,Option='{就是他！,0},{苍白使者！,0}',}",
  [663847] = "{id=663847,Voice='Npc_Quest/663847',Text='哼，总算现身了！',Speaker=829799,}",
  [663851] = "{id=663851,Voice='Npc_Quest/663851',Text='戴上面具也无法遮掩你身上吸血鬼族的气味。',Speaker=829799,}",
  [663852] = "{id=663852,Voice='Npc_Quest/663852',Text='那又怎样？你带着面具又是为了遮掩什么呢？难道你也来自血族吗！？',Speaker=829796,}",
  [663853] = "{id=663853,Voice='Npc_Quest/663853',Text='闭嘴！告诉我德古拉在哪里！',Speaker=829799,}",
  [663854] = "{id=663854,Voice='Npc_Quest/663854',Text='我什么都不知道…！我只是负责将更多人类引渡入梦…让捕梦网吸收更多的人类能量。',Speaker=829796,}",
  [663855] = "{id=663855,Voice='Npc_Quest/663855',Text='引渡进入梦境……那么这里的出口在哪儿？',Speaker=829799,}",
  [663856] = "{id=663856,Voice='Npc_Quest/663856',Text='我也不知道……我只知道梦境的入口，只要念出咒语，我便可以带着人类进入这里……',Speaker=829796,}",
  [663857] = "{id=663857,Voice='Npc_Quest/663857',Text='这个梦境究竟是谁建造的？你们吸血鬼族，哪怕是德古拉都无法拥有这样的力量吧？',Speaker=829799,}",
  [663858] = "{id=663858,Voice='Npc_Quest/663858',Text='桀桀桀……是那位大人！是那位大人以德古拉之血为钥，创造了这个完美的世界！',Speaker=829796,}",
  [663859] = "{id=663859,Voice='Npc_Quest/663859',Text='你们人类想要的净土不就是这里吗？',Speaker=829796,}",
  [663860] = "{id=663860,Voice='Npc_Quest/663860',Text='一个真正没有战争的世界，本来就是一个梦！',Speaker=829796,}",
  [663861] = "{id=663861,Voice='Npc_Quest/663861',Text='但这个梦会害死所有人！',Speaker=829799,}",
  [663862] = "{id=663862,Voice='Npc_Quest/663862',Text='桀桀桀……想要活下去……那就加入我们，帮助德古拉大人汲取更多的能量吧！',Speaker=829796,}",
  [663863] = "{id=663863,Voice='Npc_Quest/663863',Text='让愚昧的人进入这里维持梦境的平衡，为你们带来永恒的和平…多好啊~',Speaker=829796,}",
  [663864] = "{id=663864,Voice='Npc_Quest/663864',Text='当然不听话的人则会和那些猎人一样——加速死亡的进程！',Speaker=829796,}",
  [663865] = "{id=663865,Voice='Npc_Quest/663865',Text='你！',Speaker=829799,}",
  [663866] = "{id=663866,Voice='Npc_Quest/663866',Text='桀桀桀，认清眼前的现实吧，如果现在的平衡被打破，人类和血族的战争将因您而再次打响！',Speaker=829796,}",
  [663867] = "{id=663867,Voice='Npc_Quest/663867',Text='好好想想，接受这份礼物吧……',Speaker=829796,}",
  [663868] = "{id=663868,Voice='Npc_Quest/663868',Text='去死吧！留着你的鬼话下地狱吧！',Speaker=829799,}",
  [663879] = "{id=663879,Voice='Npc_Quest/663879',Text='沃尔夫……你醒醒……',Speaker=829842,}",
  [663880] = "{id=663880,Voice='Npc_Quest/663880',Text='（呓语）梦境中的人无法苏醒……杀了它……',Speaker=829799,}",
  [663881] = "{id=663881,Voice='Npc_Quest/663881',Text='沃尔夫你已经回到营地了，你还好吗？',Speaker=829842,}",
  [663882] = "{id=663882,Voice='Npc_Quest/663882',Text='（呓语）我真的能打败吸血鬼族吗？就凭我吗…',Speaker=829799,}",
  [663883] = "{id=663883,Voice='Npc_Quest/663883',Text='看来他受了很严重的伤，说着一些胡话。我要带他去找魔法团团长，只有他那有最好的药。',Speaker=829842,}",
  [663884] = "{id=663884,Text='人类和血族之战再次挑起。',}",
  [663885] = "{id=663885,Text='战争并未远离吉芬尼亚的人们，',}",
  [663886] = "{id=663886,Text='现实只是被梦境笼罩。',}",
  [663887] = "{id=663887,Voice='Npc_Quest/663887',Text='沃尔夫！你需要变得更强。你需要灭世之力。',Speaker=829852,}",
  [663888] = "{id=663888,Voice='Npc_Quest/663888',Text='收下灭世之力，成为我的使徒。',Speaker=829852,}",
  [663889] = "{id=663889,Voice='Npc_Quest/663889',Text='为我寻找身体容器，换取灭世之力！',Speaker=829852,}",
  [663890] = "{id=663890,Voice='Npc_Quest/663890',Text='灭世之力将主宰一切……',Speaker=829799,}",
  [663906] = "{id=663906,Text='杀戮并非目的，和平才是。',Speaker=829852,}",
  [663910] = "{id=663910,Voice='Npc_Quest/663910',Text='沃尔夫万岁！',Speaker=829827,}",
  [663913] = "{id=663913,Text='杀戮并非我所愿……',Speaker=829852,}",
  [663915] = "{id=663915,Voice='Npc_Quest/663915',Text='沃尔夫！沃尔夫！',Speaker=829842,}",
  [663916] = "{id=663916,Voice='Npc_Quest/663916',Text='……波里娜……',Speaker=829799,}",
  [663917] = "{id=663917,Voice='Npc_Quest/663917',Text='沃尔夫，你没事吧？吓死我了！',Speaker=829842,}",
  [663918] = "{id=663918,Voice='Npc_Quest/663918',Text='民众已经被疏散了，你需要好好休息一下。',Speaker=829842,}",
  [663919] = "{id=663919,Voice='Npc_Quest/663919',Text='……不知道为什么，我最近总是听到我母亲的声音。',Speaker=829799,}",
  [663920] = "{id=663920,Voice='Npc_Quest/663920',Text='她对我说“杀戮并非目的，和平才是。”',Speaker=829799,}",
  [663921] = "{id=663921,Voice='Npc_Quest/663921',Text='她虽然继承了罗恩的猎人意志却和罗恩完全不同，她并不认为杀戮才是唯一解决问题的方法。',Speaker=829799,}",
  [663922] = "{id=663922,Voice='Npc_Quest/663922',Text='她总是对我说，不要被鲜血蒙蔽了双眼…可是这样的她，却还是死在了吸血鬼族之手！',Speaker=829799,Option='为什么会想起她',}",
  [663923] = "{id=663923,Voice='Npc_Quest/663923',Text='也许只是她在提醒我不要忘记猎人的仇恨。一定是这样的！我一定——要替她报仇！',Speaker=829799,Option='接下来要怎么做',}",
  [663924] = "{id=663924,Voice='Npc_Quest/663924',Text='看看这个…刚才我已经收集到足够多的吸血鬼族之血，被鲜血浸染的眼睛可以带领我们找到德古拉！',Speaker=829799,Option='它是什么',}",
  [663925] = "{id=663925,Voice='Npc_Quest/663925',Text='是一个可以帮助我快速复仇的好东西！跟着它走吧！',Speaker=829799,}",
  [663928] = "{id=663928,Voice='Npc_Quest/663928',Text='冒险者，小心一些……这里有些古怪',Speaker=829799,}",
  [663929] = "{id=663929,Voice='Npc_Quest/663929',Text='你们永远无法找到梦境的出口。',Speaker=829852,}",
  [663930] = "{id=663930,Voice='Npc_Quest/663930',Text='谁都不要来打扰我和我的妻子！',Speaker=829852,}",
  [663937] = "{id=663937,Voice='Npc_Quest/663937',Text='我说过，我需要更多的力量，否则……',Speaker=829799,}",
  [663938] = "{id=663938,Voice='Npc_Quest/663938',Text='你在威胁我？',Speaker=829853,}",
  [663939] = "{id=663939,Voice='Npc_Quest/663939',Text='这并不是威胁，而是谈判，没有足够的力量我根本无法进入古堡。',Speaker=829799,}",
  [663940] = "{id=663940,Voice='Npc_Quest/663940',Text='只有[c][ffff00]那东西[-][/c]才可以承载你的灵魂不是吗？',Speaker=829799,}",
  [663941] = "{id=663941,Voice='Npc_Quest/663941',Text='这是最后一次！再敢用这样的语气和我说话，我会毁了你和整个吉芬尼亚，人类和吸血鬼族最终都化为一粒尘埃。',Speaker=829853,}",
  [663942] = "{id=663942,Voice='Npc_Quest/663942',Text='收下我赐给你的力量吧！杀戮会让你变得更强！',Speaker=829853,}",
  [663943] = "{id=663943,Voice='Npc_Quest/663943',Text='你去了很久。没碰到什么麻烦吧？',Speaker=829799,Option='{一切顺利,0},{你呢？,0}',}",
  [663944] = "{id=663944,Voice='Npc_Quest/663944',Text='我？我能有什么麻烦……只是有些疲惫……',Speaker=829799,Option='……',}",
  [663945] = "{id=663945,Voice='Npc_Quest/663945',Text='我们稍作休息，其他的事情再做打算吧。',Speaker=829799,}",
  [663946] = "{id=663946,Voice='Npc_Quest/663946',Text='我找到了我的孩子。',Speaker=829852,}",
  [663947] = "{id=663947,Voice='Npc_Quest/663947',Text='但是你的孩子正在破坏你的计划，如果他妨碍了大人，我会解决他。',Speaker=829820,}",
  [663948] = "{id=663948,Voice='Npc_Quest/663948',Text='我不会让这样的事情发生。',Speaker=829852,}",
  [663949] = "{id=663949,Voice='Npc_Quest/663949',Text='染血警钟！回营地。',Speaker=829799,}",
  [663951] = "{id=663951,Voice='Npc_Quest/663951',Text='制止沃尔夫！快！',Speaker=829842,}",
  [663954] = "{id=663954,Voice='Npc_Quest/663954',Text='他是吸血鬼！',Speaker=829860,}",
  [663955] = "{id=663955,Voice='Npc_Quest/663955',Text='吸血鬼族竟一直在我们身边！',Speaker=829860,}",
  [663956] = "{id=663956,Voice='Npc_Quest/663956',Text='发生了什么？',Speaker=829808,}",
  [663957] = "{id=663957,Voice='Npc_Quest/663957',Text='原来是这样……原来这就是罗恩那老家伙想要隐瞒的事情……',Speaker=829808,}",
  [663958] = "{id=663958,Voice='Npc_Quest/663958',Text='沃尔夫是我看着长大的，他正义，勇敢，继承了所有猎人的意志。',Speaker=829808,}",
  [663959] = "{id=663959,Voice='Npc_Quest/663959',Text='他的身体中除了流着吸血鬼族的血以外，和其他人并没有什么两样。',Speaker=829808,}",
  [663960] = "{id=663960,Voice='Npc_Quest/663960',Text='真的吗？可是我有些害怕他……',Speaker=829861,}",
  [663961] = "{id=663961,Voice='Npc_Quest/663961',Text='你们认识的沃尔夫从来都是帮助你们的，不是吗？',Speaker=829808,}",
  [663962] = "{id=663962,Voice='Npc_Quest/663962',Text='是的！没错！他一直帮着我们，不仅重建了新的银牙猎手，还让流民有了安置之处。',Speaker=829794,}",
  [663963] = "{id=663963,Voice='Npc_Quest/663963',Text='是的……我们十分信任他！',Speaker=829795,}",
  [663964] = "{id=663964,Voice='Npc_Quest/663964',Text='吸血鬼的血液无法抹去沃尔夫想要保护所有人的决心，沃尔夫，你要相信自己。',Speaker=829808,}",
  [663965] = "{id=663965,Voice='Npc_Quest/663965',Text='你永远是你自己，沃尔夫，站起来。',Speaker=829842,}",
  [663966] = "{id=663966,Voice='Npc_Quest/663966',Text='是的，没错，我是人类和吸血鬼族的孩子，最优秀的猎人罗恩是我的外祖父，我亲生母亲赫莲娜也是一位优秀的猎人。',Speaker=829799,}",
  [663967] = "{id=663967,Voice='Npc_Quest/663967',Text='我被人类抚养长大，我从不认为我是吸血鬼族的孩子，因为我的母亲就是死于德古拉之手！',Speaker=829799,}",
  [663968] = "{id=663968,Voice='Npc_Quest/663968',Text='我比你们任何人都恨吸血鬼族，同样，也痛恨我身上流淌的血脉！',Speaker=829799,}",
  [663969] = "{id=663969,Voice='Npc_Quest/663969',Text='孩子，成为人类和吸血鬼族的孩子，不是你的错，只是你的命运，只要勇敢的微笑，命运也会惧怕你的獠牙。',Speaker=829808,}",
  [663970] = "{id=663970,Voice='Npc_Quest/663970',Text='是的！我是沃尔夫！我生之并不平凡，又何必在意他人目光！',Speaker=829799,}",
  [663971] = "{id=663971,Voice='Npc_Quest/663971',Text='我的使命是向吸血鬼族复仇，带所有人冲出梦境！',Speaker=829799,}",
  [663972] = "{id=663972,Voice='Npc_Quest/663972',Text='你一定有很多问题想要问我。',Speaker=829799,Option='{你身上的力量,0},{那颗眼睛,0}',}",
  [663973] = "{id=663973,Voice='Npc_Quest/663973',Text='我身体中的力量来自这只眼睛，眼睛的主人给了我能够对抗吸血鬼一族的灭世之力。',Speaker=829799,}",
  [663974] = "{id=663974,Voice='Npc_Quest/663974',Text='作为条件，他要我从德古拉那取得伊米尔之心碎片。',Speaker=829799,Option='是梦罗克',}",
  [663975] = "{id=663975,Voice='Npc_Quest/663975',Text='你知道他？',Speaker=829799,Option='{来自异世界,0},{穿梭时空的魔王,0}',}",
  [663976] = "{id=663976,Voice='Npc_Quest/663976',Text='在之前的战斗中我越发感觉自己力量的薄弱，就在这时候他找上了我。',Speaker=829799,}",
  [663977] = "{id=663977,Voice='Npc_Quest/663977',Text='这次的失控让我意识到，这力量并不属于我，我只是被灭世之力操控的傀儡！',Speaker=829799,Option='你打算怎么做',}",
  [663978] = "{id=663978,Voice='Npc_Quest/663978',Text='我！绝不能！失去自我！',Speaker=829799,}",
  [663979] = "{id=663979,Voice='Npc_Quest/663979',Text='违背契约的怪物！你将为你的行为付出代价！',Speaker=829776,}",
  [663989] = "{id=663989,Voice='Npc_Quest/663989',Text='抓紧时间，我们分头寻找线索。',Speaker=829939,}",
  [663990] = "{id=663990,Text='这是一个古老的家族，拥有着世代世袭的爵位。德古拉一世生性阴冷好战，在一次战争中全军覆没，不屈的意志让他和他的战士们成为不死之躯——血族。',Speaker=829856,}",
  [663991] = "{id=663991,Text='此后德古拉家族一直居住在吉芬尼亚，直到人类发现这里并定居。德古拉已经在古堡中住了很久很久……',Speaker=829856,}",
  [663992] = "{id=663992,Text='保留死者的心脏。',Speaker=829857,}",
  [663993] = "{id=663993,Text='献祭他人的命运，换取死者的重生。',Speaker=829857,}",
  [663994] = "{id=663994,Text='建造捕梦网，可以将大量的人类困于梦境中。',Speaker=829858,}",
  [663995] = "{id=663995,Text='梦境只能拥有德古拉家族血脉者才能建造，建造者需使用血引作为出入口的密钥，而打破梦境的唯一方法是献祭德古拉家族血脉。',Speaker=829858,}",
  [663997] = "{id=663997,Voice='Npc_Quest/663997',Text='母亲……母亲……',Speaker=829939,}",
  [663998] = "{id=663998,Voice='Npc_Quest/663998',Text='破坏大人计划的人都应该死！就由我来替德古拉解决你这个麻烦！',Speaker=829862,}",
  [663999] = "{id=663999,Voice='Npc_Quest/663999',Text='终局已定，就此进入另一个极夜吧！',Speaker=829862,}",
  [664000] = "{id=664000,Voice='Npc_Quest/664000',Text='德古拉家族的分歧并不需要外人插手。',Speaker=829791,}",
  [664001] = "{id=664001,Voice='Npc_Quest/664001',Text='哼，愚蠢，为了维持梦境，你的力量所剩无几了吧？',Speaker=829862,}",
  [664002] = "{id=664002,Voice='Npc_Quest/664002',Text='就再给你一点时间，那个东西，我势在必得。',Speaker=829862,}",
  [664003] = "{id=664003,Voice='Npc_Quest/664003',Text='离我的母亲远一点！！！',Speaker=829939,}",
  [664004] = "{id=664004,Voice='Npc_Quest/664004',Text='怎么……会这样……？',Speaker=829939,}",
  [664005] = "{id=664005,Voice='Npc_Quest/664005',Text='因为…我是你的父亲。沃尔夫，你的身上和我流淌着同样的血液！',Speaker=829791,}",
  [664006] = "{id=664006,Voice='Npc_Quest/664006',Text='我是你的父亲，沃尔夫，我深爱着你的母亲，可是赫莲娜变成了现在这样……',Speaker=829791,}",
  [664007] = "{id=664007,Voice='Npc_Quest/664007',Text='都是你害的！是你杀死了我的母亲！罗恩亲眼看到你，摘除了我的母亲……赫莲娜的心脏。',Speaker=829939,}",
  [664008] = "{id=664008,Voice='Npc_Quest/664008',Text='当年你的外祖父罗恩，反对我和赫莲娜在一起，我们发生了一场无可避免的冲突…',Speaker=829791,}",
  [664009] = "{id=664009,Voice='Npc_Quest/664009',Text='当时我和罗恩都向对方发出了致命一击，而赫莲娜为了平息这场战斗……挡在我和罗恩之间。',Speaker=829791,}",
  [664010] = "{id=664010,Voice='Npc_Quest/664010',Text='为了复活赫莲娜，我摘除了她的心脏以药水保存，并且一直在寻找复活赫莲娜的办法。',Speaker=829791,}",
  [664011] = "{id=664011,Voice='Npc_Quest/664011',Text='所以我忽视了你……你那时候还很小。你被罗恩带走。',Speaker=829791,}",
  [664012] = "{id=664012,Voice='Npc_Quest/664012',Text='不，你撒谎！',Speaker=829939,}",
  [664013] = "{id=664013,Voice='Npc_Quest/664013',Text='我一直在找你，直到传来罗恩因为痛恨我而将仇恨转嫁于你的消息——罗恩杀了你。',Speaker=829791,}",
  [664014] = "{id=664014,Voice='Npc_Quest/664014',Text='我不相信，一直在找你，但你却真的像消失了一般。',Speaker=829791,}",
  [664015] = "{id=664015,Voice='Npc_Quest/664015',Text='而就在这个时候……我在秘术中找到了复活你母亲的方法！',Speaker=829791,}",
  [664016] = "{id=664016,Voice='Npc_Quest/664016',Text='我不得不将所有重心都放在复活你母亲这件事上。',Speaker=829791,}",
  [664017] = "{id=664017,Voice='Npc_Quest/664017',Text='我开始尝试用捕梦网汲取梦中人的能量，但仅凭秘术的方法能汲取的能量太少。',Speaker=829791,}",
  [664018] = "{id=664018,Voice='Npc_Quest/664018',Text='终于在一位神祇的帮助下，我以自己的血为钥匙，让吉芬尼亚的所有人沉睡，创造了整个吉芬尼亚的梦境。',Speaker=829791,Option='{神祇？！,0},{是谁？！,0}',}",
  [664019] = "{id=664019,Voice='Npc_Quest/664019',Text='你，一个人类，没有资格知道她的名讳！',Speaker=829791,}",
  [664020] = "{id=664020,Voice='Npc_Quest/664020',Text='沃尔夫……再过不久……赫莲娜就可以彻底活过来了！再等等，再等等，我们一家人就要团聚了……',Speaker=829791,}",
  [664021] = "{id=664021,Voice='Npc_Quest/664021',Text='可是，这里的人都会死！！',Speaker=829939,}",
  [664022] = "{id=664022,Voice='Npc_Quest/664022',Text='他们的死和我有什么关系？这个世界上，不死才是一种惩罚。',Speaker=829791,}",
  [664023] = "{id=664023,Voice='Npc_Quest/664023',Text='这里本来就不是那些人该来的地方，他们的到来除了压榨了血族的生存空间，还抢夺了我们的资源。',Speaker=829791,}",
  [664024] = "{id=664024,Voice='Npc_Quest/664024',Text='甚至对血族赶尽杀绝！而现在，我不过是对他们过去的行为施加小小惩戒而已。',Speaker=829791,}",
  [664025] = "{id=664025,Voice='Npc_Quest/664025',Text='在梦境中无痛的死去，好过长久的征战，和平，不是所有人追求的吗？人类不再战斗，血族获得了居所。',Speaker=829791,}",
  [664026] = "{id=664026,Voice='Npc_Quest/664026',Text='何况这个梦境可以复活赫莲娜，她是你的母亲啊…还有什么比我们一家三口生活在一起重要！？',Speaker=829791,}",
  [664027] = "{id=664027,Voice='Npc_Quest/664027',Text='和你的母亲说说话吧，她一定也很想你。',Speaker=829791,}",
  [664028] = "{id=664028,Voice='Npc_Quest/664028',Text='母亲……',Speaker=829939,}",
  [664029] = "{id=664029,Voice='Npc_Quest/664029',Text='沃尔夫……我的孩子……',Speaker=829849,}",
  [664031] = "{id=664031,Voice='Npc_Quest/664031',Text='能够看到你长大的样子真好啊…德古拉，我想和沃尔夫单独聊一会儿。',Speaker=829849,}",
  [664032] = "{id=664032,Voice='Npc_Quest/664032',Text='好吧……',Speaker=829791,}",
  [664033] = "{id=664033,Voice='Npc_Quest/664033',Text='阻止德古拉！他的所有计划我都知道，阻止他疯狂的一切！',Speaker=829849,}",
  [664034] = "{id=664034,Voice='Npc_Quest/664034',Text='绝不能因为复活我一个人而献祭了所有无辜的民众……',Speaker=829849,}",
  [664035] = "{id=664035,Voice='Npc_Quest/664035',Text='可是……我也想和你在一起，母亲，我也希望你活着。',Speaker=829939,}",
  [664036] = "{id=664036,Voice='Npc_Quest/664036',Text='我也想和你们永远在一起，但我们不过是平凡的血肉之躯……',Speaker=829849,}",
  [664037] = "{id=664037,Voice='Npc_Quest/664037',Text='死亡是我的终局，不过是时间早晚之差，但我对你的爱不会因此消散。',Speaker=829849,}",
  [664038] = "{id=664038,Voice='Npc_Quest/664038',Text='为我筑起坟墓吧，就由你，沃尔夫，为这个荒诞的故事写下结局吧！',Speaker=829849,}",
  [664039] = "{id=664039,Voice='Npc_Quest/664039',Text='答应我，一定要阻止德古拉的计划！',Speaker=829849,}",
  [664040] = "{id=664040,Voice='Npc_Quest/664040',Text='我答应你……母亲。',Speaker=829939,}",
  [664041] = "{id=664041,Voice='Npc_Quest/664041',Text='好…还有，如果有那一天，请不要杀死德古拉，也不要对吸血鬼族赶尽杀绝。',Speaker=829849,}",
  [664042] = "{id=664042,Voice='Npc_Quest/664042',Text='母亲！……',Speaker=829939,}",
  [664043] = "{id=664043,Voice='Npc_Quest/664043',Text='以银牙猎手的精神起誓，答应我的请求！',Speaker=829849,}",
  [664044] = "{id=664044,Voice='Npc_Quest/664044',Text='我，沃尔夫，以猎人的意志起誓，绝不对吸血鬼族赶尽杀绝，也不会杀死德古拉。',Speaker=829939,}",
  [664045] = "{id=664045,Voice='Npc_Quest/664045',Text='永远记住，杀戮不是目的，和平才是……',Speaker=829939,}",
  [664046] = "{id=664046,Voice='Npc_Quest/664046',Text='德古拉，是你的父亲，你和他都是我挚爱的人。',Speaker=829849,}",
  [664047] = "{id=664047,Voice='Npc_Quest/664047',Text='他……才不是！！！',Speaker=829939,}",
  [664048] = "{id=664048,Voice='Npc_Quest/664048',Text='他也很爱你。带领吉芬尼亚所有人们逃出梦境吧……',Speaker=829849,}",
  [664049] = "{id=664049,Voice='Npc_Quest/664049',Text='沃尔夫别离开这里，不要离开我和你的母亲，这里才是你的家。',Speaker=829791,}",
  [664050] = "{id=664050,Voice='Npc_Quest/664050',Text='家？我的家在河的对岸，我从不属于这里。',Speaker=829939,}",
  [664051] = "{id=664051,Voice='Npc_Quest/664051',Text='想想你的母亲吧！这里才有你的羁绊，而不是那些和你毫无关系的人类！',Speaker=829791,}",
  [664052] = "{id=664052,Voice='Npc_Quest/664052',Text='我已经做出了选择！我的父亲，德古拉，你也该从你制造的梦境中醒醒了！',Speaker=829939,}",
  [664053] = "{id=664053,Voice='Npc_Quest/664053',Text='能听到你叫我一声父亲，我很高兴。',Speaker=829791,}",
  [664054] = "{id=664054,Voice='Npc_Quest/664054',Text='你高兴的太早了。',Speaker=829939,}",
  [664055] = "{id=664055,Voice='Npc_Quest/664055',Text='是吗？看来你已经做了令我失望的决定，你竟然为了让那些人活下去而牺牲你的母亲！',Speaker=829791,}",
  [664056] = "{id=664056,Voice='Npc_Quest/664056',Text='真想撕开你的身体看看我的血脉在你的身体中扮演怎样的角色？是叛徒？还是傻子！',Speaker=829791,}",
  [664057] = "{id=664057,Voice='Npc_Quest/664057',Text='抱歉，让您失望了。吸血鬼族的血脉是我一生的耻辱！',Speaker=829939,}",
  [664058] = "{id=664058,Voice='Npc_Quest/664058',Text='为了掩饰我的獠牙，我不敢笑，不敢说话，卑微的活在面具之下。',Speaker=829939,}",
  [664059] = "{id=664059,Voice='Npc_Quest/664059',Text='而我要做的一切，就是为了摆脱你的血脉压制，我不是吸血鬼族的孩子，我是沃尔夫！',Speaker=829939,}",
  [664060] = "{id=664060,Voice='Npc_Quest/664060',Text='呵，一厢情愿的孩子啊，宁愿低头做一个卑贱的人类，也不愿意抬头成为高尚的德古拉家族后裔。',Speaker=829791,}",
  [664061] = "{id=664061,Voice='Npc_Quest/664061',Text='牺牲别人的命运换来的高贵不值一提！我会带所有人走出梦境！',Speaker=829939,}",
  [664062] = "{id=664062,Voice='Npc_Quest/664062',Text='你确定你要这样做吗？如果是这样，即将来到的是一场真正的人类和血族的大战，而这一切都是因你的执着所起。',Speaker=829791,}",
  [664063] = "{id=664063,Voice='Npc_Quest/664063',Text='原本那些人安安静静地在梦境中等待自己的死亡！但因为你！他们要在恐惧与痛苦中死亡！',Speaker=829791,}",
  [664064] = "{id=664064,Voice='Npc_Quest/664064',Text='把真实还给吉芬尼亚所有人类！即便是战争，痛苦，也都是他们本该接受的现实。',Speaker=829939,}",
  [664065] = "{id=664065,Voice='Npc_Quest/664065',Text='他们渴望的是远离战争，而不是虚假的和平，人们所期待的和平，都会由最后一次战争带来！迎战吧！德古拉！',Speaker=829939,}",
  [664066] = "{id=664066,Voice='Npc_Quest/664066',Text='沃尔夫，你不配做德古拉家族的孩子！',Speaker=829791,}",
  [664067] = "{id=664067,Voice='Npc_Quest/664067',Text='我也从未想过成为你的孩子。',Speaker=829939,}",
  [664081] = "{id=664081,Voice='Npc_Quest/664081',Text='血染警钟再次响起，我们在梦境中太久以至于忘记了战斗，但我们应该醒来了。',Speaker=829939,}",
  [664082] = "{id=664082,Voice='Npc_Quest/664082',Text='极夜无法带给我们真实的和平…但战争可以！',Speaker=829939,}",
  [664083] = "{id=664083,Voice='Npc_Quest/664083',Text='只要战胜吸血鬼族，我们就可以获得和平！这是我们最后一次战争！',Speaker=829939,}",
  [664084] = "{id=664084,Voice='Npc_Quest/664084',Text='你们愿意与我一起加入这场战争吗！走出梦境！重回现实！',Speaker=829939,}",
  [664085] = "{id=664085,Voice='Npc_Quest/664085',Text='我愿意！',Speaker=829842,}",
  [664086] = "{id=664086,Voice='Npc_Quest/664086',Text='银牙猎手的精神永不沉没！',Speaker=829794,}",
  [664087] = "{id=664087,Voice='Npc_Quest/664087',Text='去吧！这只不过是一场未尽的战争，早该有个输赢，去吧！孩子们！',Speaker=829808,}",
  [664089] = "{id=664089,Voice='Npc_Quest/664089',Text='该醒了。',Speaker=829939,}",
  [664090] = "{id=664090,Voice='Npc_Quest/664090',Text='我承诺过，我会带所有人离开这个梦境！',Speaker=829939,}",
  [664091] = "{id=664091,Voice='Npc_Quest/664091',Text='你会后悔你的选择，为了赫莲娜我什么都可以做！',Speaker=829791,}",
  [664092] = "{id=664092,Voice='Npc_Quest/664092',Text='你要杀了我！杀了你的母亲吗？这里有哪里不好？我们可以一直在这里幸福地生活！',Speaker=829791,}",
  [664093] = "{id=664093,Voice='Npc_Quest/664093',Text='母亲并不希望用这样的方式活过来，你也该从这个梦境中醒来了！',Speaker=829939,}",
  [664094] = "{id=664094,Voice='Npc_Quest/664094',Text='母亲她……早就死了。',Speaker=829939,}",
  [664095] = "{id=664095,Voice='Npc_Quest/664095',Text='德古拉竟然将伊米尔之心碎片放在他的心脏里面，呵……怪不得我一直没找到。',Speaker=829862,}",
  [664096] = "{id=664096,Voice='Npc_Quest/664096',Text='这对父子可真有趣，一直不想承认德古拉血统的儿子沃尔夫用自损的方式承认了自己的血统，以自己的血液打开了只有德古拉家族才可以打开的梦境。',Speaker=829862,}",
  [664097] = "{id=664097,Voice='Npc_Quest/664097',Text='而父亲德古拉却又献出自己的生命换回沃尔夫的命，还做着让自己的孩子延续德古拉家族使命的美梦。',Speaker=829862,}",
  [664098] = "{id=664098,Voice='Npc_Quest/664098',Text='可是，伊米尔之心碎片理应是属于芙蕾雅大人的。',Speaker=829862,}",
  [664099] = "{id=664099,Voice='Npc_Quest/664099',Text='不不不，现在属于我的了！这是沃尔夫欠我的！',Speaker=829776,}",
  [664100] = "{id=664100,Voice='Npc_Quest/664100',Text='这是芙蕾雅大人的东西，你也配！？',Speaker=829862,}",
  [664101] = "{id=664101,Voice='Npc_Quest/664101',Text='芙蕾雅大人终将执掌一切！为所有种族创造新的世界！',Speaker=829862,}",
  [664102] = "{id=664102,Voice='Npc_Quest/664102',Text='时空终于回归了正轨，你也该回去了。',Speaker=829775,}",
  [664128] = "{id=664128,Text='杀戮不是目的，和平才是。',}",
  [664133] = "{id=664133,Text='怎么一来就有战争.',}",
  [664134] = "{id=664134,Text='说好的完美世界呢？',}",
  [664135] = "{id=664135,Text='在吉芬外，一个脸色苍白的人带领大量流民正在遭受护卫队的驱赶，冒险者接收流民的请求，与护卫队发生冲突，最终因为受伤陷入昏迷。\n脸色苍白的人唤醒冒险者，告诉冒险者流民想要去的地方，是一个完美世界，卢恩王国正在阻止民众前往这个世界。\n帮助所有人逃避护卫队的监视，前往那男人口中所说的完美世界，而脸色苍白的人却在进入后消失。',}",
  [664137] = "{id=664137,Voice='Npc_Quest/663750',Text='再见了沃尔夫……',Speaker=829832,}",
  [664138] = "{id=664138,Text='等待了一段时间后……',}",
  [664139] = "{id=664139,Voice='Npc_Quest/664086',Text='猎人的精神永不沉没……',Speaker=829847,}",
  [664140] = "{id=664140,Voice='Npc_Quest/664140',Text='沃尔夫回来了！',Speaker=829827,}",
  [664141] = "{id=664141,Voice='Npc_Quest/664141',Text='德古拉！！！',Speaker=829939,}",
  [664142] = "{id=664142,Voice='Npc_Quest/664142',Text='战场就在眼前！',Speaker=829939,}",
  [664143] = "{id=664143,Voice='Npc_Quest/664143',Text='杀戮吧……',}",
  [664144] = "{id=664144,Voice='Npc_Quest/664144',Text='杀戮吧！！',}",
  [664145] = "{id=664145,Voice='Npc_Quest/664145',Text='你杀害了我母亲，甚至连她死了都不放过。',Speaker=829939,}",
  [664146] = "{id=664146,Voice='Npc_Quest/664146',Text='今天，我要让你给她陪葬！！！',Speaker=829939,}",
  [664147] = "{id=664147,Text='沃尔夫，你的身上和我流淌着同样的血液！',Speaker=829791,}",
  [664148] = "{id=664148,Voice='Npc_Quest/664148',Text='德古拉，到此为止了！',Speaker=829939,}",
  [664149] = "{id=664149,Voice='Npc_Quest/664149',Text='太天真了！',Speaker=829791,}",
  [664150] = "{id=664150,Voice='Npc_Quest/664150',Text='你是？',Speaker=829791,}",
  [664152] = "{id=664152,Text='即便是完美世界中的民众，仍有少部分存有“恐惧血族症”，他们因为恐惧而产生互相猜疑而导致自相残杀。\n平息混乱后，长者告诫所有人这个完美世界早已消灭了所有血族。一个少年出现，否定了这个说法。\n少年即沃尔夫，沃尔夫清晰的感应到血族就存在这个世界，言论再次引起混乱，且遭到老者的斥责。并警告沃尔夫不能再提。\n沃尔夫请求冒险者的帮助，一起寻找血族的踪迹，找到血族后，沃尔夫十分凶残的将年幼的血族杀死，可以看出沃尔夫对血族的仇恨之深。\n沃尔夫将血族的证据带到长者前，长者在掀开证据之前，证据却化为灰烬，长者以沃尔夫扰乱稳定为由，与沃尔夫产生冲突，沃尔夫口罩掉落在地，长者靠近之前，年迈的猎人罗恩终止。\n罗恩化解纷争后，告诫沃尔夫在得到众人尊重之前永远不摘下口罩，因为沃尔夫是血族和人类的孩子，獠牙是沃尔夫的污点。沃尔夫唯有复仇才能洗去肮脏的血统。\n罗恩突然迅速的死亡，沃尔夫和冒险者将罗恩埋葬。沃尔夫获得了罗恩的剑。决定独自寻找死亡原因。\n而与此同时，吉芬大量人口迅速死亡，他们的共同点都是在一个时间段加速衰老并在一个时间点突然死亡。吉芬魔法团终于发现了异常，委任冒险者调查。\n而就在此时，吉芬发生了剧烈的震荡。\n冒险者寻找震源，发现一个巨大的捕梦网。且有血族把守。\n沃尔夫再次出现，带来惊人的推断，吉芬城所有人都困在梦境中，剧烈震荡很有可能是因为大量人口死去，梦境中的能量消逝太多，梦境不稳定而带来震动。\n动荡再次发生，吉芬魔法团决定尽快找到逃离梦境的办法。冒险者提出去自己进入的地方寻找线索。\n在进入的地方，冒险者再次遇到那个苍白脸色的男人，并最终确定苍白脸色男人是引渡人——将更多健康的人引渡到梦境中，维持梦境能量。但引渡人并不知道所谓的梦境出口在哪里，因为这个梦境血族可以自由出入。梦境以德古拉之血为钥，芙蕾雅所创建。\n更多普通人进入梦境后，梦境中得到了短暂的平衡。但为了走出梦境，吉芬与德古拉势力再次开战。\n沃尔夫成立猎人团，开始猎杀血族。但由于民众并不相信自己所处梦境不参与战争导致两方抗衡，屡屡失败。沃尔夫陷入困境。\n正当渴望复仇沃尔夫一筹莫展之际，有人提出赋予沃尔夫灭世之力。',}",
  [664153] = "{id=664153,Text='赋予力量后的沃尔夫，武力值得到提升，带领猎人团大量猎杀血族。\n沃尔夫通过背后的力量寻找到了德古拉的藏身之处。沃尔夫委托冒险者前往一起调查，就在这里，沃尔夫告诉了冒险者关于自己的仇恨——他的母亲因德古拉而死。并委托冒险者帮他吸引德古拉的注意力。\n在德古拉的城堡中，沃尔夫第一次与德古拉相见，德古拉奉劝沃尔夫不要阻止他的计划。沃尔夫故意激发两方的矛盾后，去执行秘密任务。不久后，沃尔夫失望而归带领冒险者逃离城堡。\n未完成任务的沃尔夫被梦罗克追击，沃尔夫这才告诉冒险者自己的力量来自梦罗克。沃尔夫将实情告诉梦罗克——趁乱混入德古拉城堡盗取伊米尔之心的碎片但尝试多次失败。梦罗克听完后推断沃尔夫是德古拉家族的后裔，因为德古拉家族一生守护伊米尔之心碎片，无法撼动伊米尔之心碎片，也就意味着，只要是德古拉家族的人便无法拿走伊米尔之心碎片。另外关于德古拉曾经消失的几年中，的确有传闻他爱上了人类。\n梦罗克散播关于沃尔夫的身世的传闻，导致沃尔夫在猎人团中失信，但却得到了曾经帮助过的民众的支持——血族的血液无法抹去沃尔夫对人类的保护的决心。这让沃尔夫更加坚定的复仇。同时沃尔夫委托冒险者开始计划摆脱梦罗克的制约。\n冒险者将德古拉的势力引入梦罗克的力量范围中，借用德古拉之力击败梦罗克，梦罗克不得不放弃窃取伊米尔之心碎片复活计划。解决梦罗克的麻烦后，沃尔夫决定探入德古拉的城堡中，寻找关于自己身世的真相。在城堡中，沃尔夫见到了自己思念依旧的身影。\n城堡中，沃尔夫见到了“死去”的母亲赫莲娜，只是看起来毫无生气。沃尔夫的眼泪让赫莲娜短暂恢复了意识，并告诉沃尔夫一切真相——德古拉的确是沃尔夫的父亲。五年前，血族异心者为了杀死德古拉而闯入家中，赫莲娜为了救德古拉而被异心者杀死，德古拉摘除赫莲娜心脏是为了用药水单独保存并寻求复活赫莲娜的办法，德古拉一心想要救活赫莲娜，而沃尔夫被父亲罗恩带走。德古拉曾试图寻找沃尔夫，却没有线索。为了复活赫莲娜，德古拉与芙蕾雅签订协议，以德古拉血为钥匙，将吉芬彻底陷入在芙蕾雅的梦境中，这便是为什么吉芬突然进入了空前完美的状态，复活的流程需要十年，过去的五年只够让赫莲娜恢复短暂的意识。除此之外德古拉认为这样也可以让血族一族避免战争。但这个代价便是吉芬的民众都将为了复活赫莲娜而彻底死去，最终芙蕾雅拿走德古拉家族守护的伊米尔之心碎片。\n赫莲娜希望沃尔夫阻止德古拉的计划，但请求沃尔夫，如果父子必有一战，希望沃尔夫不要杀死德古拉。两人对话被德古拉中断。\n沃尔夫陷入两难抉择，最终他在母亲和民众之间，选择了民众。\n一场人类和血族的大战即将开启。',}",
  [664154] = "{id=664154,Text='沃尔夫击败了德古拉，并守护了对母亲赫莲娜的诺言，不杀死德古拉。\n德古拉却让沃尔夫再一次做选择，因为击败血族并不能轻易逃离梦境，只有以沃尔夫的鲜血为钥匙，才能带领所有人走出梦境。德古拉让沃尔夫选择，牺牲民众，还是牺牲自己和母亲，救民众。\n沃尔夫最终选择用德古拉的武器刺入自己的心脏，以自己的鲜血带领所有民众走出梦境。\n德古拉的计划落败，但最后以自己的力量将沃尔夫变成了死灵。',}",
  [664176] = "{id=664176,Voice='Npc_Quest/664176',Text='完美世界？那就好好看看这个所谓的完美世界吧。',Speaker=829797,Option='{太好了,0},{正有此意,0}',}",
  [664177] = "{id=664177,Voice='Npc_Quest/664177',Text='这个完美的世界处在极夜中，人们常常感到莫名的困顿，而连银牙猎手原本正在建造的塔也在极夜之后停止修建。',Speaker=829797,Option='这是吉芬塔？！',}",
  [664178] = "{id=664178,Voice='Npc_Quest/664178',Text='它叫作吉芬塔吗？',Speaker=829797,Option='在未来就叫这个名字',}",
  [664179] = "{id=664179,Voice='Npc_Quest/664179',Text='这座塔原本是银牙猎手用于纪念那些死于血族之手的猎人所建，只是后来…血族一夜之间消失了，而银牙猎手的势力也因此式微，这座塔也停止了修建。',Speaker=829797,}",
  [664181] = "{id=664181,Text='用自己的生命将所有人类送出梦境。',Speaker=829791,}",
  [664182] = "{id=664182,Text='再用新的梦境封锁所有血族……',Speaker=829791,}",
  [664183] = "{id=664183,Text='沃尔夫……你和你的母亲一样……为了坚持自己的信念，把痛苦留给我来承受……',Speaker=829791,}",
  [664184] = "{id=664184,Text='活下去，承受那些我曾承受的痛苦！',Speaker=829791,}",
  [664185] = "{id=664185,Text='杀戮不是目的，和平……才是……',}",
  [664213] = "{id=664213,Text='头饰，我都愿意给你… 不过得拿乐园币来换哦！',Speaker=829948,}",
  [664215] = "{id=664215,Text='头饰，我都愿意给你… 不过得拿乐园币来换哦！',Speaker=829950,}",
  [664223] = "{id=664223,Voice='Npc_Quest/664223',Text='尽快解决它们！看来出逃者并不希望有人可以进入那里！',Speaker=816772,}",
  [664224] = "{id=664224,Voice='Npc_Quest/664224',Text='出逃者的力量超出了我的预料！',Speaker=816772,}",
  [664225] = "{id=664225,Voice='Npc_Quest/664225',Text='小心一点！这些魔物的身上都沾染着出逃者的气息。',Speaker=816772,}",
  [664226] = "{id=664226,Voice='Npc_Quest/664226',Text='尽快平息出逃者导致的混乱！否则普隆德拉也会……',Speaker=816772,}",
  [664235] = "{id=664235,Voice='Npc_Quest/664235',Text='那是黑炎龙的暗爪营！他们在攻击龙族子民！',Speaker=816772,}",
  [664236] = "{id=664236,Text='他受的伤很严重……',}",
  [664237] = "{id=664237,Voice='Npc_Quest/664237',Text='我……我只是想要离开龙族的深渊……想要离开……',Speaker=816782,}",
  [664238] = "{id=664238,Text='……',Speaker=816782,}",
  [664239] = "{id=664239,Text='他停止了呼吸，双眼空洞地望向天空，到死似乎都在渴求着什么。',}",
  [664240] = "{id=664240,Voice='Npc_Quest/664240',Text='你看！这里有人类的脚印！',Speaker=816772,}",
  [664241] = "{id=664241,Voice='Npc_Quest/664241',Text='深渊之湖由于结界的原因，不应该会有人类踏足……',Speaker=816772,}",
  [664242] = "{id=664242,Voice='Npc_Quest/664242',Text='或许，这是出逃者留下的！！跟上脚印去看看！',Speaker=816772,}",
  [664243] = "{id=664243,Voice='Npc_Quest/664243',Text='不过搜寻的路上要小心，我感受到目前的深渊之湖处在一种极其奇怪的力量之中……',Speaker=816772,}",
  [664244] = "{id=664244,Voice='Npc_Quest/664244',Text='就是他！我在他的身上发现了与出逃者匹配的信息！把这个垃圾回收！',Speaker=816772,}",
  [664245] = "{id=664245,Voice='Npc_Quest/664245',Text='好可怕的火…救救我们。',Speaker=816800,}",
  [664247] = "{id=664247,Text='谁来救救我们！',}",
  [664251] = "{id=664251,Voice='Npc_Quest/664251',Text='又见面了。',Speaker=816975,Option='好久不见',}",
  [664252] = "{id=664252,Voice='Npc_Quest/664252',Text='等等，他是谁？我在他的身上匹配到了与出逃者相关的信息！',Speaker=816772,Option='{刺客公会会长,0},{鼎鼎大名的无名者,0},{他不会是出逃者,0}',}",
  [664253] = "{id=664253,Voice='Npc_Quest/664253',Text='我掌管所有时间线，关于时空乱流回收站中的垃圾资料虽然并不完整，但不会出错。',Speaker=816772,}",
  [664254] = "{id=664254,Voice='Npc_Quest/664254',Text='也许你的身上与时空乱流出逃者有着不为人知的关联……',Speaker=816772,}",
  [664255] = "{id=664255,Voice='Npc_Quest/664255',Text='这里从未有人类踏足，你是如何突破结界进入深渊之湖的？',Speaker=816772,}",
  [664256] = "{id=664256,Voice='Npc_Quest/664256',Text='这个手环指引我来到这里，它能感应到这个世界上平衡正在遭受破坏的地方。',Speaker=816975,}",
  [664257] = "{id=664257,Voice='Npc_Quest/664257',Text='现在最重要的，是扑灭燃烧天地树的大火。天地树被毁，意味着九界彻底崩溃。',Speaker=816975,}",
  [664258] = "{id=664258,Voice='Npc_Quest/664258',Text='说的没错，但这并没有那么容易。这是火之龙引起的大火，它力量强大，是守护天地树树根的守卫龙之一。',Speaker=816772,}",
  [664259] = "{id=664259,Voice='Npc_Quest/664259',Text='想要扑灭火之龙造成的大火，就需要找到风、土、水三只守护龙，获取它们的元素之力。',Speaker=816772,}",
  [664260] = "{id=664260,Voice='Npc_Quest/664260',Text='我会解决。',Speaker=816975,Option='{可靠！帅气！,0},{我可以休息一下了！,0}',}",
  [664261] = "{id=664261,Voice='Npc_Quest/664261',Text='请和冒险者一起行动，你的嫌疑并没有解除。',Speaker=816772,Option='{又是我！,0},{还是我？,0},{我就知道！,0}',}",
  [664262] = "{id=664262,Voice='Npc_Quest/664262',Text='我的目标只有一个，维护深渊之湖的平衡。',Speaker=816975,}",
  [664266] = "{id=664266,Text='谢谢……是你们救我……',Speaker=816812,}",
  [664267] = "{id=664267,Text='是谁袭击了你？',Speaker=816975,}",
  [664268] = "{id=664268,Text='我也不知道，只看到一股蓝色的力量突然向我袭来！我还是第一次见到那么强大的力量……',Speaker=816812,}",
  [664269] = "{id=664269,Text='不仅如此，我还看到那股力量袭击了火之龙导致他力量失控，将天地树树根点着了！',Speaker=816812,}",
  [664270] = "{id=664270,Text='我们正为此事而来，熄灭大火需要你的疾风之息。',Speaker=816975,Option='{说明情况,0},{讨要疾风之息,0}',}",
  [664271] = "{id=664271,Text='给你们给你们！可千万不要出事啊！黑炎龙大人知道了我们四个就完蛋了！',Speaker=816812,}",
  [664274] = "{id=664274,Text='奇怪……我刚才在干什么……似乎对你们多有冒犯，很抱歉。等我回忆一下到底发生了什么……',Speaker=816820,}",
  [664275] = "{id=664275,Text='我想起来了！我本来想要帮助火之龙摆脱一股奇怪的力量，但最终连我也受影响变成了刚才的样子……',Speaker=816820,Option='{说明情况,0},{讨要大地之息,0}',}",
  [664276] = "{id=664276,Text='大地之息分散在附近的大地之中，需使力量将之吹起。',Speaker=816820,}",
  [664277] = "{id=664277,Text='请速速去寻找大地之息吧！',Speaker=816820,}",
  [664278] = "{id=664278,Text='保护好元素之力，别被这群家伙抢走了！',Speaker=816772,}",
  [664286] = "{id=664286,Text='水之龙回来了~~太好啦~太好啦~',Speaker=816825,}",
  [664291] = "{id=664291,Voice='Npc_Quest/664291',Text='喂喂——别再给我增加工作量了！',Speaker=816772,}",
  [664292] = "{id=664292,Voice='Npc_Quest/664292',Text='可恶，我要毁了天地树！',Speaker=816830,}",
  [664293] = "{id=664293,Voice='Npc_Quest/664293',Text='如果龙族的命运就是待在深渊之湖中，倒不如让整个世界都毁灭！',Speaker=816830,}",
  [664294] = "{id=664294,Voice='Npc_Quest/664294',Text='大火会将他们烧为灰烬！我们分头行动，务必救出全部的龙！',Speaker=816975,}",
  [664295] = "{id=664295,Voice='Npc_Quest/664295',Text='谢谢你救了我们。',Speaker=816831,}",
  [664296] = "{id=664296,Voice='Npc_Quest/664296',Text='多亏了你……不然我们这些老人和孩子们就会在火之龙的大火下丧命。',Speaker=816832,}",
  [664297] = "{id=664297,Voice='Npc_Quest/664297',Text='真希望能快点摆脱暗爪营的追踪，这样我们才能离开深渊之湖，再也不用担心受怕了……',Speaker=816832,}",
  [664298] = "{id=664298,Voice='Npc_Quest/664298',Text='这里到底发生了什么？黑炎龙的暗爪营为什么要追逐你们？',Speaker=816975,}",
  [664299] = "{id=664299,Voice='Npc_Quest/664299',Text='哎，这一切都是因为龙族的两位领袖[c][ffff00]赤炎龙与黑炎龙正在交战……[-][/c]',Speaker=816832,Option='为何交战？',}",
  [664300] = "{id=664300,Voice='Npc_Quest/664300',Text='为了龙族的未来……他们的意见产生了分歧，是黑炎龙用武力挑起了战争。',Speaker=816832,}",
  [664301] = "{id=664301,Voice='Npc_Quest/664301',Text='赤炎龙想要带领所有的龙族子民离开深渊之湖，但黑炎龙却坚持龙族应该留在这里！',Speaker=816832,}",
  [664302] = "{id=664302,Voice='Npc_Quest/664302',Text='蕾蒂西亚那家伙在搞什么？龙族若是离开深渊之湖，谁来守卫天地树世界不被时空垃圾入侵？！',Speaker=816772,}",
  [664303] = "{id=664303,Voice='Npc_Quest/664303',Text='我无法评判他们的对错，但我希望至少艾尔肯能离开这里……',Speaker=816832,}",
  [664304] = "{id=664304,Voice='Npc_Quest/664304',Text='我要带艾尔肯前往赤炎龙的领地，就先告辞了。',Speaker=816832,}",
  [664306] = "{id=664306,Text='谢谢！',}",
  [664307] = "{id=664307,Text='得救了！',}",
  [664308] = "{id=664308,Text='快走快走！',}",
  [664309] = "{id=664309,Voice='Npc_Quest/664309',Text='深渊之湖是时空垃圾站与天地树世界之间的缝隙。',Speaker=816772,}",
  [664310] = "{id=664310,Voice='Npc_Quest/664310',Text='决不能让时空垃圾站中逃离的垃圾离开深渊之湖是龙族的使命！',Speaker=816772,}",
  [664311] = "{id=664311,Voice='Npc_Quest/664311',Text='你们不要过来啊！否则！我会让你们尝尝火焰灼烧的滋味！',Speaker=816830,Option='{冷静！,0},{你到底想做什么？,0}',}",
  [664312] = "{id=664312,Voice='Npc_Quest/664312',Text='走开！你们这群外族人！你们根本不懂！龙族的痛苦！',Speaker=816830,}",
  [664313] = "{id=664313,Voice='Npc_Quest/664313',Text='为这该死的使命，战死的龙族白骨能填满深渊之湖所有的湖沟！',Speaker=816830,}",
  [664314] = "{id=664314,Voice='Npc_Quest/664314',Text='一切都是为了整个天地树世界！',Speaker=816772,}",
  [664315] = "{id=664315,Voice='Npc_Quest/664315',Text='我呸！你同为龙族！为什么不能理解我们的痛苦！',Speaker=816830,}",
  [664316] = "{id=664316,Voice='Npc_Quest/664316',Text='就让你们品尝一下被困在大火中的滋味吧！就像龙族一生都困在深渊之湖中一样！',Speaker=816830,}",
  [664317] = "{id=664317,Voice='Npc_Quest/664317',Text='看看这个地方，除了战士以外，这里的龙族大多都是老人和孩子！',Speaker=816830,}",
  [664318] = "{id=664318,Voice='Npc_Quest/664318',Text='而孩子们长大后，也将踏上他们死去的父母之路——',Speaker=816830,}",
  [664319] = "{id=664319,Voice='Npc_Quest/664319',Text='战死在守护时空乱流回收站的战场上！',Speaker=816830,}",
  [664320] = "{id=664320,Voice='Npc_Quest/664320',Text='怒火之息永不熄灭，这是我的怒火，我要让所有人感受到！',Speaker=816830,}",
  [664321] = "{id=664321,Voice='Npc_Quest/664321',Text='杀了我吧，反正我迟早也会因为与时空乱流中的垃圾们对战而死。',Speaker=816830,}",
  [664322] = "{id=664322,Voice='Npc_Quest/664322',Text='我并不想干涉你的想法，但你必须要知道，天地树是生命之源，如果它彻底被烧毁，整个世界都将不复存在，这当中也包括龙族。',Speaker=816975,}",
  [664323] = "{id=664323,Voice='Npc_Quest/664323',Text='你想要彻底断送龙族的未来吗？',Speaker=816975,}",
  [664324] = "{id=664324,Text='……！！！',Speaker=816830,}",
  [664325] = "{id=664325,Voice='Npc_Quest/664325',Text='我……我……不想这样……请和我一起去熄灭燃烧天地树的火。',Speaker=816830,}",
  [664343] = "{id=664343,Voice='Npc_Quest/664343',Text='竟是区区凡人之躯，我会阻止你想要做的一切！！',Speaker=816941,}",
  [664356] = "{id=664356,Voice='Npc_Quest/664356',Text='我们还会再见的！',Speaker=816772,}",
  [664357] = "{id=664357,Voice='Npc_Quest/664357',Text='虽然神殿已经化为遗迹，但仍残存着神的力量。',Speaker=816975,}",
  [664358] = "{id=664358,Voice='Npc_Quest/664358',Text='要召唤神影需要将三样神谕之物放置在神台上，不出意外的话神谕之物就在附近。',Speaker=816975,}",
  [664359] = "{id=664359,Voice='Npc_Quest/664359',Text='与此同时，我会念诵祷文，完成仪式。',Speaker=816975,}",
  [664366] = "{id=664366,Text='羊皮纸书，封面用金色的符文装饰，书页泛黄，上面的祷文清晰可见。',Speaker=816838,Option='拾起',}",
  [664367] = "{id=664367,Text='汇聚神明的力量，可以为神影降临驱散黑暗。',Speaker=816837,Option='拾起',}",
  [664368] = "{id=664368,Text='完成召唤神谕仪式后，神影会在羽翼的光下出现。',Speaker=816836,Option='拾起',}",
  [664369] = "{id=664369,Voice='Npc_Quest/664369',Text='有趣，你们的身上有时空龙的祝福……',Speaker=816844,}",
  [664370] = "{id=664370,Voice='Npc_Quest/664370',Text='你们的祈求，神已经听见。',Speaker=816844,}",
  [664371] = "{id=664371,Voice='Npc_Quest/664371',Text='低下你们的头颅，向神行礼，让我看到你们的谦卑和服从。',Speaker=816844,}",
  [664372] = "{id=664372,Voice='Npc_Quest/664372',Text='为什么不向我行礼。',Speaker=816844,}",
  [664373] = "{id=664373,Voice='Npc_Quest/664373',Text='我并不信奉神明，而只相信自己。',Speaker=816975,}",
  [664374] = "{id=664374,Voice='Npc_Quest/664374',Text='有趣的家伙，那就告诉我，你想得到什么指引。',Speaker=816844,}",
  [664375] = "{id=664375,Voice='Npc_Quest/664375',Text='天地树被一股力量所侵蚀，我想知道治愈天地树的办法。',Speaker=816975,}",
  [664376] = "{id=664376,Voice='Npc_Quest/664376',Text='神族的确有一本史册，上面记载着相关内容。',Speaker=816844,}",
  [664377] = "{id=664377,Voice='Npc_Quest/664377',Text='这份史册被分成了三份，分别由三位神使保管。找齐它们，就能找到答案。',Speaker=816844,}",
  [664378] = "{id=664378,Text='神啊，一切都乱套了……人类？怎么会出现在深渊之湖？……',Speaker=816845,Option='说明情况',}",
  [664379] = "{id=664379,Text='……如果龙族能早一些得到神的回应，那现在的这一切都不会发现。',Speaker=816845,}",
  [664380] = "{id=664380,Text='神殿曾是神族和龙族沟通之地，为龙族守护深渊之湖提供帮助。',Speaker=816845,}",
  [664381] = "{id=664381,Text='但是他们已经消失太久了，久到龙族都忘了为何要留在这里。',Speaker=816845,}",
  [664382] = "{id=664382,Text='你们要的史册内页就在那群狂暴的黄俄希托斯手里，他们从我这里抢走了它。',Speaker=816845,}",
  [664383] = "{id=664383,Text='那东西对我而言已经没用了，如果能抢回来就给你们吧。',Speaker=816845,}",
  [664384] = "{id=664384,Text='在深渊中，曾照耀着光辉的神圣殿堂如今已沦为黑暗的避风港。',Speaker=816846,}",
  [664385] = "{id=664385,Text='你们，为何而来？',Speaker=816846,}",
  [664386] = "{id=664386,Text='呵……神影？这里早就没有出现过什么神影，你们只是想骗走我的神族内页！',Speaker=816846,}",
  [664387] = "{id=664387,Text='你刚才说，神影？神族终于降临了吗?',Speaker=816846,}",
  [664388] = "{id=664388,Text='原来神族并没有放弃这里！很抱歉，因为这里太久没有神族降临，而让我以为神族放弃了深渊之湖，也放弃了我们这些神使。',Speaker=816846,}",
  [664389] = "{id=664389,Text='在对神族的怨念中我失去了理智，很抱歉，怨念是对神明的亵渎啊，我竟然犯下这样的错误。',Speaker=816846,}",
  [664390] = "{id=664390,Text='请将神族史册的内页带走吧！我已经不配守护它了。',Speaker=816846,}",
  [664391] = "{id=664391,Text='虽然我知道你们找我，肯定有别的事情。但……这些小家伙真的很需要你们的帮助。',Speaker=816847,}",
  [664392] = "{id=664392,Text='他们的父母都因守护时空乱流回收站而战死……',Speaker=816847,}",
  [664393] = "{id=664393,Text='而最近，赤鳞团和暗爪营正在交战，也导致这些孩子无法得到食物的补给。',Speaker=816847,}",
  [664394] = "{id=664394,Text='哎，其实我是赞成赤炎龙带走他们的，他们应该获得自由。',Speaker=816847,}",
  [664395] = "{id=664395,Text='拜托为这些小龙们抓一些鱼吧！在开满鲜花的地方，有他们喜欢吃的小鱼。',Speaker=816847,}",
  [664396] = "{id=664396,Text='谢谢你们！这些小鱼足够孩子们吃一段日子，真希望他们平平安安的离开这里啊！',Speaker=816847,Option='说明情况',}",
  [664397] = "{id=664397,Text='神，竟然真的降临了！！',Speaker=816847,}",
  [664398] = "{id=664398,Text='托斯克是帮助赤鳞团带走龙族的帮凶，抓住他！！！',Speaker=816860,}",
  [664399] = "{id=664399,Text='谢谢你们保护了我，也保护了这群小龙！请带走史册内页吧！',Speaker=816847,}",
  [664400] = "{id=664400,Voice='Npc_Quest/664400',Text='这就是来自神族的史册，去探求其中关于天地树的相关内容吧！',Speaker=816844,}",
  [664401] = "{id=664401,Voice='Npc_Quest/664401',Text='诸神黄昏后，神族为了防止天地树再出意外，将天地树的原初之力存放在一处时间裂隙之中。',Speaker=816975,}",
  [664402] = "{id=664402,Voice='Npc_Quest/664402',Text='只要打开这处时间裂隙，从中取得原初之力浇灌天地树，天地树便会得到治愈。',Speaker=816975,Option='{位置在哪？,0},{如何打开？,0}',}",
  [664403] = "{id=664403,Voice='Npc_Quest/664403',Text='在[c][ffff00]龙息祭台[-][/c]有着四个龙息之锁封印的时间裂隙，而[c][ffff00]原初之力[-][/c]就在时间裂隙中。',Speaker=816975,}",
  [664404] = "{id=664404,Voice='Npc_Quest/664404',Text='我们要尽快前往龙息祭台！',Speaker=816975,}",
  [664405] = "{id=664405,Voice='Npc_Quest/664405',Text='救救我们……',Speaker=816859,}",
  [664407] = "{id=664407,Voice='Npc_Quest/664407',Text='黑炎龙彻底疯了！他为了阻止我们离开深渊之湖，竟然想要将我们禁锢在[c][ffff00]黑火雷[-][/c]中！',Speaker=816859,}",
  [664408] = "{id=664408,Voice='Npc_Quest/664408',Text='太可恶了，我们只是想离开这里，从来没有想过与他们敌对来着，还好我跑了出来！',Speaker=816859,}",
  [664409] = "{id=664409,Voice='Npc_Quest/664409',Text='你们应该已经知晓龙族的使命，而这个使命源于一个约定。',Speaker=816844,}",
  [664410] = "{id=664410,Voice='Npc_Quest/664410',Text='现在的龙族子民不应该为过去的约定，而失去离开这里的权力，这对他们来说不公平。',Speaker=816844,}",
  [664411] = "{id=664411,Voice='Npc_Quest/664411',Text='虽然我知道，治愈天地树比任何事情都要重要，但请……',Speaker=816844,}",
  [664412] = "{id=664412,Voice='Npc_Quest/664412',Text='我会救出他们。',Speaker=816975,}",
  [664413] = "{id=664413,Text='不要离开……',}",
  [664414] = "{id=664414,Text='背叛者……',}",
  [664415] = "{id=664415,Text='你们被骗了……',}",
  [664416] = "{id=664416,Text='得救了！',Speaker=816783,}",
  [664417] = "{id=664417,Text='跟紧我们！我们会保证你们的安全！',Speaker=816975,}",
  [664418] = "{id=664418,Voice='Npc_Quest/664418',Text='这些龙族之中有父母亲友因为守护时空乱流回收站而战死，也有两龙内战的受害者。',Speaker=816844,}",
  [664419] = "{id=664419,Voice='Npc_Quest/664419',Text='他们曾多次祈求神族的帮助，然而却得不到回应……很抱歉，我仅剩的力量微乎其微而无法聆听到龙族的呼唤。',Speaker=816844,}",
  [664420] = "{id=664420,Voice='Npc_Quest/664420',Text='神影大人……我好痛……好痛！',Speaker=816893,}",
  [664421] = "{id=664421,Voice='Npc_Quest/664421',Text='糟了，黑火雷的力量仍然在侵蚀着他们！要不了多久，他们都会死的……',Speaker=816859,}",
  [664422] = "{id=664422,Voice='Npc_Quest/664422',Text='这一次，我听到了来自龙族的祈求。龙族的子民需要神的力量，我将以我的力量治愈你们！',Speaker=816844,}",
  [664423] = "{id=664423,Voice='Npc_Quest/664423',Text='我已经聆听到你们的祈求。你们害怕战争，害怕分离。你们想要摆脱命运的束缚。',Speaker=816844,}",
  [664424] = "{id=664424,Voice='Npc_Quest/664424',Text='你们在渴望改变，而你们所渴求的即将来临，就如黑夜跟随白天，绝望必将迎来希望。',Speaker=816844,}",
  [664425] = "{id=664425,Voice='Npc_Quest/664425',Text='而我将引领你们前往自由，去闪麟高地吧！那里将有人为你们打开深渊之湖的出口。',Speaker=816844,}",
  [664426] = "{id=664426,Voice='Npc_Quest/664426',Text='神只是给了龙族指引，真正能帮助龙族的只有龙族。希望他们将不再对神族感到失望。也希望他们走出龙族的深渊。',Speaker=816844,}",
  [664427] = "{id=664427,Voice='Npc_Quest/664427',Text='只是，为了救治龙族，我的神力已经耗尽，也将消散于此。无法继续帮助你们前行。',Speaker=816844,}",
  [664428] = "{id=664428,Voice='Npc_Quest/664428',Text='希望你们能够尽快前往龙息祭台，顺利打开四个龙息之锁，打开时间裂隙，拿到原初之力。',Speaker=816844,Option='交给我们',}",
  [664430] = "{id=664430,Voice='Npc_Quest/664430',Text='冒险者，我的手镯每一次震颤，必是诡计出现的时刻。',Speaker=816975,}",
  [664431] = "{id=664431,Voice='Npc_Quest/664431',Text='我们似乎落入了某个精心设计的诡计中。',Speaker=816975,Option='{怎么回事？,0},{诡计？谁的诡计？,0}',}",
  [664432] = "{id=664432,Voice='Npc_Quest/664432',Text='我不知道……但我们现在只能继续前行，前往龙息祭坛。总之我们要尽快治愈天地树！',Speaker=816975,}",
  [664436] = "{id=664436,Voice='Npc_Quest/664436',Text='龙族的子民不应该一生困于深渊之湖！最后死在深渊之湖！',Speaker=816866,}",
  [664437] = "{id=664437,Voice='Npc_Quest/664437',Text='守护时空乱流回收站是龙族的使命！',Speaker=816867,}",
  [664438] = "{id=664438,Voice='Npc_Quest/664438',Text='你们暗爪营喜欢送死你们就自己去！凭什么拉上整个龙族！',Speaker=816866,}",
  [664439] = "{id=664439,Voice='Npc_Quest/664439',Text='和你们这些见识短浅的家伙没什么好多说！接受制裁吧！',Speaker=816867,}",
  [664440] = "{id=664440,Voice='Npc_Quest/664440',Text='你们说那些，都是冠冕堂皇的话！',Speaker=816866,}",
  [664441] = "{id=664441,Voice='Npc_Quest/664441',Text='我不相信没有我们，这里的问题就没有人来解决！',Speaker=816866,}",
  [664442] = "{id=664442,Voice='Npc_Quest/664442',Text='谢谢你们的帮助。我是赤鳞团的军师，你们可以叫我泰诺。',Speaker=816866,}",
  [664443] = "{id=664443,Voice='Npc_Quest/664443',Text='我奉赤炎龙之命，带领龙息祭台的龙族子民前往闪鳞高地。',Speaker=816866,}",
  [664444] = "{id=664444,Voice='Npc_Quest/664444',Text='接下来你们也看到，半途中，我们遭遇了暗爪营的拦截。',Speaker=816866,}",
  [664445] = "{id=664445,Voice='Npc_Quest/664445',Text='龙族的子民们！只要度过这一次的难关，我们便可以走向闪鳞高地获得自由！',Speaker=816866,}",
  [664446] = "{id=664446,Voice='Npc_Quest/664446',Text='我深知前往自由的路充满艰难！但你们记住你们不是孤军奋战，赤鳞团会永远守护你们！',Speaker=816866,}",
  [664447] = "{id=664447,Voice='Npc_Quest/664447',Text='太棒了，我们就要自由了！永远相信赤炎龙！相信赤鳞团！',Speaker=816960,}",
  [664448] = "{id=664448,Voice='Npc_Quest/664448',Text='快去吧，赤炎龙正在等着大家，闪鳞高地就是我们获得自由的出口！',Speaker=816866,}",
  [664449] = "{id=664449,Voice='Npc_Quest/664449',Text='我会在这里接应更多想要离开的龙族，期待我们在另一片蓝天之下相遇！',Speaker=816866,}",
  [664459] = "{id=664459,Voice='Npc_Quest/664459',Text='伟大的龙族英魂们，我们在此致敬，你们的英勇和智慧，我们将铭记在心中。希望你们远离战争，得到安息。',Speaker=816866,}",
  [664460] = "{id=664460,Voice='Npc_Quest/664460',Text='是龙息之锁！它们分别在龙息祭台的东南西北四个方向。打开它们就能找到治愈天地树的原初之力！',Speaker=816866,}",
  [664461] = "{id=664461,Voice='Npc_Quest/664461',Text='龙息之锁不能被打开！！',Speaker=816860,}",
  [664462] = "{id=664462,Text='奥斯卡大人……是你吗？……',Speaker=816873,}",
  [664463] = "{id=664463,Text='为了守护……我绝不后退……',Speaker=816874,}",
  [664464] = "{id=664464,Text='这不是你们该来的地方……',Speaker=816875,}",
  [664465] = "{id=664465,Text='再见……我将踏上归途……',Speaker=816876,}",
  [664466] = "{id=664466,Voice='Npc_Quest/664466',Text='别让它们靠近祭坛！',Speaker=816772,}",
  [664467] = "{id=664467,Voice='Npc_Quest/664467',Text='这里发生的一切都糟糕透了……',Speaker=816772,}",
  [664468] = "{id=664468,Voice='Npc_Quest/664468',Text='我需要调取时间线来了解情况……',Speaker=816772,}",
  [664470] = "{id=664470,Voice='Npc_Quest/664470',Text='我已经知晓了前因后果。或许你们不知道，刚才被带走的巨龙，是我的真身。',Speaker=816772,}",
  [664471] = "{id=664471,Voice='Npc_Quest/664471',Text='为了管理时间线，我将自己化作无数分身，而真身则陷入了沉睡。',Speaker=816772,}",
  [664472] = "{id=664472,Voice='Npc_Quest/664472',Text='龙息之锁是我为保护真身而设下的结界，本来只有我本人能够解开…',Speaker=816772,}",
  [664473] = "{id=664473,Voice='Npc_Quest/664473',Text='没想到却有人利用我给予你们的赐福，用诡计让你们解开了结界。',Speaker=816772,}",
  [664474] = "{id=664474,Voice='Npc_Quest/664474',Text='果然是诡计……设下诡计的人究竟是谁？',Speaker=816975,}",
  [664475] = "{id=664475,Voice='Npc_Quest/664475',Text='让我们回到最开始，那本指引你们做出错误决定的史册。',Speaker=816772,}",
  [664476] = "{id=664476,Voice='Npc_Quest/664476',Text='史册上面附着的力量与侵蚀天地树的力量相同。',Speaker=816772,}",
  [664477] = "{id=664477,Voice='Npc_Quest/664477',Text='诡计的源头果然是你……',Speaker=816975,}",
  [664478] = "{id=664478,Voice='Npc_Quest/664478',Text='你们的使命已经完成！就此消失吧！',Speaker=816892,}",
  [664479] = "{id=664479,Voice='Npc_Quest/664479',Text='这场游戏的胜者只会是我，愚蠢的家伙！',Speaker=816892,}",
  [664480] = "{id=664480,Voice='Npc_Quest/664480',Text='这本史册是神影精心为我们准备的陷阱，目的是为了让我们打开结界夺走时空龙的真身。',Speaker=816975,}",
  [664481] = "{id=664481,Voice='Npc_Quest/664481',Text='哎……',Speaker=816772,Option='{怎么了？,0},{还有什么坏消息？,0}',}",
  [664482] = "{id=664482,Voice='Npc_Quest/664482',Text='和你们分开的这段时间，我搜寻了大量资料，终于找到了治愈天地树的办法。',Speaker=816772,Option='{好消息啊！,0},{不会还有但是吧？,0}',}",
  [664483] = "{id=664483,Voice='Npc_Quest/664483',Text='还没到但是……想要治愈天地树就需要集齐[c][ffff00]四颗龙族之星[-][/c]。接下来，就轮到但是了……',Speaker=816772,}",
  [664484] = "{id=664484,Voice='Npc_Quest/664484',Text='这四颗龙族之星的其中一颗，在我的真身体内……我之前说过，进入深渊之湖后，是无法离开的，也正因为这样，我才会留真身在此，以分身离开这里管理时空。',Speaker=816772,Option='哎……',}",
  [664485] = "{id=664485,Voice='Npc_Quest/664485',Text='此刻，无论隐藏在暗中的人将真身夺走的目的是什么，都必须找到我的真身！',Speaker=816772,}",
  [664486] = "{id=664486,Voice='Npc_Quest/664486',Text='现在，我需要借助你们的力量感应真身的位置。',Speaker=816772,}",
  [664487] = "{id=664487,Voice='Npc_Quest/664487',Text='最混乱的地方就是最安全的地方，无序则是有序……',Speaker=816772,}",
  [664488] = "{id=664488,Voice='Npc_Quest/664488',Text='我们要追求的答案在这个世界的边界——时空隙谷！',Speaker=816772,}",
  [664489] = "{id=664489,Voice='Npc_Quest/664489',Text='交给我，我会刺穿所有的诡计！',Speaker=816975,}",
  [664490] = "{id=664490,Voice='Npc_Quest/664490',Text='……喂——！说好的不能离开冒险者的身边啊！',Speaker=816772,}",
  [664491] = "{id=664491,Voice='Npc_Quest/664491',Text='刺穿所有诡计？真是天真，我们从来都身处于诡计之中，永远无法避开。',Speaker=816772,}",
  [664492] = "{id=664492,Voice='Npc_Quest/664492',Text='快去追上他吧，他做出任何的行为你都要为此负责，毕竟你可是他的担保人。',Speaker=816772,}",
  [664498] = "{id=664498,Voice='Npc_Quest/664498',Text='时空龙大人……您终于出现了！',Speaker=816878,}",
  [664499] = "{id=664499,Voice='Npc_Quest/664499',Text='集中精神！别让这些垃圾离开时空隙谷！',Speaker=816772,}",
  [664500] = "{id=664500,Voice='Npc_Quest/664500',Text='这里是天地树世界的边界，也是我最后的底线！',Speaker=816772,}",
  [664501] = "{id=664501,Voice='Npc_Quest/664501',Text='大人！原本沉寂的时空矩阵突然被一股强大的力量启动了！大量的时空垃圾通过时空矩阵侵入时空隙谷！',Speaker=816878,Option='时空矩阵？',}",
  [664502] = "{id=664502,Voice='Npc_Quest/664502',Text='没错，这是一种高级的空间连接法阵，是出逃者建立的。只是之前一直未被激活……',Speaker=816878,}",
  [664503] = "{id=664503,Voice='Npc_Quest/664503',Text='您也知道，我们苍翼卫的守望龙们并不多，这是我们观察多日得知的结论。',Speaker=816878,}",
  [664504] = "{id=664504,Voice='Npc_Quest/664504',Text='原来如此，原来这就是他的目的……',Speaker=816772,Option='{什么意思？,0},{原来如此……,0}',}",
  [664505] = "{id=664505,Voice='Npc_Quest/664505',Text='我的真身蕴含着时空之力，他利用了我的身体开启了时空矩阵。',Speaker=816772,}",
  [664506] = "{id=664506,Voice='Npc_Quest/664506',Text='要关闭时空矩阵，就需要关闭所有的时空之眼！',Speaker=816772,}",
  [664507] = "{id=664507,Voice='Npc_Quest/664507',Text='我们曾突破时空垃圾的阻拦，尝试关闭时空之眼，却被时空之眼上附着的力量击退。',Speaker=816878,}",
  [664508] = "{id=664508,Voice='Npc_Quest/664508',Text='那股力量甚至侵蚀了我们的同伴，让他们成为了时空垃圾的帮凶！',Speaker=816878,}",
  [664509] = "{id=664509,Voice='Npc_Quest/664509',Text='这下麻烦了……对于这股力量，我们一无所知。',Speaker=816772,}",
  [664510] = "{id=664510,Voice='Npc_Quest/664510',Text='我建议伪装成时空垃圾潜入矩阵，从而套取线索、找到关闭时空之眼的办法。',Speaker=816772,}",
  [664511] = "{id=664511,Voice='Npc_Quest/664511',Text='我并不认可这个提议，这是诡计。',Speaker=816975,}",
  [664512] = "{id=664512,Voice='Npc_Quest/664512',Text='不要这么说，这只是一种手段。总之，做这一切都是为了治愈天地树！',Speaker=816772,}",
  [664513] = "{id=664513,Voice='Npc_Quest/664513',Text='我会用自己的手段获取资料。',Speaker=816975,}",
  [664514] = "{id=664514,Voice='Npc_Quest/664514',Text='……谁允许他这个嫌疑人在犯罪现场随意进出的！！！阿诺！派人跟着他！！',Speaker=816772,}",
  [664515] = "{id=664515,Voice='Npc_Quest/664515',Text='伪装潜入一事就交给你了，冒险者，上前来。',Speaker=816772,}",
  [664516] = "{id=664516,Voice='Npc_Quest/664516',Text='这股能量可以让你的身上散发出时空乱流的气息，不会被那些时空垃圾发现。',Speaker=816772,}",
  [664517] = "{id=664517,Voice='Npc_Quest/664517',Text='需要注意，这只能维持有限的时间，请在能量持续时间内找到有用的线索。',Speaker=816772,}",
  [664518] = "{id=664518,Text='现在是很关键，打起精神来！如果破坏了那位大人的计划，你会没命的！',Speaker=816879,Option='{抱歉抱歉,0},{好好好,0}',}",
  [664519] = "{id=664519,Text='记住，不可以有任何偏差，一定不能让那些守护者们关闭时空之眼！',Speaker=816879,}",
  [664520] = "{id=664520,Text='对了，刚才的交战导致我们的武器都坏了！你去战场上回收一些还能用的武器回来吧！',Speaker=816879,}",
  [664521] = "{id=664521,Text='啊哈~已经开始期待深渊之湖和时空乱流回收站完全连接的样子了！',Speaker=816879,}",
  [664522] = "{id=664522,Text='我们将成为这个世界的主人！让这个世界的人成为真正的垃圾！',Speaker=816879,}",
  [664523] = "{id=664523,Text='干得漂亮！对了，你的坍缩器呢？不戴着坍缩器，时空矩阵只会要了你的命！',Speaker=816879,Option='我现在就去找回来',}",
  [664524] = "{id=664524,Text='站住！之前从未见过你！你该不会是……',Speaker=816879,Option='{咽口水……,0},{挤出笑脸,0}',}",
  [664525] = "{id=664525,Text='刚从时空乱流回收站逃出来的吧？？啊哈，所以你还不知道它的重要性。',Speaker=816879,}",
  [664526] = "{id=664526,Text='时空坍缩器很重要，你看，在我的腰间的那个就是！',Speaker=816879,Option='{明白了！,0},{现在归我了！ ,0}',}",
  [664527] = "{id=664527,Text='……可恶！你究竟是……什么东西……',Speaker=816879,}",
  [664528] = "{id=664528,Text='时空龙大人……',Speaker=816880,}",
  [664529] = "{id=664529,Text='时空龙大人……小心……是洛……',Speaker=816880,}",
  [664530] = "{id=664530,Text='共有四个时空之眼，时空隙谷的最深处弥漫着浓雾，似乎在掩盖着什么。',}",
  [664531] = "{id=664531,Text='在这里鬼鬼祟祟地想要做什么！？',Speaker=816881,}",
  [664532] = "{id=664532,Text='呜呜呜呜，你干嘛打我们……我们不是同伴吗？',Speaker=816888,Option='最深处有什么？',}",
  [664533] = "{id=664533,Text='这你都不知道？被带回来的巨龙！他被禁锢在时空矩阵最后一个超时空之眼中！',Speaker=816888,}",
  [664534] = "{id=664534,Text='只要再等一等，我们的愿望就能实现了！',Speaker=816888,}",
  [664535] = "{id=664535,Voice='Npc_Quest/664535',Text='为了节省时间，我要直接提取你的时间线获得信息。',Speaker=816772,}",
  [664536] = "{id=664536,Voice='Npc_Quest/664536',Text='你获得的信息与无名者是一致的，时空坍缩器上就蕴含着抵抗废气的能量。',Speaker=816772,Option='无名者如何获得信息？',}",
  [664537] = "{id=664537,Voice='Npc_Quest/664537',Text='……他通过在暗处观察，察觉到坍缩器的作用，并无声无息地从它们身上拿走了坍缩器。',Speaker=816772,Option='{不愧是第一刺客！,0},{厉害……,0}',}",
  [664538] = "{id=664538,Voice='Npc_Quest/664538',Text='另外，根据我对废气结构和坍缩器蕴含能量的解析，用足够多的坍缩器就可以关闭时空之眼！',Speaker=816772,}",
  [664539] = "{id=664539,Voice='Npc_Quest/664539',Text='明白了，我们即刻出发！',Speaker=816975,}",
  [664540] = "{id=664540,Voice='Npc_Quest/664540',Text='超时空坍缩器……大概率它可以用于关闭超时空之眼。',Speaker=816975,}",
  [664541] = "{id=664541,Voice='Npc_Quest/664541',Text='关闭全部的时空之眼后，带给时空龙检验。',Speaker=816975,}",
  [664542] = "{id=664542,Voice='Npc_Quest/664542',Text='你们猜测的没错，超时空坍缩器可以用于关闭超时空之眼！',Speaker=816772,}",
  [664543] = "{id=664543,Voice='Npc_Quest/664543',Text='就差最后一步了！现在，就前往时空隙谷的最深处！',Speaker=816772,}",
  [664546] = "{id=664546,Voice='Npc_Quest/664546',Text='它们在阻拦我们靠近超时空之眼！',Speaker=816975,}",
  [664547] = "{id=664547,Voice='Npc_Quest/664547',Text='加快速度！必须在时空彻底链接之前，阻止这一切！',Speaker=816975,}",
  [664548] = "{id=664548,Voice='Npc_Quest/664548',Text='出逃者就在附近！我感应到了他的存在！',Speaker=816772,}",
  [664549] = "{id=664549,Voice='Npc_Quest/664549',Text='小心！',Speaker=816772,}",
  [664550] = "{id=664550,Voice='Npc_Quest/664550',Text='是你们！破坏了我最完美的计划！',Speaker=816866,}",
  [664551] = "{id=664551,Voice='Npc_Quest/664551',Text='是他！所有的信息都比对上了！他就是出逃者！',Speaker=816772,}",
  [664552] = "{id=664552,Voice='Npc_Quest/664552',Text='时空的力量，将为我所用！',Speaker=816877,}",
  [664553] = "{id=664553,Voice='Npc_Quest/664553',Text='伪善的时空管理者，你有什么资格将我们囚禁！',Speaker=816877,}",
  [664554] = "{id=664554,Voice='Npc_Quest/664554',Text='时空有着它的准则，偏离正确轨道的一切都是错误！',Speaker=816772,}",
  [664555] = "{id=664555,Voice='Npc_Quest/664555',Text='我只是在维护时间线的平衡，割离错误才能让世界不会崩塌！',Speaker=816772,}",
  [664556] = "{id=664556,Voice='Npc_Quest/664556',Text='听听，这高高在上的姿态，真是令人作呕！',Speaker=816877,}",
  [664557] = "{id=664557,Voice='Npc_Quest/664557',Text='而我，就是要来告诉你们，没有任何生命天生就是垃圾！',Speaker=816877,}",
  [664558] = "{id=664558,Voice='Npc_Quest/664558',Text='哼哼……你们，不过是我诡计中的棋子！我精心为你们准备的礼物，你们还满意吗？',Speaker=816844,}",
  [664559] = "{id=664559,Voice='Npc_Quest/664559',Text='你所费劲心思找寻的东西不过是我随便写下的骗局，你渴望打开龙息之锁拿到原初之力，殊不知是被我利用找到时空龙的真身而已。',Speaker=816844,}",
  [664560] = "{id=664560,Voice='Npc_Quest/664560',Text='看看你们的嘴脸，真是可笑啊~这个世界根本不存在治愈天地树的方法！毁灭才是任何存在的宿命！',Speaker=816844,}",
  [664561] = "{id=664561,Voice='Npc_Quest/664561',Text='诡计终将被正义刺穿！',Speaker=816975,}",
  [664562] = "{id=664562,Voice='Npc_Quest/664562',Text='你们于这个世界而言是错误的存在，时空乱流回收站才是你们宿命的终点。',Speaker=816772,}",
  [664563] = "{id=664563,Voice='Npc_Quest/664563',Text='呵呵？回那个鬼地方？你瞧瞧我的样子，那里把我折磨得只剩下了半个影子！就连战斗也要通过操控他人完成，让我回去？你做梦！',Speaker=816844,}",
  [664564] = "{id=664564,Voice='Npc_Quest/664564',Text='我会摧毁一切，让这个世界服从我的秩序！',Speaker=816844,}",
  [664565] = "{id=664565,Voice='Npc_Quest/664565',Text='泰诺早已经死了。',Speaker=816975,}",
  [664566] = "{id=664566,Voice='Npc_Quest/664566',Text='不仅如此，泰诺的身体上已经无法找到与时空乱流回收站出逃者所对应的信息。',Speaker=816772,}",
  [664567] = "{id=664567,Voice='Npc_Quest/664567',Text='真正的出逃者是那枚手环，泰诺只是他选中的身体。只是那枚手环，与我拥有的这枚手环相似。',Speaker=816975,}",
  [664568] = "{id=664568,Voice='Npc_Quest/664568',Text='我在你的手环上感应到了神族的力量，这是来自神族的宝物。',Speaker=816772,}",
  [664569] = "{id=664569,Voice='Npc_Quest/664569',Text='那是不是意味着它也来自神族？',Speaker=816975,}",
  [664570] = "{id=664570,Voice='Npc_Quest/664570',Text='我只知道，每一件神族的宝物都有其独特的命运，它们的相遇并非偶然。',Speaker=816772,}",
  [664571] = "{id=664571,Voice='Npc_Quest/664571',Text='或许通过这两个手环，你能找到你所追求的真相。',Speaker=816772,}",
  [664572] = "{id=664572,Voice='Npc_Quest/664572',Text='我会找到它的！',Speaker=816975,}",
  [664573] = "{id=664573,Voice='Npc_Quest/664573',Text='但我必须提醒你，不要对过去过度追逐。记忆会困住你前行的脚步，并丢失主宰未来的决定权。',Speaker=816772,}",
  [664574] = "{id=664574,Voice='Npc_Quest/664574',Text='我会有自己的判断。',Speaker=816975,}",
  [664575] = "{id=664575,Voice='Npc_Quest/664575',Text='好了，现在至少我们知道了出逃者的目的，也恭喜你，洗清了嫌疑。',Speaker=816772,Option='{恭喜恭喜,0},{早就说不是他,0}',}",
  [664576] = "{id=664576,Voice='Npc_Quest/664576',Text='不过，很奇怪，所有的时空垃圾都有详细的资料记载，唯独这个出逃者无法找到任何资料。',Speaker=816772,}",
  [664577] = "{id=664577,Voice='Npc_Quest/664577',Text='我会继续追查此事。而眼下最重要的是获得龙族之星。',Speaker=816772,}",
  [664578] = "{id=664578,Voice='Npc_Quest/664578',Text='时间的动荡将我从沉眠中唤醒。',Speaker=816772,}",
  [664579] = "{id=664579,Voice='Npc_Quest/664579',Text='我已经看到了你们的勇气和智慧，我将把时空之星赐予你们。',Speaker=816772,}",
  [664580] = "{id=664580,Voice='Npc_Quest/664580',Text='希望你们不负重托，治愈天地树。',Speaker=816772,}",
  [664581] = "{id=664581,Voice='Npc_Quest/664581',Text='出逃者似乎并没有察觉我们已经找到了治愈天地树的办法。',Speaker=816975,}",
  [664582] = "{id=664582,Voice='Npc_Quest/664582',Text='听起来是的，所以你用魔法掩盖了天地树之芽已经得到部分治愈的真相。',Speaker=816772,}",
  [664583] = "{id=664583,Voice='Npc_Quest/664583',Text='没错，刚才的魔法足以让外界难以察觉天地树的变化。',Speaker=816975,}",
  [664584] = "{id=664584,Voice='Npc_Quest/664584',Text='就像出逃者当时也使用魔法让我们难以发现天地树枯萎的真实原因一样。',Speaker=816772,}",
  [664585] = "{id=664585,Voice='Npc_Quest/664585',Text='嗯……我痛恨诡计，但不得不使用它的诡计。',Speaker=816975,}",
  [664586] = "{id=664586,Voice='Npc_Quest/664586',Text='我说过，冒险之路会让你有所改变。总之，这并不是什么坏事情！',Speaker=816772,}",
  [664587] = "{id=664587,Voice='Npc_Quest/664587',Text='接下去你们还需要找到另外三颗龙族之星，它们分别为[c][ffff00]赤炎之星，黑炎之星，生命之星[-][/c]。',Speaker=816772,}",
  [664588] = "{id=664588,Voice='Npc_Quest/664588',Text='它们分别在[c][ffff00]赤炎龙蕾蒂西亚[-][/c]，[c][ffff00]黑炎龙参宿四[-][/c]和[c][ffff00]原初之龙尼德霍格[-][/c]的手中。',Speaker=816772,}",
  [664589] = "{id=664589,Voice='Npc_Quest/664589',Text='在时机合适的时候，我会指引你们前去找到他们。',Speaker=816772,}",
  [664590] = "{id=664590,Voice='Npc_Quest/664590',Text='无论如何请记住，你们做的每一件微小的事情，都将改变这个世界的命运。',Speaker=816772,}",
  [664591] = "{id=664591,Voice='Npc_Quest/664591',Text='而前路，我仍然会以分身帮助你们完成使命。再见了！我将再次沉眠。',Speaker=816772,}",
  [664612] = "{id=664612,Text='请等一下！奥斯卡，我认识他，他不会是出逃者！',}",
  [664614] = "{id=664614,Text='无名者？',}",
  [664615] = "{id=664615,Voice='Npc_Quest/664615',Text='冒险者？',Speaker=816975,}",
  [664616] = "{id=664616,Voice='Npc_Quest/664616',Text='这就是我的选择。',Speaker=816975,}",
  [664618] = "{id=664618,Text='净化之水已经涂抹在各位的武器上了。',Speaker=827519,}",
  [664619] = "{id=664619,Text='这就是时空乱流站的入口吗？',}",
  [664620] = "{id=664620,Voice='Npc_Quest/664620',Text='是的，但是入口的状态似乎不是很稳定。',Speaker=816772,}",
  [664621] = "{id=664621,Voice='Npc_Quest/664621',Text='混乱的时间裂隙已经被我抑制住了，冒险者快趁现在离开吧，我随后就会赶到！',Speaker=816772,}",
  [664622] = "{id=664622,Voice='Npc_Quest/664622',Text='呼——赤炎龙脑子里那天真的想法暂且放在一边，现在更重要的事是尽快找到火之龙。',Speaker=816772,}",
  [664623] = "{id=664623,Voice='Npc_Quest/664623',Text='经过刚才的交战，那家伙更加失控了！再由他这么疯下去，天地树恐怕要完蛋了！',Speaker=816772,}",
  [664624] = "{id=664624,Voice='Npc_Quest/664624',Text='跟随这些脚印就能找到它，不过要小心避开岩浆脚印，否则将会被灼伤。',Speaker=816772,}",
  [664625] = "{id=664625,Voice='Npc_Quest/664625',Text='谢谢您，谢谢神族的指引。',Speaker=816893,}",
  [664626] = "{id=664626,Voice='Npc_Quest/664626',Text='你们去打开龙息之锁！这里交给我！快去！龙族子民与天地树对我而言都是最珍贵的存在！',Speaker=816866,}",
  [664636] = "{id=664636,Text='………………',}",
  [664637] = "{id=664637,Text='疾风之息对燃烧天地树的火起作用了。',Speaker=816772,}",
  [664638] = "{id=664638,Text='大地之息对燃烧天地树的火起作用了。',Speaker=816772,}",
  [664639] = "{id=664639,Text='潮汐之息对燃烧天地树的火起作用了。',Speaker=816772,}",
  [664649] = "{id=664649,Text='时空巨龙正在穿越错乱的时间线，未知的异时空魔物将如潮水一般涌来！',Speaker=851062,}",
  [664650] = "{id=664650,Text='是否直面魔潮？',Speaker=851062,Option='{准备好了,11},{再等一下,12}',}",
  [664651] = "{id=664651,Text='是否超越极限，提前召唤下一波魔物？',Speaker=851062,Option='{准备好了,11},{再想想,12}',}",
  [664655] = "{id=664655,Text='这是哪里？我为什么在这儿……',Speaker=30072,}",
  [664656] = "{id=664656,Text='赤炎龙大人的椅子以前会发光的！可是现在它暗啦……西尔芙想用亮晶晶贴纸帮它补一补！',Speaker=851063,}",
  [664657] = "{id=664657,Text='蕾蒂西亚女王喷的赤火火很厉害的！但现在像生病了一样，带着黑点点……阿嚏！黑点点好呛噢……',Speaker=851063,}",
  [664658] = "{id=664658,Text='咦？西尔芙在墙缝里找到一片红龙鳞和一片黑龙鳞！它们本来是一对吗？可是怎么也贴不到一块去……是不是他们吵架啦？',Speaker=851063,}",
  [664659] = "{id=664659,Text='哇哇哇！这里有个会‘嗖——’一下把东西吃掉的大门！西尔芙的发卡被它吸走啦！好可怕……',Speaker=851063,}",
  [664660] = "{id=664660,Text='西尔芙在用藤蔓编蝴蝶结！我想挂在门口，这样大家路过就会停下来拍照打卡啦~嘻嘻~',Speaker=851063,}",
  [664661] = "{id=664661,Text='赤炎龙大人养伤的时候总是念叨：“大人，我会遵从您的旨意……”可是那个“大人”是谁呀？西尔芙看不见~',Speaker=851063,}",
  [664663] = "{id=664663,Text='女王的侍女姐姐以前会请西尔芙喝赤果果汁！后来她眼睛变蓝蓝的，果汁也变苦苦的……西尔芙不喜欢了~',Speaker=851063,}",
  [664665] = "{id=664665,Text='呜呜……这里的果果不能吃啦！吃了肚子会咕噜咕噜叫痛痛~啊啊……以后再也不来无相沼泽啦……（捂住嘴）啊！不会被黑炎龙大人听见吧？！',Speaker=851063,}",
  [664667] = "{id=664667,Text='嘘——偷偷告诉你一个大秘密哦！黑炎龙大人收藏了好多奇怪的东西！比如能定住时间裂隙，比如会吃人魂的花，锁住灵魂的链子！！超吓人的！',Speaker=851063,}",
  [664668] = "{id=664668,Text='睡不着的时候，西尔芙喜欢数一数有多少个暗爪营战士……咦？以前只有十个指头就够数了，现在要掰脚趾都数不完啦！暗爪营的龙战士多了很多耶……',Speaker=851063,}",
  [664669] = "{id=664669,Text='西尔芙在躲猫猫呢！可那些路过的龙战士都不愿意陪我玩……他们的眼神好凶，和以前的龙战士一点儿都不一样……',Speaker=851063,}",
  [664670] = "{id=664670,Text='哗啦哗啦~风一吹，芦苇就唱歌啦！好像是在唱给那些躺在地下的白骨听……它们也想站起来跳舞吗？',Speaker=851063,}",
  [664671] = "{id=664671,Text='西尔芙看到黑炎龙大人笑了！可是那不是开心的笑容……那是看着敌人痛苦时才会有的笑……好可怕……',Speaker=851063,}",
  [664672] = "{id=664672,Text='咦？塔顶有个亮晶晶的小光点在闪呀~是不是有人躲在最高处偷看我们？快藏起来！',Speaker=851063,}",
  [664674] = "{id=664674,Text='咦？这里有一个小窝窝！是不是曾经有小龙住过？我还发现了一片小小的黑龙鳞……难道是黑炎龙小时候住过的地方？！',Speaker=851063,}",
  [664676] = "{id=664676,Text='咻咻咻~风从地底吹出来啦！里面好像还带着一点点火焰的味道……是要打仗了吗？还是……有龙在里面烤鱼？',Speaker=851063,}",
  [664677] = "{id=664677,Text='是超级海蝴蝶！没想到它竟然守在这，看来只有先击败它才能解除总控室的屏障了。',Speaker=842635,}",
  [664678] = "{id=664678,Text='不好！天鹰座开始充能了！冒险者，尽快击败超级海蝴蝶吧。',Speaker=842635,}",
  [664679] = "{id=664679,Text='太好了！冒险者，快去关闭总控室的屏障吧！',Speaker=842635,}",
  [664680] = "{id=664680,Text='成功了！只要击败天鹰座，就能破坏这艘飞空艇了。',Speaker=842635,}",
  [664681] = "{id=664681,Text='是天鹰座！拜托了，冒险者，摧毁它吧，解放伊斯加尔特的所有人！',Speaker=842635,}",
  [664682] = "{id=664682,Text='天鹰座充能进度……10%',Speaker=276570,}",
  [664683] = "{id=664683,Text='天鹰座充能进度……20%',Speaker=276570,}",
  [664684] = "{id=664684,Text='天鹰座充能进度……30%',Speaker=276570,}",
  [664685] = "{id=664685,Text='天鹰座充能进度……40%',Speaker=276570,}",
  [664686] = "{id=664686,Text='天鹰座充能进度……50%',Speaker=276570,}",
  [664687] = "{id=664687,Text='天鹰座充能进度……60%',Speaker=276570,}",
  [664688] = "{id=664688,Text='天鹰座充能进度……70%',Speaker=276570,}",
  [664689] = "{id=664689,Text='天鹰座充能进度……80%',Speaker=276570,}",
  [664690] = "{id=664690,Text='天鹰座充能进度……90%',Speaker=276570,}",
  [664691] = "{id=664691,Text='天鹰座充能进度……100%，切换为攻击模式！',Speaker=276570,}",
  [664692] = "{id=664692,Text='好耶！我们成功打断了它的技能！',}",
  [664693] = "{id=664693,Text='它在治愈自己，趁机攻击它！',}",
  [664694] = "{id=664694,Text='它在释放一个看起来很厉害的技能，快全力攻击打断它！',}",
  [664695] = "{id=664695,Text='太阳，注视着我',Speaker=277031,}",
  [664696] = "{id=664696,Text='为了友情的牺牲，是对太阳献上的最大供奉',Speaker=277031,}",
  [664697] = "{id=664697,Text='过分依赖外界的力量可不好',Speaker=277031,}",
  [664698] = "{id=664698,Text='其实，护盾这种东西是可以随便抢走的',Speaker=277031,}",
  [664699] = "{id=664699,Text='让我看看你们的友情',Speaker=277031,}",
  [664700] = "{id=664700,Text='闯入者，无处可逃！',Speaker=277030,}",
  [664701] = "{id=664701,Text='我的神明在此！',Speaker=277030,}",
  [664702] = "{id=664702,Text='燃尽吧！',Speaker=277030,}",
  [664703] = "{id=664703,Text='吾乃玛特的代行者！',Speaker=277030,}",
  [664704] = "{id=664704,Text='我来增强守护者！',Speaker=277036,}",
  [664705] = "{id=664705,Text='触碰神的人会受到诅咒',Speaker=277031,}",
  [664706] = "{id=664706,Text='刚刚..似乎有点危险？',Speaker=277031,}",
  [664707] = "{id=664707,Text='好险好险，差点就被你们抓到机会了呢',Speaker=277030,}",
  [664708] = "{id=664708,Text='居然被自己的神力给攻击了，真是难看',Speaker=277030,}",
  [664709] = "{id=664709,Text='竟然用封印来玷污神座……奇耻大辱',Speaker=277031,}",
  [664710] = "{id=664710,Text='美~丽~冻~人~',Speaker=277039,}",
  [664711] = "{id=664711,Text='靠近我就会被冻住哦',Speaker=277039,}",
  [664712] = "{id=664712,Text='来自冥府的气息你受得了吗',Speaker=277039,}"
}
Table_Dialog_Left_44.count = 2001
